    /**
     * Paper runs the modern attempt event and the deprecated compatibility
     * event before it creates EntityPickupItemEvent.  A protection plugin
     * cancelling either earlier event otherwise prevents our final owner
     * policy from ever seeing the reward.  Keep all three stages aligned.
     */
    @EventHandler(priority = EventPriority.HIGHEST, ignoreCancelled = false)
    public void onWaveRewardAttemptPickup(PlayerAttemptPickupItemEvent event) {
        Player player = event.getPlayer();
        Item item = event.getItem();
        if (!isWaveRewardItem(item)) {
            logUntaggedWaveRewardPickup(player, item, event.isCancelled(), "attempt");
            return;
        }
        event.setCancelled(!allowWaveRewardPickup(player, item, "attempt"));
    }

    /**
     * Re-apply the event-owned decision after every other plugin listener.
     * Some server protection listeners run at the same priority and may
     * cancel an otherwise valid pickup after the normal HIGHEST pass.
     */
    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = false)
    public void onWaveRewardAttemptPickupFinal(PlayerAttemptPickupItemEvent event) {
        Player player = event.getPlayer();
        Item item = event.getItem();
        if (!isWaveRewardItem(item)) {
            return;
        }
        event.setCancelled(!allowWaveRewardPickup(player, item, "attempt-final"));
    }

    @EventHandler(priority = EventPriority.HIGHEST, ignoreCancelled = false)
    public void onWaveRewardPickup(EntityPickupItemEvent event) {
        if (!(event.getEntity() instanceof Player player)) {
            return;
        }
        Item item = event.getItem();
        if (!isWaveRewardItem(item)) {
            logUntaggedWaveRewardPickup(player, item, event.isCancelled(), "entity");
            return;
        }
        event.setCancelled(!allowWaveRewardPickup(player, item, "entity"));
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = false)
    public void onWaveRewardPickupFinal(EntityPickupItemEvent event) {
        if (!(event.getEntity() instanceof Player player)) {
            return;
        }
        Item item = event.getItem();
        if (!isWaveRewardItem(item)) {
            return;
        }
        event.setCancelled(!allowWaveRewardPickup(player, item, "entity-final"));
    }

    private boolean isWaveRewardItem(Item item) {
        return item != null
                && EVENT_KIND_WAVE_REWARD.equals(readString(item, keyKind))
                && ownedByEvent(item, eventId);
    }

    private void logUntaggedWaveRewardPickup(Player player, Item item, boolean cancelled, String stage) {
        if (player == null || item == null) {
            return;
        }
        ItemStack stack = item.getItemStack();
        String stackOwnerText = "";
        if (stack != null && stack.hasItemMeta()) {
            stackOwnerText = stack.getItemMeta().getPersistentDataContainer().getOrDefault(
                    keyRewardStackOwner, PersistentDataType.STRING, "");
        }
        if (!stackOwnerText.isBlank()) {
            getLogger().warning("WAVE_REWARD_PICKUP_EVENT_UNTAGGED event=" + eventId
                    + " stage=" + stage + " player=" + player.getUniqueId()
                    + " stack_owner=" + stackOwnerText + " cancelled_before=" + cancelled);
        }
    }

    private boolean allowWaveRewardPickup(Player player, Item item, String stage) {
        if (player == null || item == null) {
            return false;
        }
        ItemStack stack = item.getItemStack();
        String stackOwnerText = "";
        if (stack != null && stack.hasItemMeta()) {
            stackOwnerText = stack.getItemMeta().getPersistentDataContainer().getOrDefault(
                    keyRewardStackOwner, PersistentDataType.STRING, "");
        }
        PersistentDataContainer data = item.getPersistentDataContainer();
        boolean shared = data.getOrDefault(keyRewardShared, PersistentDataType.BYTE, (byte) 0) == (byte) 1;
        long expiresAt = data.getOrDefault(keyRewardExpiresAt, PersistentDataType.LONG, 0L);
        String ownerText = data.getOrDefault(keyRewardOwner, PersistentDataType.STRING, "");
        boolean ownerMatches = player.getUniqueId().toString().equals(ownerText)
                || player.getUniqueId().toString().equals(stackOwnerText);
        boolean ownerRestricted = !shared && expiresAt > System.currentTimeMillis();
        if (ownerRestricted && !ownerMatches) {
            getLogger().info("WAVE_REWARD_PICKUP_BLOCKED event=" + eventId
                    + " stage=" + stage + " player=" + player.getUniqueId()
                    + " owner=" + ownerText + " stack_owner=" + stackOwnerText
                    + " material=" + (stack == null ? "unknown" : stack.getType().getKey()));
            player.sendActionBar(Component.text("Эта награда временно предназначена другому участнику",
                    NamedTextColor.YELLOW));
            return false;
        }
        getLogger().info("WAVE_REWARD_PICKUP_ALLOWED event=" + eventId
                + " stage=" + stage + " player=" + player.getUniqueId()
                + " owner=" + ownerText + " stack_owner=" + stackOwnerText
                + " shared=" + shared + " material="
                + (stack == null ? "unknown" : stack.getType().getKey()));
        return true;
    }

    private boolean shouldTraceCombat(EntityDamageEvent event) {
        if (!combatTraceEnabled || event == null) {
            return false;
        }
        Entity victim = event.getEntity();
        if (victim instanceof LivingEntity living
                && (EVENT_KIND_BOSS.equals(readString(living, keyKind))
                || isWaveCombatKind(readString(living, keyKind)))) {
            return true;
        }
        if (!(victim instanceof Player)) {
            return false;
        }
        if (!(event instanceof EntityDamageByEntityEvent byEntity)) {
            return false;
        }
        Entity damager = byEntity.getDamager();
        if (damager instanceof LivingEntity living) {
            return EVENT_KIND_BOSS.equals(readString(living, keyKind))
                    || isWaveCombatKind(readString(living, keyKind));
        }
        return isEventArrow(damager) || isRiftFireball(damager);
    }

    @EventHandler(priority = EventPriority.LOWEST, ignoreCancelled = false)
    public void onCombatTraceOpen(EntityDamageEvent event) {
        if (!shouldTraceCombat(event) || !(event.getEntity() instanceof LivingEntity victim)) {
            return;
        }
        Entity source = event instanceof EntityDamageByEntityEvent byEntity ? byEntity.getDamager() : null;
        UUID attackerId = source instanceof org.bukkit.entity.Projectile projectile
                && projectile.getShooter() instanceof Entity shooter ? shooter.getUniqueId()
                : source == null ? null : source.getUniqueId();
        String attackerKind = source instanceof org.bukkit.entity.Projectile projectile
                && projectile.getShooter() instanceof Entity shooter
                ? projectile.getType() + ":" + shooter.getType()
                : source == null ? "ENVIRONMENT" : source.getType().name();
        boolean shielded = EVENT_KIND_BOSS.equals(readString(victim, keyKind))
                && !BossDamagePolicy.damageAllowed(bossPhase,
                bossDefeatCinematicStarted
                        ? BossPhasePolicy.DamageImmunityReason.BOSS_CINEMATIC
                        : BossPhasePolicy.DamageImmunityReason.NONE);
        CombatTraceRecord trace = CombatTraceRecord.open(
                Bukkit.getCurrentTick(), System.currentTimeMillis(), attackerId, victim.getUniqueId(),
                attackerKind, event.getCause().name(), event.getDamage(), event.getFinalDamage(),
                event.isCancelled(), victim.getNoDamageTicks(), victim.getMaximumNoDamageTicks(),
                victim.getLastDamage(), victim.getHealth(), phase, bossAbilityState, shielded,
                Bukkit.getServer().getAverageTickTime());
        pendingCombatTraces.put(event, trace);
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = false)
    public void onCombatTraceClose(EntityDamageEvent event) {
        CombatTraceRecord opened = pendingCombatTraces.remove(event);
        if (opened == null || !(event.getEntity() instanceof LivingEntity victim)) {
            return;
        }
        boolean cancelledAfter = event.isCancelled();
        Bukkit.getScheduler().runTask(this, () -> {
            double nextTickHealth = victim.isValid() && !victim.isDead() ? victim.getHealth() : 0.0D;
            CombatTraceRecord closed = opened.close(cancelledAfter, nextTickHealth);
            combatTrace.record(closed);
            getLogger().info(closed.toLogLine());
        });
    }

    @EventHandler(priority = EventPriority.HIGHEST, ignoreCancelled = false)
    public void onCoreOverlayDamage(EntityDamageByEntityEvent event) {
        Entity entity = event.getEntity();
        if (!(event.getDamager() instanceof Player player)
                || !(entity instanceof ItemDisplay display)
                || !isConfigured()) {
            return;
        }
        World world = Bukkit.getWorld(worldName);
        Block core = world == null ? null : world.getBlockAt(coreX, coreY, coreZ);
        if (!sameCoreOverlayBlock(display, core)) {
            return;
        }
        event.setCancelled(true);
        if (player.isOp() || isAdmin(player)) {
            openCoreRemovalConfirm(player);
        } else {
            player.sendActionBar(Component.text(
                    "Ядро защищено: снять его может только администратор", NamedTextColor.RED));
        }
    }

    /**
     * Display entities are not attackable on every Paper build, even when
     * their damage event is enabled.  A real left click still produces an arm
     * swing, so use the player's server-side ray-traced block as a fallback.
     * This keeps the Core clickable without making the overlay itself a
     * breakable entity or trusting client-supplied coordinates.
     */
    @EventHandler(priority = EventPriority.HIGHEST, ignoreCancelled = false)
    public void onCoreOverlayAnimation(PlayerAnimationEvent event) {
        Player player = event.getPlayer();
        if (player == null || !isConfigured()) {
            return;
        }
        Block target = player.getTargetBlockExact(8);
        // When the crosshair is on the display shell, Bukkit may report the
        // air block immediately above the real Core instead of the Core
        // block itself.  Accept only that exact Core column; never trust a
        // client-supplied coordinate.
        if (target == null || (!sameCore(target) && !isCoreBlockPosition(target.getLocation()))) {
            return;
        }
        if (player.isOp() || isAdmin(player)) {
            openCoreRemovalConfirm(player);
        } else {
            player.sendActionBar(Component.text(
                    "Ядро защищено: снять его может только администратор", NamedTextColor.RED));
        }
    }

    @EventHandler(priority = EventPriority.HIGHEST, ignoreCancelled = false)
    public void onOwnedDisplayDamage(EntityDamageEvent event) {
        Entity entity = event.getEntity();
        if (entity instanceof TextDisplay || entity instanceof ItemDisplay
                || entity instanceof BlockDisplay) {
            String kind = readString(entity, keyKind);
            if (ownedEntities.containsKey(entity.getUniqueId())
                    && (EVENT_KIND_DISPLAY.equals(kind) || EVENT_KIND_MEMORIAL.equals(kind)
                    || EVENT_KIND_CORE.equals(kind)
                    || EVENT_KIND_PAD.equals(kind)
                    || EVENT_KIND_TENTACLE.equals(kind)
                    || EVENT_KIND_WAVE4_OBELISK.equals(kind))) {
                event.setCancelled(true);
            }
        }
    }

    /**
     * Permanent tentacle visuals are ItemDisplays, so they cannot own Bukkit
     * health.  Their invisible Interaction companion is the only damageable
     * surface.  Every accepted hit is reduced against the slot ledger on the
     * main thread; the display remains a visual carrier and can never become
     * the source of an accidental vanilla damage transaction.
     */
    @EventHandler(priority = EventPriority.HIGHEST, ignoreCancelled = false)
    public void onTentacleGuardianDamage(EntityDamageByEntityEvent event) {
        if (!(event.getEntity() instanceof Interaction hitbox)
                || event.isCancelled()) {
            return;
        }
        UUID displayId = tentacleDisplaysByHitbox.get(hitbox.getUniqueId());
        if (displayId == null && keyTentacleDisplay != null) {
            String raw = readString(hitbox, keyTentacleDisplay);
            if (!raw.isBlank()) {
                try {
                    displayId = UUID.fromString(raw);
                } catch (IllegalArgumentException ignored) {
                    displayId = null;
                }
            }
        }
        Entity displayEntity = displayId == null ? null : ownedEntities.get(displayId);
        if (!(displayEntity instanceof ItemDisplay display)
                || !EVENT_KIND_TENTACLE.equals(readString(display, keyKind))) {
            return;
        }
        // The Interaction is event-owned even when the attacker is invalid.
        // Cancel first so swords, arrows and explosions can never damage the
        // invisible entity or make it disappear through vanilla health.
        event.setCancelled(true);
        if (!(event.getDamager() instanceof Player attacker)
                || !isActiveBossParticipant(attacker)
                || phase != EventPhase.BOSS_ACTIVE
                || bossPhase != BossPhase.LAST_SEAL
                || tentacleController.state(display.getUniqueId()) == null) {
            return;
        }
        applyTentacleGuardianDamage(display, Math.max(0.0D,
                Math.max(event.getFinalDamage(), event.getDamage())), attacker);
    }

    @EventHandler(priority = EventPriority.HIGHEST, ignoreCancelled = false)
    public void onArenaPlayerDamage(EntityDamageByEntityEvent event) {
        if (!(event.getEntity() instanceof Player victim) || !(event.getDamager() instanceof Player attacker)
                || phase == EventPhase.UNLOCKED) {
            return;
        }
        if (isArenaLocation(victim.getLocation()) && isArenaLocation(attacker.getLocation())
                && victim.getWorld().equals(attacker.getWorld())) {
            event.setCancelled(true);
        }
    }

    /**
     * Vanilla skeletons can acquire animals and other monsters as targets.
     * Event skeletons are explicitly player-only: every target transition is
     * checked here and the controller rechecks it before every shot.
     */
    @EventHandler(priority = EventPriority.HIGHEST, ignoreCancelled = false)
    public void onEventSkeletonTarget(EntityTargetLivingEntityEvent event) {
        if (!(event.getEntity() instanceof Skeleton skeleton) || !isEventSkeleton(skeleton)) {
            return;
        }
        LivingEntity target = event.getTarget();
        if (target == null) {
            skeleton.setTarget(null);
            return;
        }
        if (!(target instanceof Player player)
                || !SkeletonCombatPolicy.canTargetPlayersOnly("PLAYER", isCombatTarget(player))
                || !realitySplitTargetAllowed(skeleton, player)) {
            event.setCancelled(true);
            skeleton.setTarget(null);
            getLogger().info("SKELETON_TARGET_BLOCKED entity=" + skeleton.getUniqueId()
                    + " target=" + (target == null ? "none" : target.getType())
                    + " reason=PLAYER_ONLY");
            return;
        }
        if (isOfficialCurrentAttempt() && activeWave == 6
                && isCurrentCollapseGuard(skeleton)
                && !currentCollapseTargetAllowed(skeleton, player)) {
            event.setCancelled(true);
            skeleton.setTarget(null);
            getLogger().info("WAVE6_TARGET_BLOCKED entity=" + skeleton.getUniqueId()
                    + " target=" + player.getUniqueId());
            return;
        }
        skeleton.setTarget(player);
    }

    /** Keep the current Collapse Rings guard targeting bounded between ticks. */
    @EventHandler(priority = EventPriority.HIGHEST, ignoreCancelled = false)
    public void onCollapseRingRoleTarget(EntityTargetLivingEntityEvent event) {
        Entity source = event.getEntity();
        if (!isOfficialCurrentAttempt() || activeWave != 6
                || !isCurrentCollapseGuard(source)) {
            return;
        }
        LivingEntity target = event.getTarget();
        if (target instanceof Player player && currentCollapseTargetAllowed(source, player)) {
            return;
        }
        event.setCancelled(true);
        if (source instanceof Mob mob) {
            mob.setTarget(null);
        }
        getLogger().info("WAVE6_TARGET_BLOCKED entity=" + source.getUniqueId()
                + " target=" + (target == null ? "none" : target.getType()));
    }

    /** Tag every ordinary skeleton arrow so its trail and cleanup are bounded. */
    @EventHandler(priority = EventPriority.HIGHEST, ignoreCancelled = true)
    public void onEventSkeletonShootBow(EntityShootBowEvent event) {
        if (!(event.getEntity() instanceof Skeleton skeleton) || !isEventSkeleton(skeleton)
                || !(event.getProjectile() instanceof Arrow arrow)) {
            return;
        }
        boolean miniBoss = isSkeletonMiniBoss(skeleton);
        SkeletonCombatPolicy.ArrowProfile profile = SkeletonCombatPolicy.arrowProfile(miniBoss);
        long now = System.currentTimeMillis();
        long nextAllowed = nextSkeletonArrowMillis.getOrDefault(skeleton.getUniqueId(), 0L);
        if (now < nextAllowed) {
            event.setCancelled(true);
            if (arrow.isValid() && !arrow.isDead()) {
                arrow.remove();
            }
            getLogger().info("SKELETON_ARROW_COOLDOWN_BLOCKED entity=" + skeleton.getUniqueId()
                    + " variant=" + (miniBoss ? "MINIBOSS" : "COMMON")
                    + " retry_ms=" + (nextAllowed - now)
                    + " cooldown_ticks=" + profile.cooldownTicks());
            return;
        }
        nextSkeletonArrowMillis.put(skeleton.getUniqueId(),
                now + profile.cooldownTicks() * 50L);
        tag(arrow, EVENT_KIND_PROJECTILE, readInt(skeleton, keyWave, 0), isOfficialEntity(skeleton));
        SkeletonArrowPolicy.ArrowKind arrowKind = SkeletonArrowPolicy.forShot(
                miniBoss, random.nextLong());
        String arrowSpell = switch (arrowKind) {
            case EXPLOSIVE -> ARROW_SPELL_EXPLOSIVE;
            case POISON_NAUSEA -> ARROW_SPELL_POISON_NAUSEA;
            case COMMON -> ARROW_SPELL_SKELETON;
        };
        tagArrowSpell(arrow, arrowSpell);
        arrow.setDamage(profile.damage());
        arrow.setCritical(true);
        arrow.setPickupStatus(AbstractArrow.PickupStatus.DISALLOWED);
        arrow.setColor(switch (arrowKind) {
            case EXPLOSIVE -> Color.fromRGB(255, 72, 28);
            case POISON_NAUSEA -> Color.fromRGB(122, 255, 72);
            case COMMON -> Color.fromRGB(228, 228, 198);
        });
        trackEventArrow(arrow);
        getLogger().info("SKELETON_ARROW_SHOT entity=" + skeleton.getUniqueId()
                + " arrow=" + arrow.getUniqueId() + " variant=" + (miniBoss ? "MINIBOSS" : "COMMON")
                + " target=PLAYER_ONLY damage=" + profile.damage()
                + " spell=" + arrowSpell + " trail=" + profile.particlePattern());
    }

    /** Ordinary skeleton arrows may hurt eligible players, never event mobs. */
    @EventHandler(priority = EventPriority.HIGHEST, ignoreCancelled = false)
    public void onEventSkeletonArrowDamage(EntityDamageByEntityEvent event) {
        if (!(event.getDamager() instanceof Arrow arrow)
                || !(arrow.getShooter() instanceof Skeleton skeleton)
                || !isEventSkeleton(skeleton) || !isEventArrow(arrow)) {
            return;
        }
        String spell = readString(arrow, keyArrowSpell);
        if (ARROW_SPELL_EXPLOSIVE.equals(spell)) {
            event.setCancelled(true);
            if (!(event.getEntity() instanceof Player player) || !isCombatTarget(player)
                    || !realitySplitTargetAllowed(skeleton, player)) {
                cleanupEventArrow(arrow.getUniqueId());
                getLogger().info("SKELETON_EXPLOSIVE_ARROW_BLOCKED event=" + eventId
                        + " arrow=" + arrow.getUniqueId() + " target="
                        + event.getEntity().getType() + " reason=player-only-or-room");
                return;
            }
            detonateExplosiveArrow(arrow, event.getEntity().getLocation());
            return;
        }
        if (ARROW_SPELL_POISON_NAUSEA.equals(spell)) {
            if (!(event.getEntity() instanceof Player player) || !isCombatTarget(player)
                    || !realitySplitTargetAllowed(skeleton, player)) {
                event.setCancelled(true);
                getLogger().info("SKELETON_ARROW_NON_PLAYER_BLOCKED arrow=" + arrow.getUniqueId()
                        + " spell=" + spell + " target=" + event.getEntity().getType());
                cleanupEventArrow(arrow.getUniqueId());
                return;
            }
            if (statusArrowEffectsApplied.add(arrow.getUniqueId())) {
                player.addPotionEffect(new PotionEffect(PotionEffectType.POISON,
                        SkeletonArrowPolicy.STATUS_DURATION_TICKS,
                        SkeletonArrowPolicy.STATUS_AMPLIFIER, false, true, true));
                player.addPotionEffect(new PotionEffect(PotionEffectType.NAUSEA,
                        SkeletonArrowPolicy.STATUS_DURATION_TICKS,
                        SkeletonArrowPolicy.STATUS_AMPLIFIER, false, true, true));
                getLogger().info("SKELETON_ARROW_STATUS_HIT arrow=" + arrow.getUniqueId()
                        + " shooter=" + skeleton.getUniqueId() + " target=" + player.getUniqueId()
                        + " poison_nausea_level=III duration_ticks="
                        + SkeletonArrowPolicy.STATUS_DURATION_TICKS);
            }
            return;
        }
        if (!ARROW_SPELL_SKELETON.equals(spell)) {
            onCustomEventArrowDamage(event, arrow, spell);
            return;
        }
        if (!(event.getEntity() instanceof Player player) || !isCombatTarget(player)
                || !realitySplitTargetAllowed(skeleton, player)) {
            event.setCancelled(true);
            getLogger().info("SKELETON_ARROW_NON_PLAYER_BLOCKED arrow=" + arrow.getUniqueId()
                    + " target=" + event.getEntity().getType());
            cleanupEventArrow(arrow.getUniqueId());
            return;
        }
        getLogger().info("SKELETON_ARROW_PLAYER_HIT arrow=" + arrow.getUniqueId()
                + " shooter=" + skeleton.getUniqueId() + " target=" + player.getUniqueId()
                + " damage=" + event.getFinalDamage());
    }

    /** Boss and miniboss spell arrows use one authoritative player-only hit. */
    @EventHandler(priority = EventPriority.HIGHEST, ignoreCancelled = false)
    public void onCustomEventArrowDamage(EntityDamageByEntityEvent event) {
        if (!(event.getDamager() instanceof Arrow arrow) || !isEventArrow(arrow)) {
            return;
        }
        if (arrow.getShooter() instanceof Skeleton skeleton && isEventSkeleton(skeleton)) {
            // The skeleton-specific handler owns common, status and explosive
            // payloads.  Returning here prevents two listeners from applying
            // the same status or damage when Bukkit dispatches equal-priority
            // handlers in a different registration order.
            return;
        }
        String spell = readString(arrow, keyArrowSpell);
        if (ARROW_SPELL_SKELETON.equals(spell)
                || ARROW_SPELL_POISON_NAUSEA.equals(spell)
                || ARROW_SPELL_EXPLOSIVE.equals(spell)) {
            return;
        }
        onCustomEventArrowDamage(event, arrow, spell);
    }

    private void onCustomEventArrowDamage(EntityDamageByEntityEvent event, Arrow arrow, String spell) {
        boolean alreadyCancelled = event.isCancelled();
        if (alreadyCancelled) {
            cleanupEventArrow(arrow.getUniqueId());
            return;
        }
        event.setCancelled(true);
        if (!(event.getEntity() instanceof Player player) || !isCombatTarget(player)) {
            cleanupEventArrow(arrow.getUniqueId());
            getLogger().info("EVENT_ARROW_NON_PLAYER_BLOCKED arrow=" + arrow.getUniqueId()
                    + " spell=" + spell + " target=" + event.getEntity().getType());
            return;
        }
        LivingEntity shooter = arrow.getShooter() instanceof LivingEntity living ? living : null;
        if (shooter != null && isChamberWaveEntity(shooter)
                && !realitySplitTargetAllowed(shooter, player)) {
            cleanupEventArrow(arrow.getUniqueId());
            getLogger().info("WAVE_7_ARROW_CROSS_ROOM_BLOCKED event=" + eventId
                    + " arrow=" + arrow.getUniqueId() + " shooter=" + shooter.getUniqueId()
                    + " target=" + player.getUniqueId());
            return;
        }
        boolean miniBoss = EndRiftAiPolicy.MiniBossSpell.ARROW_SALVO.id().equals(spell);
        double damage = miniBoss ? SkeletonCombatPolicy.arrowProfile(true).damage()
                : BOSS_PROJECTILE_DAMAGE;
        if (shooter != null && shooter.isValid() && !shooter.isDead()) {
            player.damage(damage, shooter);
        } else {
            player.damage(damage);
        }
        int debuffTicks = miniBoss ? SLOWNESS_DEBUFF_TICKS : BOSS_PROJECTILE_DEBUFF_TICKS;
        player.addPotionEffect(new PotionEffect(PotionEffectType.SLOWNESS,
                debuffTicks, abilityDebuffAmplifier("wave-arrow"), false, true, true));
        getLogger().info("EVENT_ARROW_PLAYER_HIT arrow=" + arrow.getUniqueId()
                + " spell=" + spell + " target=" + player.getUniqueId()
                + " damage=" + damage + " slowness_ticks=" + debuffTicks);
        cleanupEventArrow(arrow.getUniqueId());
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onEventArrowHit(ProjectileHitEvent event) {
        if (event.getEntity() instanceof Arrow arrow && isEventArrow(arrow)) {
            if (ARROW_SPELL_EXPLOSIVE.equals(readString(arrow, keyArrowSpell))) {
                detonateExplosiveArrow(arrow, arrow.getLocation());
                return;
            }
            cleanupEventArrow(arrow.getUniqueId());
        }
    }

    /** A current wave mob may be distracted by the player who hit it briefly. */
    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onWaveMobPlayerDamageTrace(EntityDamageByEntityEvent event) {
        if (!(event.getEntity() instanceof Mob mob)
                || !(event.getDamager() instanceof Player attacker)
                || !isWaveCombatKind(readString(mob, keyKind))
                || !isWaveAiCombatEntity(mob)
                || !isCombatTarget(attacker)) {
            return;
        }
        long now = System.currentTimeMillis();
        long expiresAt = now + WAVE_MOB_AGGRO_MILLIS;
        wavePlayerAggroUntil.put(mob.getUniqueId(), expiresAt);
        mob.setTarget(attacker);
        getLogger().info("WAVE_MOB_AGGRO entity=" + mob.getUniqueId()
                + " target=" + attacker.getUniqueId()
                + " duration_ms=" + WAVE_MOB_AGGRO_MILLIS);
    }

    /**
     * Wave 6 room isolation must cover the final damage event as well as AI
     * target selection.  A stale vanilla target, a collision edge case, or a
     * third-party melee hook must not let a mob damage a player through a
     * closed chamber boundary.
     */
    @EventHandler(priority = EventPriority.HIGH, ignoreCancelled = false)
    public void onRealitySplitCrossRoomMobDamage(EntityDamageByEntityEvent event) {
        if (!(event.getEntity() instanceof Player player)
                || !(event.getDamager() instanceof LivingEntity attacker)
                || !isWaveCombatKind(readString(attacker, keyKind))
                || !isChamberWaveEntity(attacker)
                || !ownedEntities.containsKey(attacker.getUniqueId())) {
            return;
        }
        if (realitySplitTargetAllowed(attacker, player)) {
            return;
        }
        event.setCancelled(true);
        getLogger().info("WAVE_6_MELEE_CROSS_ROOM_BLOCKED event=" + eventId
                + " attacker=" + attacker.getUniqueId()
                + " target=" + player.getUniqueId()
                + " chamber=" + realitySplitChamberId(attacker)
                + " rooms_complete=" + realitySplitChamberController.allChambersComplete(generation));
    }

    /**
     * Endermen are one of the official wave combat roles, but daylight is not
     * an event mechanic.  Letting the vanilla sunlight tick kill every
     * candidate can strand Wave 1 after its scheduled groups are RECOVERY.
     * Cancel only the FIRE_TICK for the current, tagged event Endermen; player
     * damage, fire hazards and all natural Endermen keep their normal rules.
     */
    @EventHandler(priority = EventPriority.HIGHEST, ignoreCancelled = false)
    public void onOfficialEndermanSunDamage(EntityDamageEvent event) {
        if (!(event.getEntity() instanceof Enderman enderman)
                || event.getCause() != EntityDamageEvent.DamageCause.FIRE_TICK
                || !ownedEntities.containsKey(enderman.getUniqueId())
                || !isOfficialEntity(enderman)) {
            return;
        }
        String kind = readString(enderman, keyKind);
        if (!EVENT_KIND_BOSS.equals(kind) && !isWaveCombatKind(kind)) {
            return;
        }
        event.setCancelled(true);
        enderman.setFireTicks(0);
        getLogger().fine("EVENT_ENDERMAN_SUN_DAMAGE_BLOCKED event=" + eventId
                + " entity=" + enderman.getUniqueId() + " kind=" + kind);
    }

    private Player playerDamageAttacker(Entity source) {
        if (source instanceof Player player) {
            return player;
        }
        if (source instanceof org.bukkit.entity.Projectile projectile
                && projectile.getShooter() instanceof Player player) {
            return player;
        }
        return null;
    }

    /**
     * Wave mobs retain real Bukkit entity health, but normal living-entity
     * hurt resistance keeps only the difference from a previous attack while
     * its 20-tick window is active.  Combat Trace reproduced that as a
     * non-cancelled 2.440 hit becoming a 0.358 health change.  Once every
     * earlier protection listener has allowed a player hit, apply the already
     * computed final damage once to the real health value and cancel only the
     * duplicate native application.  This does not reset noDamageTicks or
     * bypass an earlier cancellation.
     */
    @EventHandler(priority = EventPriority.HIGHEST, ignoreCancelled = true)
    public void onWaveMobPlayerDamageAuthoritative(EntityDamageByEntityEvent event) {
        if (!(event.getEntity() instanceof LivingEntity victim)
                || !isWaveCombatKind(readString(victim, keyKind))
                || !ownedEntities.containsKey(victim.getUniqueId())) {
            return;
        }
        Player attacker = playerDamageAttacker(event.getDamager());
        if (attacker == null || !isCombatTarget(attacker)) {
            return;
        }
        if (isChamberWaveEntity(victim)
                && !realitySplitTargetAllowed(victim, attacker)) {
            event.setCancelled(true);
            getLogger().info("WAVE_6_ATTACK_CROSS_ROOM_BLOCKED event=" + eventId
                    + " attacker=" + attacker.getUniqueId()
                    + " target=" + victim.getUniqueId()
                    + " chamber=" + realitySplitChamberId(victim));
            return;
        }
        EventRealHealthDamagePolicy.Result result = EventRealHealthDamagePolicy.apply(
                victim.getHealth(), victim.getMaxHealth(), event.getFinalDamage());
        if (!result.applied()) {
            return;
        }
        authoritativeEventMobDamage.put(event, result);
        event.setCancelled(true);
        victim.setHealth(result.remainingHealth());
        getLogger().fine("WAVE_MOB_REAL_HEALTH_DAMAGE event=" + eventId
                + " mob=" + victim.getType() + ":" + victim.getUniqueId()
                + " attacker=" + attacker.getUniqueId()
                + " cause=" + event.getCause() + " final=" + event.getFinalDamage()
                + " health_before=" + result.healthBefore()
                + " health_after=" + result.remainingHealth());
    }

    /**
     * Record both sides of a player-to-event-mob hit.  The Bukkit callback is
     * raised before Paper applies the damage, so the next tick is the only
     * reliable place to distinguish an accepted event from a real health
     * mutation.
     */
    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = false)
    public void onWaveMobDamagedByPlayer(EntityDamageByEntityEvent event) {
        Player attacker = playerDamageAttacker(event.getDamager());
        if (!(event.getEntity() instanceof LivingEntity victim)
                || !isWaveCombatKind(readString(victim, keyKind))
                || !ownedEntities.containsKey(victim.getUniqueId())
                || attacker == null || !isCombatTarget(attacker)) {
            return;
        }
        EventRealHealthDamagePolicy.Result authoritative = authoritativeEventMobDamage.remove(event);
        double before = authoritative == null ? victim.getHealth() : authoritative.healthBefore();
        double finalDamage = event.getFinalDamage();
        getLogger().info("WAVE_MOB_PLAYER_DAMAGE event=" + eventId
                + " mob=" + victim.getType() + ":" + victim.getUniqueId()
                + " attacker=" + attacker.getUniqueId()
                + " wave=" + readInt(victim, keyWave, 0)
                + " cause=" + event.getCause()
                + " final=" + finalDamage
                + " cancelled=" + event.isCancelled()
                + " authoritative_real_health=" + (authoritative != null)
                + " health_before=" + before
                + " no_damage_ticks=" + victim.getNoDamageTicks());
        Bukkit.getScheduler().runTask(this, () -> {
            double after = victim.isValid() && !victim.isDead() ? victim.getHealth() : 0.0D;
            double delta = Math.max(0.0D, before - after);
            getLogger().info("WAVE_MOB_PLAYER_DAMAGE_APPLIED event=" + eventId
                    + " mob=" + victim.getType() + ":" + victim.getUniqueId()
                    + " attacker=" + attacker.getUniqueId()
                    + " accepted_before=" + (authoritative != null || !event.isCancelled())
                    + " authoritative_real_health=" + (authoritative != null)
                    + " delta=" + delta
                    + " health_before=" + before
                    + " health_after=" + after
                    + " no_damage_ticks_after=" + victim.getNoDamageTicks());
        });
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onPortalWaveMobAttack(EntityDamageByEntityEvent event) {
        if (event.getEntity() instanceof Player victim
                && event.getDamager() instanceof LivingEntity attacker
                && isWaveCombatKind(readString(attacker, keyKind))) {
            getLogger().info("WAVE_MOB_DAMAGE event=" + eventId
                    + " attacker=" + attacker.getType() + ":" + attacker.getUniqueId()
                    + " wave=" + readInt(attacker, keyWave, 0)
                    + " victim=" + victim.getUniqueId()
                    + " cause=" + event.getCause()
                    + " final=" + event.getFinalDamage()
                    + " cancelled=" + event.isCancelled());
        }

        Player playerDamager = event.getDamager() instanceof Player player
                ? player
                : event.getDamager() instanceof org.bukkit.entity.Projectile projectile
                && projectile.getShooter() instanceof Player player ? player : null;
        if (!(event.getEntity() instanceof Mob mob)
                || playerDamager == null
                || !isWaveCombatKind(readString(mob, keyKind))
                || !ownedEntities.containsKey(mob.getUniqueId())
                || readInt(mob, keyWave, 0) != 3
                || !isCombatTarget(playerDamager)) {
            return;
        }

        portalWaveKnockbackUntilMillis.put(mob.getUniqueId(), System.currentTimeMillis() + 250L);
        // Portal-wave mobs must hold their combat lane. Keep the player's
        // damage event and hit animation, but cancel only the knockback event
        // that Paper emits for this just-accepted player hit.
        getLogger().fine("WAVE_PORTAL_MOB_KNOCKBACK_DISABLED event=" + eventId
                + " attacker=" + playerDamager.getUniqueId()
                + " mob=" + mob.getUniqueId());
    }

    /**
     * Paper emits knockback after the damage event. Cancel only the short
     * window recorded for a portal-wave hit; the damage event remains intact
     * and all other waves keep vanilla combat physics.
     */
    @EventHandler(priority = EventPriority.HIGHEST, ignoreCancelled = false)
    public void onPortalWaveMobKnockback(EntityKnockbackEvent event) {
        if (!(event.getEntity() instanceof Mob mob)
                || !isWaveCombatKind(readString(mob, keyKind))
                || readInt(mob, keyWave, 0) != 3
                || event.getCause() != EntityKnockbackEvent.KnockbackCause.ENTITY_ATTACK) {
            return;
        }
        Long until = portalWaveKnockbackUntilMillis.get(mob.getUniqueId());
        if (until == null) {
            return;
        }
        long now = System.currentTimeMillis();
        if (until < now) {
            portalWaveKnockbackUntilMillis.remove(mob.getUniqueId());
            return;
        }
        // Keep the short window alive for all hits in a burst. Removing the
        // marker after the first event allowed a second player hit in the same
        // tick to push a portal mob out of its lane.
        event.setCancelled(true);
        getLogger().info("WAVE_PORTAL_MOB_KNOCKBACK_CANCELLED event=" + eventId
                + " mob=" + mob.getUniqueId());
    }

    /** Apply the stage profile to the boss's outgoing melee, not only its path. */
    @EventHandler(priority = EventPriority.HIGHEST, ignoreCancelled = true)
    public void onBossMeleeAttack(EntityDamageByEntityEvent event) {
        if (!(event.getDamager() instanceof LivingEntity attacker)
                || !(event.getEntity() instanceof Player victim)
                || bossUuid == null || !bossUuid.equals(attacker.getUniqueId())
                || !EVENT_KIND_BOSS.equals(readString(attacker, keyKind))
                || !isCombatTarget(victim)) {
            return;
        }
        boolean disposableTest = testCombatAiMode && isTestBoss(attacker);
        boolean active = phase == EventPhase.BOSS_ACTIVE;
        if (!active && !disposableTest) {
            return;
        }
        BossPhasePolicy.CombatProfile profile = currentBossCombatProfile();
        double stageBonus = profile.meleeDamageBonus();
        if (stageBonus <= 0.0D) {
            return;
        }
        event.setDamage(Math.max(0.0D, event.getDamage()) + stageBonus);
        getLogger().info("BOSS_MELEE_ATTACK event=" + eventId
                + " boss=" + attacker.getUniqueId() + " target=" + victim.getUniqueId()
                + " stage=" + bossPhase + " stage_bonus=" + stageBonus
                + " total=" + event.getDamage());
    }

    private boolean isArenaLocation(Location location) {
        if (!isConfigured() || location == null || location.getWorld() == null
                || !location.getWorld().getName().equalsIgnoreCase(worldName)) {
            return false;
        }
        int x = location.getBlockX();
        int y = location.getBlockY();
        int z = location.getBlockZ();
        return x >= arenaMinX && x <= arenaMaxX && y >= arenaMinY && y <= arenaMaxY
                && z >= arenaMinZ && z <= arenaMaxZ;
    }

    /**
     * The current obelisk is five blocks tall while the local arena volume
     * is only three blocks above the combat floor. Permit exactly the single
     * crown layer above that old ceiling, keeping its horizontal footprint,
     * gate/core reservations and block protection unchanged. This is a visual
     * crest, not an expansion of the player or mob combat volume.
     */
    private boolean isObeliskLocation(Location location) {
        if (isArenaLocation(location)) {
            return true;
        }
        if (!isConfigured() || location == null || location.getWorld() == null
                || !location.getWorld().getName().equalsIgnoreCase(worldName)) {
            return false;
        }
        int x = location.getBlockX();
        int y = location.getBlockY();
        int z = location.getBlockZ();
        return y == arenaMaxY + 1
                && x >= arenaMinX && x <= arenaMaxX
                && z >= arenaMinZ && z <= arenaMaxZ;
    }

    /** The event-owned projectile may briefly crest above the obelisk crown. */
    private boolean isObeliskProjectileLocation(Location location) {
        if (isObeliskLocation(location)) {
            return true;
        }
        if (!isConfigured() || location == null || location.getWorld() == null
                || !location.getWorld().getName().equalsIgnoreCase(worldName)) {
            return false;
        }
        int x = location.getBlockX();
        int y = location.getBlockY();
        int z = location.getBlockZ();
        return y == arenaMaxY + 2
                && x >= arenaMinX && x <= arenaMaxX
                && z >= arenaMinZ && z <= arenaMaxZ;
    }

    private boolean isProtectedEventLocation(Location location) {
        return phase != EventPhase.UNLOCKED
                && (isArenaLocation(location) || isGateLocation(location)
                || isWave4ObeliskObeliskCell(location));
    }

    private boolean isProtectedInventory(Inventory inventory) {
        if (inventory == null) {
            return false;
        }
        InventoryHolder holder = inventory.getHolder();
        if (holder instanceof org.bukkit.block.BlockState state) {
            return isProtectedEventLocation(state.getLocation());
        }
        if (holder instanceof Entity entity) {
            return isProtectedEventLocation(entity.getLocation());
        }
        return false;
    }

    private boolean isGateLocation(Location location) {
        if (location == null || location.getWorld() == null || layoutState.gatePos1() == null
                || layoutState.gatePos2() == null) {
            return false;
        }
        EventLayoutState.Point first = layoutState.gatePos1();
        EventLayoutState.Point second = layoutState.gatePos2();
        return first.world().equalsIgnoreCase(location.getWorld().getName())
                && location.getBlockX() >= Math.min(first.x(), second.x())
                && location.getBlockX() <= Math.max(first.x(), second.x())
                && location.getBlockY() >= Math.min(first.y(), second.y())
                && location.getBlockY() <= Math.max(first.y(), second.y())
                && location.getBlockZ() >= Math.min(first.z(), second.z())
                && location.getBlockZ() <= Math.max(first.z(), second.z());
    }

    private void restoreCoreAndPads() {
        World world = Bukkit.getWorld(worldName);
        if (world == null) {
            return;
        }
        Block core = world.getBlockAt(coreX, coreY, coreZ);
        if (!coreBlockData.isBlank()) {
            restoreBlock(core, coreBlockData);
        }
        for (EventSnapshot.PadSnapshot pad : pads) {
            Block block = world.getBlockAt(pad.x(), pad.y(), pad.z());
            if (!pad.originalBlockData().isBlank()) {
                restoreBlock(block, pad.originalBlockData());
            }
        }
        cleanupOwnedEntities(eventId, generation);
    }

    /**
     * Victory restores only the vanilla block data and combat entities.  The
     * Core itself remains as a non-destructive memorial, so the next rebuild
     * can show the same custom shell and the frozen official roster.
     */
    private void restoreCoreAndPadsForVictory() {
        World world = Bukkit.getWorld(worldName);
        if (world == null) {
            return;
        }
        Block core = world.getBlockAt(coreX, coreY, coreZ);
        if (!coreBlockData.isBlank()) {
            restoreBlock(core, coreBlockData);
        }
        for (EventSnapshot.PadSnapshot pad : pads) {
            Block block = world.getBlockAt(pad.x(), pad.y(), pad.z());
            if (!pad.originalBlockData().isBlank()) {
                restoreBlock(block, pad.originalBlockData());
            }
        }
        removeCoreVisualsAtConfiguredLayout();
        cleanupOwnedEntitiesForEvent(eventId);
    }

    private void restoreBlock(Block block, String blockData) {
        if (block == null || blockData == null || blockData.isBlank()) {
            return;
        }
        try {
            BlockData data = Bukkit.createBlockData(blockData);
            block.setBlockData(data, false);
        } catch (IllegalArgumentException error) {
            getLogger().warning("Refused to restore invalid event block data at " + block.getLocation());
        }
    }

    private void rebuildPersistedVisuals() {
        if (!bootstrapped || !isConfigured()) {
            return;
        }
        World world = Bukkit.getWorld(worldName);
        if (world == null) {
            getLogger().warning("Configured End Event world is unavailable: " + worldName);
            return;
        }
        if (phase == EventPhase.UNLOCKED) {
            releaseOverlayChunkTickets();
        } else {
            ensureOverlayChunksLoaded(world);
        }
        if (phase == EventPhase.UNLOCKED) {
            removeOwnedVisuals();
            if (shouldShowVictoryMemorial()) {
                spawnVictoryMemorialVisuals(world);
            }
            return;
        }
        Block core = world.getBlockAt(coreX, coreY, coreZ);
        if (core.getType().isAir() || core.isPassable() || core.isLiquid()) {
            getLogger().warning("Configured Core target is no longer a solid block; refusing to create a floating overlay.");
            return;
        }
        removeOwnedVisuals();
        spawnCoreOverlay(world, core);
        for (EventSnapshot.PadSnapshot pad : pads) {
            spawnRuneOverlay(world, pad);
        }
        spawnCoreText(world);
        getLogger().info("END_EVENT_PHYSICAL_VISUALS core=" + core.getType()
                + " pads=VANILLA_FLOOR_BLOCKS displays=CORE_OVERLAY_AND_RUNE_OVERLAYS");
    }

    /**
     * Removes the persistent Core/rune display shells by their configured
     * block anchors.  This is intentionally narrower than the event-entity
     * cleanup: it catches a visual left by an earlier plugin generation without
     * scanning or touching unrelated displays elsewhere in the world.
     */
    private int removeCoreVisualsAtConfiguredLayout() {
        World world = Bukkit.getWorld(worldName);
        if (world == null) {
            return 0;
        }
        int removed = 0;
        Block core = world.getBlockAt(coreX, coreY, coreZ);
        // Keep the exact Core/rune chunks loaded while the removal is being
        // performed.  A nearby-entity query silently misses a persisted
        // display in an unloaded chunk, which is how an old Core shell could
        // survive an otherwise successful GUI removal.
        ensureOverlayChunksLoaded(world);
        Set<UUID> candidateIds = new LinkedHashSet<>();
        // Iterate the loaded entity list instead of relying on an entity
        // bounding-box lookup.  This catches displays whose transformed
        // bounding box no longer intersects the old search box.
        List<Entity> candidates = new ArrayList<>(world.getEntities());
        for (Entity entity : candidates) {
            if (entity == null || !candidateIds.add(entity.getUniqueId())) {
                continue;
            }
            String kind = readString(entity, keyKind);
            if (!isCoreVisualAtConfiguredLayout(entity, kind, core, world)) {
                continue;
            }
            entity.remove();
            ownedEntities.remove(entity.getUniqueId());
            removed++;
        }
        return removed;
    }

    private boolean isCoreVisualAtConfiguredLayout(Entity entity, String kind, Block core, World world) {
        if (entity == null || core == null || world == null || entity.getWorld() == null
                || !entity.getWorld().equals(world)) {
            return false;
        }
        // Do not require a PDC role here. Displays created by an earlier
        // plugin generation may have a missing/renamed role tag, while their
        // exact Core/rune anchor is still unambiguous.  The type and position
        // checks below keep this cleanup limited to event visuals.
        if (!(entity instanceof ItemDisplay)
                && !(entity instanceof BlockDisplay)
                && !(entity instanceof TextDisplay)) {
            return false;
        }
        if (entity instanceof ItemDisplay display) {
            if (sameCoreOverlayBlock(display, core)) {
                return true;
            }
            for (EventSnapshot.PadSnapshot pad : pads) {
                Block floor = world.getBlockAt(pad.x(), pad.y() - 1, pad.z());
                if (sameRuneOverlayBlock(display, floor)) {
                    return true;
                }
            }
            return false;
        }
        if (entity instanceof BlockDisplay) {
            return sameCoreOrRuneDisplayBlock(entity, core, world);
        }
        return entity instanceof TextDisplay && sameCoreTextDisplay(entity, core);
    }

    private boolean sameCoreOrRuneDisplayBlock(Entity entity, Block core, World world) {
        Location location = entity.getLocation();
        if (location.getBlockX() == core.getX() && location.getBlockZ() == core.getZ()
                && (location.getBlockY() == core.getY() || location.getBlockY() == core.getY() + 1)) {
            return true;
        }
        for (EventSnapshot.PadSnapshot pad : pads) {
            if (location.getBlockX() == pad.x() && location.getBlockZ() == pad.z()
                    && (location.getBlockY() == pad.y() - 1 || location.getBlockY() == pad.y())) {
                return true;
            }
        }
        return false;
    }

    private boolean sameCoreTextDisplay(Entity entity, Block core) {
        if (entity == null || core == null || entity.getWorld() == null
                || !entity.getWorld().equals(core.getWorld())) {
            return false;
        }
        Location location = entity.getLocation();
        return location.getBlockX() == core.getX()
                && location.getBlockZ() == core.getZ()
                && location.getY() >= core.getY() + 1.0D
                && location.getY() <= core.getY() + 8.0D;
    }

    /**
     * ItemDisplay entities are stored in their chunks. A configured Core may
     * be far from spawn with no player nearby, so an unloaded chunk would
     * make the visual look missing and trigger an endless rebuild loop. Keep
     * only the Core and rune chunks loaded for the lifetime of this event.
     */
    private void ensureOverlayChunksLoaded(World world) {
        world.removePluginChunkTickets(this);
        Set<String> requiredChunks = new LinkedHashSet<>();
        requiredChunks.add((coreX >> 4) + ":" + (coreZ >> 4));
        for (EventSnapshot.PadSnapshot pad : pads) {
            requiredChunks.add((pad.x() >> 4) + ":" + (pad.z() >> 4));
        }
        for (String key : requiredChunks) {
            String[] parts = key.split(":", 2);
            int chunkX = Integer.parseInt(parts[0]);
            int chunkZ = Integer.parseInt(parts[1]);
            world.getChunkAt(chunkX, chunkZ, true).addPluginChunkTicket(this);
        }
    }

    private void releaseOverlayChunkTickets() {
        for (World world : Bukkit.getWorlds()) {
            world.removePluginChunkTickets(this);
        }
    }

    private void removeOwnedVisuals() {
        World world = Bukkit.getWorld(worldName);
        if (world == null) {
            return;
        }
        int removed = 0;
        for (Entity entity : new ArrayList<>(world.getEntities())) {
            String kind = readString(entity, keyKind);
            boolean visual = EVENT_KIND_DISPLAY.equals(kind) || EVENT_KIND_MEMORIAL.equals(kind)
                    || EVENT_KIND_CORE.equals(kind)
                    || EVENT_KIND_PAD.equals(kind);
            boolean currentSession = ownedBySession(entity, eventId, generation);
            boolean priorVisualInArena = visual && isArenaLocation(entity.getLocation());
            if (visual && (currentSession || priorVisualInArena)) {
                entity.remove();
                ownedEntities.remove(entity.getUniqueId());
                removed++;
            }
        }
        if (removed > 0) {
            getLogger().info("END_EVENT_VISUAL_CLEANUP removed=" + removed + " scope=event-arena");
        }
    }

    /** Remove only transition-pad displays; the Core shell and its text stay. */
    private void removeTransitionRuneVisuals() {
        int removed = 0;
        for (Entity entity : new ArrayList<>(ownedEntities.values())) {
            if (!EVENT_KIND_PAD.equals(readString(entity, keyKind))) {
                continue;
            }
            if (entity.isValid()) {
                entity.remove();
                removed++;
            }
            ownedEntities.remove(entity.getUniqueId());
        }
        transitionRuneRenderStates.clear();
        if (removed > 0) {
            getLogger().info("END_EVENT_TRANSITION_RUNES_REMOVED event=" + eventId
                    + " count=" + removed + " reason=ritual-complete");
        }
    }

    private void spawnCoreOverlay(World world, Block core) {
        // The target block remains the real block selected by the admin.  Keep
        // the display at the block centre and let the tiny shell expansion
        // expose every face without moving the visual onto the block above.
        // The vanilla block itself is still preserved and restored from its
        // original BlockData when the event is removed.
        Location displayLocation = coreOverlayLocation(core);
        ItemDisplay display = world.spawn(displayLocation, ItemDisplay.class, entity -> {
            entity.setItemStack(overlayItem(coreCharged ? MODEL_CORE_CHARGED_OVERLAY : MODEL_CORE_OVERLAY,
                    coreCharged ? "end_event_core_charged" : "end_event_core"));
            // Keep the custom shell readable on any vanilla block and at any
            // time of day.  Without an explicit light level the display can
            // look like an untextured black cube even though the resource
            // pack model is present.
            entity.setBrightness(new Display.Brightness(15, 15));
            // The event models are authored as raw block-space cubes.  FIXED
            // applies the item-model fixed transform again in 1.21.1, which
            // leaves the display depth-tested inside the real block.  NONE
            // keeps the cube at the exact block anchor and makes its faces
            // render over the vanilla block without replacing that block.
            entity.setItemDisplayTransform(ItemDisplay.ItemDisplayTransform.NONE);
            entity.setBillboard(Display.Billboard.FIXED);
            entity.setViewRange(64.0F);
            // A display exactly inside an opaque block is depth-tested away.
            // Keep its origin at the block centre, but give the shell a small
            // symmetric margin so all six faces remain visible without moving
            // the Core onto the block above.
            entity.setDisplayWidth(1.10F);
            entity.setDisplayHeight(1.10F);
            entity.setPersistent(true);
            entity.setGravity(false);
            // Do not use the entity-level invulnerable flag here: Paper then
            // skips EntityDamageByEntityEvent for a real left click on the
            // visual shell.  The event handlers below cancel the damage and
            // route an operator click to the confirmation GUI, so the Core
            // remains physically protected without becoming unclickable.
            entity.setInvulnerable(false);
            entity.setShadowRadius(0.0F);
            entity.setTransformation(new Transformation(
                    new Vector3f(), new AxisAngle4f(), new Vector3f(1.10F, 1.10F, 1.10F), new AxisAngle4f()));
        });
        tag(display, EVENT_KIND_CORE, 0, false);
    }

    private void spawnRuneOverlay(World world, EventSnapshot.PadSnapshot pad) {
        Block floor = world.getBlockAt(pad.x(), pad.y() - 1, pad.z());
        if (!floor.getType().isSolid() || floor.isLiquid()) {
            getLogger().warning("Refused to create a floating rune overlay: floor is not solid at "
                    + floor.getLocation());
            return;
        }
        // The pad coordinate is the air block above this floor.  The custom
        // rune model is a full-width, low slab whose lower face is anchored
        // to the floor top; the occupied variant is selected from the live
        // pad roster so a player can see the registration immediately.
        Location displayLocation = runeOverlayLocation(floor);
        ItemDisplay display = world.spawn(displayLocation, ItemDisplay.class, entity -> {
            entity.setItemStack(runeOverlayItem(pad));
            entity.setBrightness(new Display.Brightness(15, 15));
            // Runes use the same raw block-space model convention as the Core;
            // NONE is required for the thin slab to render on the floor top.
            entity.setItemDisplayTransform(ItemDisplay.ItemDisplayTransform.NONE);
            entity.setBillboard(Display.Billboard.FIXED);
            entity.setViewRange(64.0F);
            entity.setDisplayWidth(1.0F);
            entity.setDisplayHeight(0.25F);
            entity.setPersistent(true);
            entity.setGravity(false);
            entity.setInvulnerable(true);
            entity.setShadowRadius(0.0F);
            entity.setTransformation(new Transformation(
                    new Vector3f(), new AxisAngle4f(), new Vector3f(1.0F, 1.0F, 1.0F), new AxisAngle4f()));
        });
        tag(display, EVENT_KIND_PAD, 0, false);
    }

    private Location coreOverlayLocation(Block core) {
        // ItemDisplay block models are centred on their display origin.  A
        // centre anchor leaves the opaque vanilla block in front of the
        // shell, so only the top face survives depth testing.  Anchor the
        // model at the block's top plane: its lower half covers the real
        // block and its tiny 1.10 scale margin keeps all faces visible
        // without replacing or moving the vanilla block.
        return core.getLocation().add(0.5D, 1.0D, 0.5D);
    }

    private Location runeOverlayLocation(Block floor) {
        return floor.getLocation().add(0.5D, 1.0D, 0.5D);
    }

    private boolean sameRuneOverlayBlock(ItemDisplay display, Block floor) {
        if (display == null || floor == null || display.getWorld() == null
                || !display.getWorld().equals(floor.getWorld())) {
            return false;
        }
        Location location = display.getLocation();
        return location.getBlockX() == floor.getX()
                && location.getBlockY() == floor.getY() + 1
                && location.getBlockZ() == floor.getZ();
    }

    private boolean sameCoreOverlayBlock(ItemDisplay display, Block core) {
        if (display == null || core == null || display.getWorld() == null
                || !display.getWorld().equals(core.getWorld())) {
            return false;
        }
        Location location = display.getLocation();
        return location.getBlockX() == core.getX()
                && location.getBlockY() == core.getY() + 1
                && location.getBlockZ() == core.getZ();
    }

    private boolean hasCoreOverlay(World world, Block core) {
        return findCoreOverlay(world, core) != null;
    }

    private ItemDisplay findCoreOverlay(World world, Block core) {
        if (world == null || core == null) {
            return null;
        }
        for (Entity entity : world.getEntities()) {
            if (entity instanceof ItemDisplay display
                    && EVENT_KIND_CORE.equals(readString(entity, keyKind))
                    && ownedBySession(entity, eventId, generation)
                    && sameCoreOverlayBlock(display, core)) {
                return display;
            }
        }
        return null;
    }

    private ItemDisplay findRuneOverlay(World world, Block floor) {
        if (world == null || floor == null) {
            return null;
        }
        for (Entity entity : world.getEntities()) {
            if (entity instanceof ItemDisplay display
                    && EVENT_KIND_PAD.equals(readString(entity, keyKind))
                    && ownedBySession(entity, eventId, generation)
                    && sameRuneOverlayBlock(display, floor)) {
                return display;
            }
        }
        return null;
    }

    private ItemStack runeOverlayItem(EventSnapshot.PadSnapshot pad) {
        String key = padKey(pad);
        boolean occupied = runeVisualOccupants.containsKey(key);
        TransitionRuneController.RenderState state = transitionRuneRenderStates.getOrDefault(
                key, occupied ? TransitionRuneController.RenderState.OCCUPIED
                        : TransitionRuneController.RenderState.EMPTY);
        return switch (state) {
            case CHARGING -> overlayItem(MODEL_RUNE_OVERLAY_CHARGING, "end_event_pad_charging");
            case COMPLETE -> overlayItem(MODEL_RUNE_OVERLAY_COMPLETE, "end_event_pad_complete");
            case OCCUPIED -> overlayItem(MODEL_RUNE_OVERLAY_OCCUPIED, "end_event_pad_occupied");
            case EMPTY -> overlayItem(MODEL_RUNE_OVERLAY, "end_event_pad");
        };
    }

    private void refreshRuneOverlayVisuals() {
        World world = Bukkit.getWorld(worldName);
        if (world == null) {
            return;
        }
        for (EventSnapshot.PadSnapshot pad : pads) {
            Block floor = world.getBlockAt(pad.x(), pad.y() - 1, pad.z());
            ItemDisplay display = findRuneOverlay(world, floor);
            if (display != null) {
                display.setItemStack(runeOverlayItem(pad));
            }
        }
    }

    /**
     * Keep the ritual pads readable even when the custom model is subtle or
     * the viewer is using a low-contrast shader. Particles are sent only to
     * event viewers and are anchored to the solid block top, so this never
     * creates a second floating pad or mutates the arena.
     */
    private void renderRitualZoneVisuals(long now) {
        if (!coreCharged || (phase != EventPhase.READY_FOR_PLAYERS
                && phase != EventPhase.START_RITUAL
                && !isTransitionRunePhase(phase))) {
            return;
        }
        World world = Bukkit.getWorld(worldName);
        if (world == null || pads.isEmpty()) {
            return;
        }
        for (EventSnapshot.PadSnapshot pad : pads) {
            Block floor = world.getBlockAt(pad.x(), pad.y() - 1, pad.z());
            if (!floor.getType().isSolid() || floor.isLiquid()) {
                continue;
            }
            TransitionRuneController.RenderState runeState = transitionRuneRenderStates.getOrDefault(
                    padKey(pad), runeVisualOccupants.containsKey(padKey(pad))
                            ? TransitionRuneController.RenderState.OCCUPIED
                            : TransitionRuneController.RenderState.EMPTY);
            ZoneVisualPolicy.ZoneState state = switch (runeState) {
                case CHARGING -> ZoneVisualPolicy.ZoneState.CHARGING;
                case COMPLETE -> ZoneVisualPolicy.ZoneState.COMPLETED;
                case OCCUPIED -> ZoneVisualPolicy.ZoneState.OCCUPIED;
                case EMPTY -> ZoneVisualPolicy.ZoneState.FREE;
            };
            Location top = runeOverlayLocation(floor);
            for (Player viewer : eventAudience()) {
                renderZoneVisual(viewer, top, state, 0.72D, now);
            }
        }
    }

    private ItemStack overlayItem(int customModelData, String modelId) {
        ItemStack item = new ItemStack(EVENT_OVERLAY_ITEM);
        ItemMeta meta = item.getItemMeta();
        if (meta == null) {
            return item;
        }
        meta.setCustomModelData(customModelData);
        meta.setDisplayName("§f" + modelId);
        meta.addItemFlags(ItemFlag.values());
        item.setItemMeta(meta);
        return item;
    }

    private int overlayModelData(ItemDisplay display) {
        if (display == null) {
            return 0;
        }
        ItemStack item = display.getItemStack();
        if (item == null || !item.hasItemMeta()) {
            return 0;
        }
        Integer customModelData = item.getItemMeta().getCustomModelData();
        return customModelData == null ? 0 : customModelData;
    }

    private String visualStatusText() {
        if (!isConfigured()) {
            return "coreOverlay=false coreModel=0 runes=0/0 occupied=0";
        }
        World world = Bukkit.getWorld(worldName);
        if (world == null) {
            return "coreOverlay=false coreModel=0 runes=0/" + pads.size() + " occupied=0 world=unloaded";
        }
        ItemDisplay coreDisplay = findCoreOverlay(world, world.getBlockAt(coreX, coreY, coreZ));
        int runeCount = 0;
        int occupiedCount = 0;
        for (EventSnapshot.PadSnapshot pad : pads) {
            ItemDisplay rune = findRuneOverlay(world, world.getBlockAt(pad.x(), pad.y() - 1, pad.z()));
            if (rune == null) {
                continue;
            }
            runeCount++;
            if (overlayModelData(rune) == MODEL_RUNE_OVERLAY_OCCUPIED) {
                occupiedCount++;
            }
        }
        return "coreOverlay=" + (coreDisplay != null)
                + " coreModel=" + overlayModelData(coreDisplay)
                + " runes=" + runeCount + "/" + pads.size()
                + " occupied=" + occupiedCount;
    }

    private void spawnCoreText(World world) {
        Location location = new Location(world, coreX + 0.5D, coreY + 2.25D, coreZ + 0.5D);
        TextDisplay display = world.spawn(location, TextDisplay.class);
        tag(display, EVENT_KIND_DISPLAY, 0, false);
        display.setText(coreCharged ? "§5РАЗЛОМ ЗАРЯЖЕН\n§7Соберите игроков на рунах" : "§5РАЗЛОМ\n§7" + resourceProgressText().replace(", ", "\n§7"));
        display.setBillboard(TextDisplay.Billboard.CENTER);
        display.setLineWidth(180);
        display.setTransformation(new Transformation(
                new Vector3f(), new AxisAngle4f(), new Vector3f(0.45F, 0.45F, 0.45F), new AxisAngle4f()));
        ownedEntities.put(display.getUniqueId(), display);
    }

    @EventHandler(priority = EventPriority.HIGHEST, ignoreCancelled = true)
    public void onCoreInteract(PlayerInteractEvent event) {
        if (event.getHand() != EquipmentSlot.HAND || event.getAction() != Action.RIGHT_CLICK_BLOCK
                || !sameCore(event.getClickedBlock()) || phase != EventPhase.COLLECTING) {
            return;
        }
        event.setCancelled(true);
        Player player = event.getPlayer();
        if (!coreInteractionGuard.accept(Bukkit.getCurrentTick(), eventId, generation, player.getUniqueId())) {
            return;
        }
        registerParticipant(player);
        ItemStack held = player.getInventory().getItemInMainHand();
        if (held.getType() == Material.AIR || held.getAmount() < 1) {
            return;
        }
        String material = held.getType().name();
        if (!resourceRequirements.containsKey(material)) {
            player.sendActionBar(Component.text("Нужен ресурс из списка Разлома", NamedTextColor.RED));
            return;
        }
        boolean official = rewardService != null && rewardService.isOfficialArtifact(held);
        boolean customProtected = held.hasItemMeta() && !held.getItemMeta().getPersistentDataContainer().getKeys().isEmpty();
        if (!CoreDepositMath.canAccept(true, material, resourceRequirements.keySet(), official, customProtected)) {
            player.sendActionBar(Component.text("Этот custom item нельзя пожертвовать", NamedTextColor.RED));
            return;
        }
        int required = resourceRequirements.get(material);
        int progress = depositedResources.getOrDefault(material, 0);
        int accepted = CoreDepositMath.acceptedAmount(held.getAmount(), required, progress);
        if (accepted <= 0) {
            player.sendActionBar(Component.text("Этот ресурс уже заполнен", NamedTextColor.YELLOW));
            return;
        }
        DepositJournal.Entry entry = new DepositJournal.Entry(
                eventId + ":" + UUID.randomUUID(), player.getUniqueId(), held.getType(), accepted, progress + accepted, "PREPARED");
        if (!depositJournal.prepare(entry)) {
            player.sendMessage(ChatColor.RED + "Внесение не записано durable; предмет не изменён.");
            return;
        }
        EventSnapshot before = snapshot();
        int previousAmount = held.getAmount();
        if (!depositJournal.markItemRemoved(entry)) {
            depositJournal.refund(entry);
            player.sendMessage(ChatColor.RED + "Журнал внесения недоступен; предмет не изменён.");
            return;
        }
        held.setAmount(previousAmount - accepted);
        depositedResources.put(material, progress + accepted);
        resourceContributors.add(player.getUniqueId());
        updateCoreChargeState();
        if (!saveStateSync()) {
            applySnapshot(before);
            if (restoreDepositItem(player, held, previousAmount)) {
                depositJournal.refund(entry);
                player.sendMessage(ChatColor.RED + "Состояние Core не сохранилось; ресурс возвращён.");
            } else {
                depositJournal.refundPending(entry);
                player.sendMessage(ChatColor.RED + "Состояние Core не сохранилось; возврат ресурса ожидает свободный слот.");
            }
            return;
        }
        if (!depositJournal.commit(entry)) {
            getLogger().warning("Deposit state was saved but journal commit is pending: " + entry.id());
        }
        if (held.getAmount() <= 0) {
            player.getInventory().setItemInMainHand(new ItemStack(Material.AIR));
        }
        playerCategory(player, "resource_contributor");
        rebuildPersistedVisuals();
        player.playSound(player.getLocation(), Sound.BLOCK_RESPAWN_ANCHOR_CHARGE, 0.8F, 1.2F);
        player.sendActionBar(Component.text("Внесено " + accepted + " " + material + ". " + resourceProgressText(), NamedTextColor.LIGHT_PURPLE));
    }

    private ItemStack heldWithAmount(ItemStack held, int amount) {
        ItemStack restored = held.clone();
        restored.setAmount(Math.max(1, amount));
        return restored;
    }

    private boolean restoreDepositItem(Player player, ItemStack original, int amount) {
        if (player == null || original == null || original.getType() == Material.AIR || amount < 1) {
            return false;
        }
        ItemStack restored = heldWithAmount(original, amount);
        ItemStack current = player.getInventory().getItemInMainHand();
        if (current == null || current.getType() == Material.AIR || current.isSimilar(original)) {
            player.getInventory().setItemInMainHand(restored);
            return true;
        }
        if (!inventoryCanFitExact(player.getInventory(), restored)) {
            return false;
        }
        return player.getInventory().addItem(restored).isEmpty();
    }

    private boolean inventoryCanFitExact(Inventory inventory, ItemStack item) {
        if (inventory == null || item == null || item.getType() == Material.AIR) {
            return false;
        }
        int remaining = item.getAmount();
        for (ItemStack stack : inventory.getStorageContents()) {
            if (remaining < 1) {
                return true;
            }
            if (stack != null && stack.isSimilar(item)) {
                remaining -= Math.max(0, stack.getMaxStackSize() - stack.getAmount());
            }
        }
        for (ItemStack stack : inventory.getStorageContents()) {
            if (remaining < 1) {
                return true;
            }
            if (stack == null || stack.getType() == Material.AIR) {
                remaining -= item.getMaxStackSize();
            }
        }
        return remaining <= 0;
    }

    private void recoverUnresolvedDeposits() {
        for (DepositJournal.Entry entry : depositJournal.unresolved()) {
            Player player = Bukkit.getPlayer(entry.playerUuid());
            int progress = depositedResources.getOrDefault(entry.material().name(), 0);
            if (progress >= entry.afterProgress()) {
                depositJournal.commit(entry);
                continue;
            }
            if (player != null && player.isOnline()) {
                ItemStack refund = new ItemStack(entry.material(), entry.amount());
                if (inventoryCanFitExact(player.getInventory(), refund)
                        && player.getInventory().addItem(refund).isEmpty()) {
                    depositJournal.refund(entry);
                } else {
                    depositJournal.refundPending(entry);
                    getLogger().warning("DEPOSIT_REFUND_PENDING event=" + eventId
                            + " player=" + entry.playerUuid() + " material=" + entry.material()
                            + " amount=" + entry.amount());
                }
            }
        }
    }

    private void registerParticipant(Player player) {
        if (player == null || !isConfigured()) {
            return;
        }
        if (participantUuids.add(player.getUniqueId())) {
            saveStateAsync();
        }
    }

    private void playerCategory(Player player, String category) {
        if (player != null) {
            playerCategories.put(player.getUniqueId(), category);
        }
    }

    private void tick() {
        if (!bootstrapped || !isEnabled()) {
            return;
        }
        lastMainThreadTickAtMillis = System.currentTimeMillis();
        lastMainThreadPhase = phase.name();
        lastMainThreadWave = activeWave;
        lastMainThreadGeneration = generation;
        eventTickCounter += 5L;
        sampleRuntimeDiagnostics();
        tickOfflineRosterGrace();
        updatePadOccupancy();
        renderRitualZoneVisuals(System.currentTimeMillis());
        updateCombatHelpers();
        tickWaveMobAi();
        tickWaveCommanderAura();
        tickMiniBosses();
        tickEventArrowProjectiles();
        refreshClientBindingsForOnlinePlayers();
        // Official boss phases are handled by the switch below.  The extra
        // call is only for the disposable local AI harness, which deliberately
        // keeps the official phase outside BOSS_ACTIVE.
        if (testCombatAiMode && liveBoss() != null
                && phase != EventPhase.BOSS_ACTIVE && phase != EventPhase.BOSS_FINISH
                && phase != EventPhase.BOSS_CINEMATIC) {
            tickBoss();
        }
        if (testWave4ObeliskMode) {
            tickWave4ObeliskAssault();
        }
        switch (phase) {
            case START_RITUAL -> tickStartRitual();
            case INTERMISSION_1, INTERMISSION_2, INTERMISSION_3,
                    INTERMISSION_5, INTERMISSION_6 -> tickCurrentIntermission();
            case CORE_RESTORATION -> tickCoreRestoration();
            case WAVE_1, WAVE_2, WAVE_3, WAVE_4, WAVE_5, WAVE_6, WAVE_7 -> tickWaveCompletion();
            case PRE_BOSS_COOLDOWN -> tickPreBossCooldown();
            case BOSS_CINEMATIC -> tickBossCinematic();
            case BOSS_ACTIVE, BOSS_FINISH -> tickBoss();
            default -> {
            }
        }
        if (endUnlocked && (phase == EventPhase.VICTORY_PROCESSING || phase == EventPhase.UNLOCKED)
                && System.currentTimeMillis() >= nextVictoryRetryMillis) {
            nextVictoryRetryMillis = System.currentTimeMillis() + 5_000L;
            issueVictoryRewards();
        }
        tickShardChannels();
        tickShardPassives();
    }

    private void updatePadOccupancy() {
        maintainRitualVisuals();
        Map<String, UUID> previousVisualOccupants = new LinkedHashMap<>(runeVisualOccupants);
        Map<String, UUID> previousOccupants = new LinkedHashMap<>(padOccupants);
        runeVisualOccupants.clear();
        padOccupants.clear();
        if (!coreCharged) {
            if (!previousVisualOccupants.isEmpty() || !previousOccupants.isEmpty()) {
                refreshRuneOverlayVisuals();
            }
            return;
        }
        World world = Bukkit.getWorld(worldName);
        if (world == null) {
            if (!previousVisualOccupants.isEmpty() || !previousOccupants.isEmpty()) {
                refreshRuneOverlayVisuals();
            }
            return;
        }
        // Visual occupancy accepts Creative operators but still rejects dead
        // and Spectator players.  This is presentation-only and cannot start
        // the ritual or enter the official reward roster.
        runeVisualOccupants.putAll(detectRuneOccupants(world, false));
        boolean visualChanged = !previousVisualOccupants.equals(runeVisualOccupants);
        if (visualChanged) {
            refreshRuneOverlayVisuals();
        }
        boolean startRitualPhase = phase == EventPhase.READY_FOR_PLAYERS
                || phase == EventPhase.START_RITUAL;
        boolean transitionPhase = isTransitionRunePhase(phase);
        if (!startRitualPhase && !transitionPhase) {
            if (visualChanged) {
                getLogger().info("RUNE_OCCUPANCY_CHANGED event=" + eventId
                        + " visual=" + runeVisualOccupants.size() + " official=0");
            }
            return;
        }
        padOccupants.putAll(startRitualPhase
                ? detectRuneOccupants(world, true)
                : detectTransitionRuneOccupants(world));
        boolean officialChanged = !previousOccupants.equals(padOccupants);
        if (officialChanged) {
            refreshRuneOverlayVisuals();
        }
        if (visualChanged || officialChanged) {
            getLogger().info("RUNE_OCCUPANCY_CHANGED event=" + eventId
                    + " visual=" + runeVisualOccupants.size()
                    + " official=" + padOccupants.size());
        }
        if (padOccupants.size() == requiredPlayers && phase == EventPhase.READY_FOR_PLAYERS) {
                    beginStartRitualIfReady();
        } else if (phase == EventPhase.START_RITUAL
                && padOccupants.size() != requiredPlayers) {
            cancelRitual("pad occupancy changed");
        }
    }

    private Map<String, UUID> detectTransitionRuneOccupants(World world) {
        Map<String, UUID> detected = detectRuneOccupants(world, true);
        if (officialRewardRoster.isEmpty()) {
            return Map.of();
        }
        detected.entrySet().removeIf(entry -> !officialRewardRoster.contains(entry.getValue()));
        return detected;
    }

    private Map<String, UUID> detectRuneOccupants(World world, boolean officialRoster) {
        Map<String, UUID> occupants = new LinkedHashMap<>();
        Set<UUID> assigned = new HashSet<>();
        List<Player> players = new ArrayList<>(Bukkit.getOnlinePlayers());
        players.sort(Comparator.comparing(player -> player.getUniqueId().toString()));
        for (EventSnapshot.PadSnapshot pad : pads) {
            Location padLocation = new Location(world, pad.x() + 0.5D, pad.y(), pad.z() + 0.5D);
            Player closest = players.stream()
                    .filter(player -> player.getWorld().equals(world) && !player.isDead()
                            && player.getHealth() > 0.0D
                            && player.getGameMode() != org.bukkit.GameMode.SPECTATOR
                            && (!officialRoster || player.getGameMode() != org.bukkit.GameMode.CREATIVE)
                            && !assigned.contains(player.getUniqueId()))
                    .filter(player -> player.getLocation().distanceSquared(padLocation)
                            <= config.padOccupancyRadius() * config.padOccupancyRadius())
                    .min(Comparator.comparingDouble(player -> player.getLocation().distanceSquared(padLocation)))
                    .orElse(null);
            if (closest != null) {
                assigned.add(closest.getUniqueId());
                occupants.put(padKey(pad), closest.getUniqueId());
                if (officialRoster) {
                    registerParticipant(closest);
                }
            }
        }
        return occupants;
    }

    private void maintainRitualVisuals() {
        if (!bootstrapped || !isConfigured() || phase == EventPhase.UNLOCKED || pads.isEmpty()) {
            return;
        }
        World world = Bukkit.getWorld(worldName);
        if (world == null) {
            return;
        }
        Block core = world.getBlockAt(coreX, coreY, coreZ);
        if (!hasCoreOverlay(world, core)) {
            if (System.currentTimeMillis() >= nextRitualVisualRepairMillis) {
                nextRitualVisualRepairMillis = System.currentTimeMillis() + 1_000L;
                getLogger().warning("END_EVENT_CORE_VISUAL_REBUILD event=" + eventId
                        + " phase=" + phase + " reason=loaded_entity_missing");
                rebuildPersistedVisuals();
            }
            return;
        }
        if (!coreCharged) {
            return;
        }
        int missing = 0;
        for (EventSnapshot.PadSnapshot pad : pads) {
            Block floor = world.getBlockAt(pad.x(), pad.y() - 1, pad.z());
            if (findRuneOverlay(world, floor) == null) {
                missing++;
            }
        }
        if (missing > 0 && System.currentTimeMillis() >= nextRitualVisualRepairMillis) {
            nextRitualVisualRepairMillis = System.currentTimeMillis() + 1_000L;
            getLogger().warning("END_EVENT_RUNE_VISUAL_REBUILD event=" + eventId
                    + " phase=" + phase + " missing=" + missing + " expected=" + pads.size());
            rebuildPersistedVisuals();
        }
    }

    private String padKey(EventSnapshot.PadSnapshot pad) {
        return pad.x() + ":" + pad.y() + ":" + pad.z();
    }

    private boolean isEventPad(Block block) {
        return block != null && isConfigured() && block.getWorld() != null
                && block.getWorld().getName().equalsIgnoreCase(worldName)
                && pads.stream().anyMatch(pad -> pad.x() == block.getX()
                        && (pad.y() == block.getY() || pad.y() - 1 == block.getY())
                        && pad.z() == block.getZ());
    }

    @EventHandler(priority = EventPriority.HIGHEST, ignoreCancelled = false)
    public void onEventPadInteract(PlayerInteractEvent event) {
        if (event.getHand() == EquipmentSlot.HAND
                && event.getAction() == Action.RIGHT_CLICK_BLOCK
                && isEventPad(event.getClickedBlock())
                && phase != EventPhase.UNLOCKED) {
            event.setCancelled(true);
        }
    }

    private void beginStartRitualIfReady() {
        if (phase != EventPhase.READY_FOR_PLAYERS || padOccupants.size() != requiredPlayers) {
            return;
        }
        phaseDeadlineMillis = System.currentTimeMillis() + config.startRitualTimeoutSeconds() * 1000L;
        transitionRuneController.reset();
        transitionRuneRenderStates.clear();
        if (transition(EventPhase.START_RITUAL, "all unique pads occupied", eventId + ":start-ritual")) {
            announceEventTitle("§5РИТУАЛ НАЧАТ", "§dУдерживайте руны ещё пять секунд", true);
            getLogger().info("RITUAL_STARTED event=" + eventId + " generation=" + generation
                    + " hold_ms=5000 timeout_seconds=" + config.startRitualTimeoutSeconds());
        }
    }

    /** Current flow uses a real five-second continuous hold on every unique start rune. */
    private void tickStartRitual() {
        if (phase != EventPhase.START_RITUAL) {
            return;
        }
        long now = System.currentTimeMillis();
        if (phaseDeadlineMillis <= 0L || now >= phaseDeadlineMillis) {
            cancelRitual("start ritual timeout");
            return;
        }
        Set<UUID> candidateRoster = new LinkedHashSet<>(padOccupants.values());
        List<TransitionRunePolicy.RuneOccupancy> occupancies = new ArrayList<>();
        for (Map.Entry<String, UUID> entry : padOccupants.entrySet()) {
            Player player = Bukkit.getPlayer(entry.getValue());
            boolean eligible = player != null && player.isOnline() && !player.isDead()
                    && player.getHealth() > 0.0D && player.getGameMode() != GameMode.SPECTATOR
                    && player.getGameMode() != GameMode.CREATIVE && isArenaLocation(player.getLocation());
            occupancies.add(new TransitionRunePolicy.RuneOccupancy(
                    entry.getValue(), entry.getKey(), player != null && player.isOnline(),
                    player != null && !player.isDead() && player.getHealth() > 0.0D,
                    eligible));
        }
        TransitionRuneController.Observation observation = transitionRuneController.observe(
                candidateRoster, occupancies, now);
        for (EventSnapshot.PadSnapshot pad : pads) {
            String key = padKey(pad);
            transitionRuneRenderStates.put(key, padOccupants.containsKey(key)
                    ? observation.renderState() : TransitionRuneController.RenderState.EMPTY);
        }
        refreshRuneOverlayVisuals();
        if (observation.justCompleted()) {
            completeStartRitual(candidateRoster);
        }
    }

    private void completeStartRitual(Set<UUID> candidateRoster) {
        if (candidateRoster == null || candidateRoster.size() != requiredPlayers
                || phase != EventPhase.START_RITUAL) {
            cancelRitual("start ritual roster changed");
            return;
        }
        try {
            RewardRoster roster = RewardRoster.commitExactly(candidateRoster, requiredPlayers);
            if (!officialRewardRoster.isEmpty() && !officialRewardRoster.equals(roster.players())) {
                cancelRitual("committed roster mismatch after recovery");
                getLogger().warning("RITUAL_ROSTER_MISMATCH event=" + eventId
                        + " committed=" + officialRewardRoster + " occupied=" + roster.players());
                return;
            }
            if (officialRewardRoster.isEmpty()) {
                officialRewardRoster.addAll(roster.players());
            }
            participantUuids.addAll(roster.players());
        } catch (IllegalArgumentException invalid) {
            cancelRitual("roster uniqueness failed");
            return;
        }
        generation = Math.max(1L, generation + 1L);
        cancelSessionTasks();
        resetEncounterTaskRegistry(generation);
        attemptLifecycle.begin(generation, new LinkedHashSet<>(officialRewardRoster));
        realitySplitChamberController.clear();
        clearCombatAiState();
        lootIssuedEntityUuids.clear();
        activeWave = 1;
        removeTransitionRuneVisuals();
        pads.clear();
        padOccupants.clear();
        runeVisualOccupants.clear();
        transitionRuneRenderStates.clear();
        if (!transition(EventPhase.WAVE_1, "start ritual hold complete; official roster frozen",
                eventId + ":roster:" + generation, false)) {
            officialRewardRoster.clear();
            attemptLifecycle.clear();
            activeWave = 0;
            forcePhase(EventPhase.READY_FOR_PLAYERS, "roster transition rejected");
            return;
        }
        if (!saveStateSync()) {
            officialRewardRoster.clear();
            rewardStatuses.clear();
            nightCloakRolls.clear();
            attemptLifecycle.clear();
            activeWave = 0;
            forcePhase(EventPhase.READY_FOR_PLAYERS, "official roster commit could not be persisted");
            getLogger().severe("RITUAL_COMMIT_FAILED event=" + eventId + " generation=" + generation);
            return;
        }
        getLogger().info("RITUAL_COMPLETED event=" + eventId + " roster=" + officialRewardRoster
                + " hold_ms=5000");
        spawnWave(1, false);
    }

    private void cancelRitual(String reason) {
        if (phase == EventPhase.START_RITUAL) {
            phaseDeadlineMillis = 0L;
            transitionRuneController.reset();
            transitionRuneRenderStates.clear();
            boolean hadPadOccupants = !padOccupants.isEmpty();
            boolean hadRuneVisualOccupants = !runeVisualOccupants.isEmpty();
            padOccupants.clear();
            runeVisualOccupants.clear();
            if (hadPadOccupants || hadRuneVisualOccupants) {
                refreshRuneOverlayVisuals();
            }
            transition(EventPhase.READY_FOR_PLAYERS, reason, eventId + ":ritual-cancel:" + UUID.randomUUID());
            getLogger().info("RITUAL_CANCELLED event=" + eventId + " reason=" + reason);
        }
    }

    private void updateCombatHelpers() {
        if (!isCombatPhase()) {
            return;
        }
        for (Player player : Bukkit.getOnlinePlayers()) {
            if (isActiveArenaParticipant(player)) {
                combatHelpers.add(player.getUniqueId());
                registerParticipant(player);
                playerCategory(player, officialRewardRoster.contains(player.getUniqueId())
                        ? "official_participant" : "combat_helper");
            }
        }
    }

    /**
     * One bounded controller owns wave targeting and the containment watchdog.
     * Natural mobs are never included because every lookup starts in
     * ownedEntities and checks the event role tag.
     */
    private void tickWaveMobAi() {
        boolean hasTestWave = false;
        for (Entity entity : new ArrayList<>(ownedEntities.values())) {
            String kind = readString(entity, keyKind);
            if (!isWaveCombatKind(kind) || !isLiveOwnedEntity(entity.getUniqueId())) {
                continue;
            }
            ensureEventCombatAi(entity);
            hasTestWave |= !isOfficialEntity(entity);
        }
        enforceWaveMobContainment();
        if (!isCombatPhase() && !hasTestWave) {
            return;
        }
        long now = System.currentTimeMillis();
        renderWaveMobRoleVisuals(now);
        List<Player> candidates = activeLivingPlayers();
        List<UUID> candidateIds = candidates.stream()
                .map(Player::getUniqueId)
                .sorted(Comparator.comparing(UUID::toString))
                .toList();
        boolean rotateTargets = now >= nextWaveTargetMillis;
        for (Entity entity : new ArrayList<>(ownedEntities.values())) {
            String kind = readString(entity, keyKind);
            if (!(entity instanceof Mob mob) || !isWaveCombatKind(kind)
                    || !isLiveOwnedEntity(entity.getUniqueId())
                    || !isWaveAiCombatEntity(entity)) {
                continue;
            }
            List<Player> entityCandidates = candidates.stream()
                    .filter(player -> isWaveTargetAllowed(entity, player))
                    .toList();
            List<UUID> entityCandidateIds = entityCandidates.stream()
                    .map(Player::getUniqueId)
                    .sorted(Comparator.comparing(UUID::toString))
                    .toList();
            Player target = mob.getTarget() instanceof Player player
                    && isWaveTargetAllowed(entity, player) ? player : null;
            UUID previousTargetId = target == null ? null : target.getUniqueId();
            if (mob.getTarget() != null && target == null) {
                mob.setTarget(null);
                mob.getPathfinder().stopPathfinding();
                nextWavePathRequestMillis.remove(entity.getUniqueId());
                lastWavePathLogMillis.remove(entity.getUniqueId());
            }
            int entityWave = readInt(entity, keyWave, activeWave);
            EndRiftObjective.Objective entityObjective = objectiveForWave(entityWave);
            Player markedTarget = entityObjective == EndRiftObjective.Objective.RIFT_HUNT
                    && waveTwoMarkedPlayerUuid != null
                    ? Bukkit.getPlayer(waveTwoMarkedPlayerUuid) : null;
            boolean markedTargetEligible = markedTarget != null
                    && isWaveTargetAllowed(entity, markedTarget);
            boolean markedTargetPriority = SkeletonCombatPolicy.shouldPrioritizeMarkedTarget(
                    entityObjective, entityObjective == EndRiftObjective.Objective.RIFT_HUNT,
                    markedTargetEligible);
            boolean markedTargetNeedsRefresh = markedTargetPriority
                    && (target == null || !target.getUniqueId().equals(markedTarget.getUniqueId()));
            if ((rotateTargets || target == null || markedTargetNeedsRefresh)
                    && !entityCandidateIds.isEmpty()) {
                if (markedTargetPriority) {
                    target = markedTarget;
                } else {
                    UUID current = target == null ? null : target.getUniqueId();
                    Deque<UUID> targetMemory = recentWaveTargets.get(entity.getUniqueId());
                    EndRiftAiPolicy.TargetChoice choice = EndRiftAiPolicy.chooseFairTarget(
                            entityCandidateIds, current,
                            targetMemory == null ? List.of() : new ArrayList<>(targetMemory),
                            waveTargetCursor++);
                    target = choice.target() == null ? null : Bukkit.getPlayer(choice.target());
                }
                if (target != null && isWaveTargetAllowed(entity, target)) {
                    rememberWaveTarget(entity.getUniqueId(), target.getUniqueId());
                    mob.setTarget(target);
                    String targetMessage = "WAVE_AI_TARGET entity=" + entity.getUniqueId()
                            + " role=" + kind + " target=" + target.getUniqueId()
                            + " rotation=" + (markedTargetPriority ? "marked"
                            : rotateTargets ? "scheduled" : "reacquired")
                            + " objective=player";
                    if (previousTargetId == null
                            || !previousTargetId.equals(target.getUniqueId())) {
                        getLogger().info(targetMessage);
                    } else {
                        getLogger().fine(targetMessage);
                    }
                } else {
                    target = null;
                    mob.setTarget(null);
                    mob.getPathfinder().stopPathfinding();
                }
            }
            if (target == null || !isWaveTargetAllowed(entity, target)) {
                continue;
            }
            if (mob instanceof Skeleton skeleton) {
                maintainSkeletonCombatPosture(skeleton, target, kind, now);
            } else {
                maintainWaveMobPath(mob, target, kind, now);
            }
            watchWaveMobProgress(mob, target, kind, now);
        }
        enforceWaveMobContainment();
        if (rotateTargets && !candidateIds.isEmpty()) {
            nextWaveTargetMillis = now
                    + randomSeconds(config.bossTargetMinSeconds(), config.bossTargetMaxSeconds()) * 1000L;
        }
    }

    private boolean isWaveTargetAllowed(Entity entity, Player player) {
        if (!isCombatTarget(player) || !realitySplitTargetAllowed(entity, player)) {
            return false;
        }
        return !isCurrentCollapseGuard(entity) || currentCollapseTargetAllowed(entity, player);
    }

    private void rememberWaveTarget(UUID entityId, UUID targetId) {
        if (entityId == null || targetId == null) {
            return;
        }
        int memoryLimit = Math.max(1, config == null ? 3 : config.bossRecentTargetMemory());
        Deque<UUID> memory = recentWaveTargets.computeIfAbsent(entityId, ignored -> new ArrayDeque<>());
        List<UUID> updated = EndRiftAiPolicy.rememberTarget(
                new ArrayList<>(memory), targetId, memoryLimit);
        memory.clear();
        memory.addAll(updated);
    }

    /**
     * If Paper accepts a path but collision/navigation leaves a mob in place,
     * give it one safe steering retry. This is deliberately a velocity nudge,
     * never a teleport, and it preserves the same Core radius and Y-level
     * checks as normal movement.
     */
    private void watchWaveMobProgress(Mob mob, Player target, String kind, long now) {
        if (mob == null || !isLiveOwnedEntity(mob.getUniqueId())
                || !isCombatTarget(target)) {
            return;
        }
        UUID entityId = mob.getUniqueId();
        Location current = mob.getLocation();
        Location previous = waveLastProgressLocations.put(entityId, current.clone());
        long progressAt = waveLastProgressAt.getOrDefault(entityId, 0L);
        if (previous == null || previous.getWorld() == null
                || !previous.getWorld().equals(current.getWorld())
                || horizontalDistanceSquared(previous, current) >= WAVE_MOB_PROGRESS_DISTANCE_SQUARED) {
            waveLastProgressAt.put(entityId, now);
            return;
        }

        if (mob instanceof Skeleton skeleton && target != null) {
            SkeletonCombatPolicy.WaveBehavior behavior = SkeletonCombatPolicy.behaviorFor(
                    objectiveForWave(readInt(skeleton, keyWave, 1)), isSkeletonMiniBoss(skeleton));
            double distance = Math.sqrt(horizontalDistanceSquared(skeleton.getLocation(), target.getLocation()));
            if (distance >= behavior.minimumRange() - 1.0D
                    && distance <= behavior.maximumRange() + 1.0D) {
                waveLastProgressAt.put(entityId, now);
                return;
            }
        }
        if (target != null && horizontalDistanceSquared(mob.getLocation(), target.getLocation()) <= 10.24D) {
            // Melee mobs may hold their ground while their attack cooldown is
            // active. Do not treat a readable close-range engagement as a
            // navigation failure.
            waveLastProgressAt.put(entityId, now);
            return;
        }
        if (progressAt <= 0L) {
            waveLastProgressAt.put(entityId, now);
            return;
        }
        if (now - progressAt < WAVE_MOB_STUCK_TIMEOUT_MILLIS
                || now < nextWaveStuckRepositionMillis.getOrDefault(entityId, 0L)) {
            return;
        }
        Location anchor = coreCombatAnchorLocation();
        if (anchor == null) {
            return;
        }
        Location destination = waveTacticalDestination(mob, target, kind, now);
        if (destination == null || isCoreBlockPosition(destination)) {
            destination = findSafeCombatLocation(anchor, waveCoreFlankDestination(anchor, mob),
                    boundedCombatRadius(config.containmentRadius()) - 1.0D,
                    MIN_WAVE_CORE_DISTANCE_BLOCKS, realitySplitChamberId(mob));
        }
        if (destination == null || outsideCombatVertical(destination, anchor)
                || horizontalDistanceSquared(destination, anchor)
                > boundedCombatRadius(config.containmentRadius()) * boundedCombatRadius(config.containmentRadius())) {
            return;
        }
        mob.getPathfinder().stopPathfinding();
        double speed = mob.getType() == EntityType.SPIDER ? 1.20D
                : EVENT_KIND_ELITE.equals(kind) ? 1.15D : 1.05D;
        boolean moved = mob.getPathfinder().moveTo(destination, speed);
        if (!moved) {
            moved = requestBoundedCombatMovement(mob, destination, speed, anchor,
                    boundedCombatRadius(config.containmentRadius()), MIN_WAVE_CORE_DISTANCE_BLOCKS,
                    "WAVE_AI_STUCK_REPOSITION");
        }
        nextWaveStuckRepositionMillis.put(entityId, now + WAVE_MOB_STUCK_REPOSITION_COOLDOWN_MILLIS);
        waveLastProgressAt.put(entityId, now);
        getLogger().info("WAVE_AI_STUCK_REPOSITION entity=" + entityId
                + " target=" + target.getUniqueId()
                + " moved=" + moved + " destination=" + locationText(destination));
    }

    /**
     * Give each event role a small, throttled particle signature. The actual
     * entity textures remain client-bound; this aura only makes the role and
     * elite status readable in a crowded five-player fight.
     */
    private void renderWaveMobRoleVisuals(long now) {
        if (now < nextWaveRoleVisualMillis || eventAudience().isEmpty()) {
            return;
        }
        nextWaveRoleVisualMillis = now + 900L;
        int rendered = 0;
        for (Entity entity : new ArrayList<>(ownedEntities.values())) {
            String kind = readString(entity, keyKind);
            if (!(entity instanceof Mob mob) || !isWaveCombatKind(kind)
                    || !isLiveOwnedEntity(entity.getUniqueId()) || rendered++ >= 16) {
                continue;
            }
            Location point = mob.getLocation().add(0.0D, 1.0D, 0.0D);
            if (EVENT_KIND_ELITE.equals(kind) || EVENT_KIND_WAVE_GUARDIAN.equals(kind)) {
                spawnEventParticle(point, Particle.REVERSE_PORTAL, 2,
                        0.22D, 0.45D, 0.22D, 0.01D);
                spawnEventParticle(point, Particle.DUST, 1,
                        0.08D, 0.18D, 0.08D, 0.0D,
                        new Particle.DustOptions(Color.fromRGB(195, 74, 255), 1.15F));
            } else if (mob instanceof Skeleton) {
                spawnEventParticle(point, Particle.SOUL_FIRE_FLAME, 2,
                        0.18D, 0.35D, 0.18D, 0.005D);
                spawnEventParticle(point, Particle.DUST, 1,
                        0.08D, 0.16D, 0.08D, 0.0D,
                        new Particle.DustOptions(Color.fromRGB(89, 210, 255), 1.0F));
            } else if (mob instanceof Spider) {
                spawnEventParticle(point, Particle.CRIT, 2,
                        0.22D, 0.28D, 0.22D, 0.01D);
                spawnEventParticle(point, Particle.DUST, 1,
                        0.08D, 0.16D, 0.08D, 0.0D,
                        new Particle.DustOptions(Color.fromRGB(255, 76, 106), 1.0F));
            } else {
                spawnEventParticle(point, Particle.PORTAL, 2,
                        0.18D, 0.35D, 0.18D, 0.01D);
            }
        }
    }

    /**
     * Ranged skeletons keep a readable firing lane instead of pathing into
     * melee range. The destination is still resolved by the common collision,
     * height, Core and arena-bound checks, so this posture cannot escape the
     * event box or walk through hazards.
     */
    private void maintainSkeletonCombatPosture(Skeleton skeleton, Player target,
                                                String kind, long now) {
        if (skeleton == null || target == null || !isCombatTarget(target)
                || now < nextWavePathRequestMillis.getOrDefault(skeleton.getUniqueId(), 0L)) {
            return;
        }
        Location anchor = coreCombatAnchorLocation();
        if (anchor == null) {
            return;
        }
        boolean miniBoss = isSkeletonMiniBoss(skeleton);
        int wave = readInt(skeleton, keyWave, 1);
        EndRiftObjective.Objective objective = objectiveForWave(wave);
        SkeletonCombatPolicy.WaveBehavior behavior = SkeletonCombatPolicy.behaviorFor(objective, miniBoss);
        int maneuverCycle = (int) Math.floorMod(
                now / SKELETON_MANEUVER_CYCLE_MILLIS, 4L);
        int maneuverSlot = Math.floorMod(skeleton.getUniqueId().hashCode(), 4);
        SkeletonCombatPolicy.Maneuver maneuver = SkeletonCombatPolicy.maneuverFor(
                objective, miniBoss, maneuverCycle, maneuverSlot);
        double distance = Math.sqrt(horizontalDistanceSquared(skeleton.getLocation(), target.getLocation()));
        double minimum = behavior.minimumRange();
        double maximum = behavior.maximumRange();
        if (distance >= minimum && distance <= maximum) {
            skeleton.getPathfinder().stopPathfinding();
            nextWavePathRequestMillis.put(skeleton.getUniqueId(), now + WAVE_PATH_REQUEST_INTERVAL_MILLIS);
            return;
        }
        Location destination = skeletonRangedDestination(anchor, skeleton, target,
                minimum + 2.0D, behavior, maneuver);
        if (destination == null) {
            nextWavePathRequestMillis.put(skeleton.getUniqueId(), now + WAVE_PATH_REQUEST_INTERVAL_MILLIS);
            return;
        }
        double speed = miniBoss ? 1.15D : 1.05D;
        boolean moved = skeleton.getPathfinder().moveTo(destination, speed);
        if (!moved) {
            moved = requestBoundedCombatMovement(skeleton, destination, speed, anchor,
                    boundedCombatRadius(config.containmentRadius()), MIN_WAVE_CORE_DISTANCE_BLOCKS,
                    "WAVE_SKELETON_PATH");
        }
        nextWavePathRequestMillis.put(skeleton.getUniqueId(), now + WAVE_PATH_REQUEST_INTERVAL_MILLIS);
        if (moved) {
            long lastLog = lastWavePathLogMillis.getOrDefault(skeleton.getUniqueId(), 0L);
            if (now - lastLog >= 2_000L) {
                lastWavePathLogMillis.put(skeleton.getUniqueId(), now);
                String message = "WAVE_SKELETON_KITE entity=" + skeleton.getUniqueId()
                        + " variant=" + (miniBoss ? "MINIBOSS" : "COMMON")
                        + " behavior=" + behavior.id()
                        + " target=" + target.getUniqueId() + " distance=" + String.format(Locale.ROOT, "%.2f", distance)
                        + " firing_lane=" + String.format(Locale.ROOT, "%.1f", minimum)
                        + "-" + String.format(Locale.ROOT, "%.1f", maximum)
                        + " maneuver=" + maneuver
                        + " destination=" + locationText(destination);
                // The first successful posture is a useful state transition;
                // later two-second refreshes remain debug-only.
                if (lastLog == 0L) {
                    getLogger().info(message);
                } else {
                    getLogger().fine(message);
                }
            }
        }
    }

    /** Hold the Wave IV artillery ring while the Core remains the objective. */
    private Location skeletonRangedDestination(Location anchor, Skeleton skeleton,
                                               Player target, double desiredDistance,
                                               SkeletonCombatPolicy.WaveBehavior behavior,
                                               SkeletonCombatPolicy.Maneuver maneuver) {
        if (anchor == null || skeleton == null || target == null) {
            return null;
        }
        Location tacticalTarget = target.getLocation();
        if (behavior != null && behavior.guardsObjective()
                && readInt(skeleton, keyWave, 0) == 3) {
            Location portal = nearestOpenPortal(skeleton.getLocation());
            if (portal != null && horizontalDistanceSquared(target.getLocation(), portal) > 36.0D) {
                // Keep a portal sentinel on a safe firing station around the
                // objective while its Mob target remains the player. This
                // prevents the skeleton from abandoning the portal whenever
                // somebody crosses the arena.
                tacticalTarget = portal;
            }
        }
        Vector radial = skeleton.getLocation().toVector().subtract(tacticalTarget.toVector());
        radial.setY(0.0D);
        if (radial.lengthSquared() < 0.04D) {
            radial = tacticalTarget.toVector().subtract(anchor.toVector());
            radial.setY(0.0D);
        }
        if (radial.lengthSquared() < 0.04D) {
            radial = new Vector(1.0D, 0.0D, 0.0D);
        }
        radial.normalize();
        Location preferred = tacticalTarget.clone().add(radial.multiply(desiredDistance));
        Vector side = new Vector(-radial.getZ(), 0.0D, radial.getX());
        long stableBits = skeleton.getUniqueId().getLeastSignificantBits();
        double sideSign = (stableBits & 1L) == 0L ? 1.0D : -1.0D;
        if (maneuver != null) {
            switch (maneuver) {
                case SIDE_STEP -> preferred.add(side.multiply(sideSign * 2.0D));
                case CROSS_FIRE -> preferred.add(side.multiply(-sideSign * 2.75D));
                case FALLBACK -> preferred.add(radial.multiply(2.0D));
                case HOLD_LINE -> { }
            }
        }
        return findSafeCombatLocation(anchor, preferred,
                boundedCombatRadius(config.containmentRadius()) - 1.0D,
                MIN_WAVE_CORE_DISTANCE_BLOCKS, realitySplitChamberId(skeleton));
    }

    private Location nearestOpenPortal(Location from) {
        if (from == null || from.getWorld() == null) {
            return null;
        }
        List<Location> portals = wavePortals.getOrDefault(3, List.of());
        List<PortalCapturePolicy.PortalState> states = portalCaptureStates.getOrDefault(3, List.of());
        Location nearest = null;
        double nearestDistance = Double.POSITIVE_INFINITY;
        for (int index = 0; index < portals.size(); index++) {
            Location portal = portals.get(index);
            if (portal == null || !from.getWorld().equals(portal.getWorld())
                    || index < states.size() && states.get(index).completed()) {
                continue;
            }
            double distance = horizontalDistanceSquared(from, portal);
            if (distance < nearestDistance) {
                nearest = portal;
                nearestDistance = distance;
            }
        }
        return nearest;
    }

    private void enforceWaveMobContainment() {
        Location anchor = coreCombatAnchorLocation();
        if (anchor == null) {
            return;
        }
        double radius = boundedCombatRadius(config.containmentRadius());
        for (Entity entity : new ArrayList<>(ownedEntities.values())) {
            String kind = readString(entity, keyKind);
            if (isWaveCombatKind(kind) && isLiveOwnedEntity(entity.getUniqueId())) {
                enforceCombatLeash(entity, anchor, radius, "WAVE_AI_LEASH");
            }
        }
    }

    /**
     * Select a combat destination from the mob's stable job.  The target is
     * still authoritative, but each wave role gets a different battlefield
     * intention: breakers orbit the Core, artillery holds a rear ring, and
     * hunters attack from a moving flank.  The final location is always
     * passed through the same collision/height/Core safety resolver.
     */
    /** Select a readable, bounded battlefield position for the current objective tactic. */
    private Location waveTacticalDestination(Mob mob, Player target, String kind, long now) {
        Location anchor = coreCombatAnchorLocation();
        if (anchor == null || mob == null || target == null || !isCombatTarget(target)) {
            return null;
        }
        CombatTacticsPolicy.MobTactic tactic = combatTactic(
                mob, Math.floorMod(mob.getUniqueId().hashCode(), 128));
        Location preferred;
        switch (tactic) {
            case OBELISK_GUARD, GATE_DEFENDER -> preferred = isCoreBlockPosition(target.getLocation())
                    ? stableCombatRingLocation(anchor, mob, 5.0D, 8.0D) : target.getLocation();
            case SKELETON_FIRELINE -> preferred = stableCombatRingLocation(anchor, mob, 8.0D, 11.0D);
            case FOG_SCOUT, ELITE_HUNTER -> preferred = flankTargetLocation(anchor, mob, target);
            case MARKED_HUNTER, CARRIER_ESCORT, RING_GUARD, CHAMBER_BLADE, ASSAULT
                    -> preferred = target.getLocation();
            default -> preferred = target.getLocation();
        }
        if (preferred == null) {
            return null;
        }
        String maneuverRole = EVENT_KIND_ELITE.equals(kind) || EVENT_KIND_WAVE_GUARDIAN.equals(kind)
                ? "ELITE" : "MOB";
        int maneuverWave = Math.max(1, readInt(mob, keyWave, activeWave));
        int maneuverCycle = (int) Math.floorMod(now / SKELETON_MANEUVER_CYCLE_MILLIS, 4L);
        int maneuverSlot = Math.floorMod(mob.getUniqueId().hashCode(), 4);
        CombatTacticsPolicy.MobManeuver maneuver = CombatTacticsPolicy.maneuverFor(
                objectiveForWave(maneuverWave), maneuverRole, maneuverCycle, maneuverSlot);
        preferred = applyMobManeuver(preferred, anchor, mob, target, maneuver);
        preferred = constrainRealitySplitPreferred(anchor, preferred, mob);
        Location destination = findSafeCombatLocation(anchor, preferred,
                boundedCombatRadius(config.containmentRadius()) - 1.0D,
                MIN_WAVE_CORE_DISTANCE_BLOCKS, realitySplitChamberId(mob));
        if (destination != null) {
            getLogger().fine("WAVE_AI_TACTIC_DESTINATION entity=" + mob.getUniqueId()
                    + " role=" + kind + " tactic=" + tactic
                    + " maneuver=" + maneuver + " destination=" + locationText(destination));
        }
        return destination;
    }

    private Location applyMobManeuver(Location preferred, Location anchor, Mob mob,
                                      Player target, CombatTacticsPolicy.MobManeuver maneuver) {
        if (preferred == null || anchor == null || mob == null || maneuver == null
                || maneuver == CombatTacticsPolicy.MobManeuver.HOLD_LINE) {
            return preferred;
        }
        Location origin = target == null ? anchor : target.getLocation();
        Vector away = preferred.toVector().subtract(origin.toVector());
        away.setY(0.0D);
        if (away.lengthSquared() < 0.04D) {
            away = mob.getLocation().toVector().subtract(origin.toVector());
            away.setY(0.0D);
        }
        if (away.lengthSquared() < 0.04D) {
            away = new Vector(1.0D, 0.0D, 0.0D);
        }
        away.normalize();
        Vector side = new Vector(-away.getZ(), 0.0D, away.getX());
        long stableBits = mob.getUniqueId().getLeastSignificantBits();
        double sideSign = (stableBits & 1L) == 0L ? 1.0D : -1.0D;
        Location moved = preferred.clone();
        switch (maneuver) {
            case SIDE_STEP -> moved.add(side.multiply(sideSign * 1.5D));
            case CROSS_FIRE -> moved.add(side.multiply(-sideSign * 2.25D));
            case FALLBACK -> moved.add(away.multiply(1.5D));
            case PINCH -> moved.add(side.multiply(sideSign * 1.25D));
            case HOLD_LINE -> { }
        }
        return moved;
    }

    private Location stableCombatRingLocation(Location anchor, Entity entity,
                                               double minimum, double maximum) {
        if (anchor == null || entity == null) {
            return null;
        }
        long bits = entity.getUniqueId().getMostSignificantBits()
                ^ Long.rotateLeft(entity.getUniqueId().getLeastSignificantBits(), 17);
        double angle = Math.floorMod((int) (bits ^ (bits >>> 32)), 3600) / 3600.0D
                * Math.PI * 2.0D;
        double distance = minimum + Math.floorMod((int) (bits >>> 19), 1000) / 1000.0D
                * Math.max(0.0D, maximum - minimum);
        return anchor.clone().add(Math.cos(angle) * distance, 0.0D,
                Math.sin(angle) * distance);
    }

    private Location flankTargetLocation(Location anchor, Mob mob, Player target) {
        if (anchor == null || mob == null || target == null) {
            return null;
        }
        Location targetLocation = target.getLocation();
        if (isCoreBlockPosition(targetLocation)) {
            return stableCombatRingLocation(anchor, mob, 6.0D, 9.0D);
        }
        Vector radial = targetLocation.toVector().subtract(anchor.toVector());
        radial.setY(0.0D);
        if (radial.lengthSquared() < 0.01D) {
            radial = new Vector(1.0D, 0.0D, 0.0D);
        }
        radial.normalize();
        Vector side = new Vector(-radial.getZ(), 0.0D, radial.getX());
        long bits = mob.getUniqueId().getLeastSignificantBits();
        double direction = (bits & 1L) == 0L ? 1.0D : -1.0D;
        double distance = 2.75D + Math.floorMod((int) (bits >>> 13), 3) * 0.65D;
        return targetLocation.clone().add(side.multiply(direction * distance));
    }

    /**
     * Endermen and skeletons do not reliably start useful navigation from a
     * Bukkit target assignment alone. Request a bounded path for mobile wave
     * mobs so the target controller produces visible movement as well as combat
     * intent. Skeletons use the ranged posture below and never receive a mob
     * target.
     */
    private void maintainWaveMobPath(Mob mob, Player target, String kind, long now) {
        if (mob == null || target == null || !isCombatTarget(target)
                || now < nextWavePathRequestMillis.getOrDefault(mob.getUniqueId(), 0L)) {
            return;
        }
        Location anchor = coreCombatAnchorLocation();
        if (anchor == null) {
            return;
        }
        Location destination = waveTacticalDestination(mob, target, kind, now);
        if (destination == null || isCoreBlockPosition(destination)) {
            // A player standing on the Core is a valid combat target, but it
            // is not a valid mob destination.  Give each mob a stable flank
            // so a whole wave surrounds the Core instead of collapsing onto
            // one fallback cell or repeatedly pushing against the block.
            destination = findSafeCombatLocation(anchor, waveCoreFlankDestination(anchor, mob),
                    boundedCombatRadius(config.containmentRadius()) - 1.0D,
                    MIN_WAVE_CORE_DISTANCE_BLOCKS);
        }
        if (destination == null
                || horizontalDistanceSquared(destination, anchor)
                > boundedCombatRadius(config.containmentRadius()) * boundedCombatRadius(config.containmentRadius())
                || outsideCombatVertical(destination, anchor)) {
            mob.setTarget(null);
            nextWavePathRequestMillis.put(mob.getUniqueId(), now + WAVE_PATH_REQUEST_INTERVAL_MILLIS);
            return;
        }
        if (horizontalDistanceSquared(mob.getLocation(), destination) <= 4.0D) {
            mob.getPathfinder().stopPathfinding();
            nextWavePathRequestMillis.put(mob.getUniqueId(), now + WAVE_PATH_REQUEST_INTERVAL_MILLIS);
            return;
        }
        double speed = mob.getType() == EntityType.SPIDER
                ? 1.20D : EVENT_KIND_ELITE.equals(kind) ? 1.15D : 1.05D;
        boolean moved = mob.getPathfinder().moveTo(destination, speed);
        if (!moved) {
            moved = requestBoundedCombatMovement(mob, destination, speed, anchor,
                    boundedCombatRadius(config.containmentRadius()), MIN_WAVE_CORE_DISTANCE_BLOCKS,
                    "WAVE_AI_PATH");
        }
        if (moved) {
            nextWavePathRequestMillis.put(mob.getUniqueId(), now + WAVE_PATH_REQUEST_INTERVAL_MILLIS);
            long lastLog = lastWavePathLogMillis.getOrDefault(mob.getUniqueId(), 0L);
            if (now - lastLog >= 2_000L) {
                lastWavePathLogMillis.put(mob.getUniqueId(), now);
                String message = "WAVE_AI_PATH entity=" + mob.getUniqueId()
                        + " role=" + kind + " target=" + target.getUniqueId()
                        + " tactic=" + combatTactic(mob, mob.getUniqueId().hashCode())
                        + " speed=" + speed + " destination=" + locationText(destination);
                if (lastLog == 0L) {
                    getLogger().info(message);
                } else {
                    getLogger().fine(message);
                }
            }
        }
    }

    /**
     * Apply one collision-checked horizontal nudge when Paper cannot produce a
     * path.  This is deliberately not a teleport and never changes Y, so a
     * transient navigation failure cannot make a mob fly through the arena.
     */
    private boolean requestBoundedCombatMovement(Mob mob, Location destination, double speed,
                                                 Location anchor, double radius,
                                                 double minimumCoreDistance, String logMarker) {
        if (mob == null || destination == null || anchor == null
                || !mob.isValid() || mob.isDead()) {
            return false;
        }
        Location current = mob.getLocation();
        CombatMovementPolicy.Step step = CombatMovementPolicy.stepTowards(
                current.getX(), current.getY(), current.getZ(),
                destination.getX(), destination.getY(), destination.getZ(), speed);
        if (step.equals(CombatMovementPolicy.Step.ZERO)) {
            return false;
        }
        if (step.horizontalLength() > MAX_COMBAT_STEP_BLOCKS + 0.0001D) {
            return false;
        }
        Location next = current.clone().add(step.x(), step.y(), step.z());
        if (!isSafeCombatStep(anchor, next, radius, minimumCoreDistance)) {
            return false;
        }
        Vector velocity = mob.getVelocity().clone();
        double vertical = velocity.getY();
        if (!Double.isFinite(vertical)) {
            vertical = 0.0D;
        }
        velocity.setX(step.x()).setY(Math.max(-0.20D, Math.min(0.20D, vertical))).setZ(step.z());
        mob.setVelocity(velocity);
        getLogger().fine(logMarker + " entity=" + mob.getUniqueId()
                + " fallback=velocity step=" + String.format(Locale.ROOT, "%.3f,%.3f", step.x(), step.z())
                + " destination=" + locationText(destination));
        return true;
    }

    private boolean isSafeCombatStep(Location anchor, Location candidate,
                                     double radius, double minimumCoreDistance) {
        if (anchor == null || candidate == null || candidate.getWorld() == null
                || !anchor.getWorld().equals(candidate.getWorld())
                || !CombatMovementPolicy.withinBounds(anchor.getX(), anchor.getY(), anchor.getZ(),
                candidate.getX(), candidate.getY(), candidate.getZ(), radius,
                configuredCombatVerticalRadius(), minimumCoreDistance)) {
            return false;
        }
        Block feet = candidate.getBlock();
        Block head = feet.getRelative(BlockFace.UP);
        Block floor = feet.getRelative(BlockFace.DOWN);
        return feet.isPassable() && head.isPassable() && floor.getType().isSolid()
                && !feet.isLiquid() && !head.isLiquid() && !floor.isLiquid()
                && !isFireBlock(feet) && !isFireBlock(head) && !isFireBlock(floor)
                && !isWebBlock(feet) && !isWebBlock(head) && !isWebBlock(floor)
                && !isTemporaryMovementHazard(feet) && !isTemporaryMovementHazard(head)
                && !isTemporaryMovementHazard(floor) && !isCoreBlockPosition(candidate);
    }

    private Location waveCoreFlankDestination(Location anchor, Mob mob) {
        if (anchor == null || mob == null || mob.getUniqueId() == null) {
            return null;
        }
        long bits = mob.getUniqueId().getMostSignificantBits()
                ^ Long.rotateLeft(mob.getUniqueId().getLeastSignificantBits(), 21);
        double angle = Math.floorMod((int) (bits ^ (bits >>> 32)), 3600) / 3600.0D
                * Math.PI * 2.0D;
        Vector radial = new Vector(Math.cos(angle), 0.0D, Math.sin(angle));
        double ring = MIN_WAVE_CORE_DISTANCE_BLOCKS + 1.0D
                + Math.floorMod((int) (bits >>> 17), 4) * 1.25D;
        double maximum = Math.max(MIN_WAVE_CORE_DISTANCE_BLOCKS + 0.5D,
                boundedCombatRadius(config.containmentRadius()) - 2.0D);
        return anchor.clone().add(radial.multiply(Math.min(ring, maximum)));
    }

    private boolean isWaveCombatKind(String kind) {
        return EVENT_KIND_WAVE_MOB.equals(kind) || EVENT_KIND_ELITE.equals(kind)
                || EVENT_KIND_WAVE_GUARDIAN.equals(kind);
    }

    private boolean isEventSkeleton(Entity entity) {
        return entity instanceof Skeleton
                && isWaveCombatKind(readString(entity, keyKind));
    }

    private boolean isSkeletonMiniBoss(Entity entity) {
        return isEventSkeleton(entity) && !readString(entity, keyMiniBossSpell).isBlank();
    }

    private boolean isEventArrow(Entity entity) {
        return entity instanceof Arrow
                && EVENT_KIND_PROJECTILE.equals(readString(entity, keyKind))
                && activeEventArrowAges.containsKey(entity.getUniqueId());
    }

    private void tagArrowSpell(Arrow arrow, String spellId) {
        if (arrow != null && keyArrowSpell != null && spellId != null && !spellId.isBlank()) {
            arrow.getPersistentDataContainer().set(keyArrowSpell,
                    PersistentDataType.STRING, spellId);
        }
    }

    private void trackEventArrow(Arrow arrow) {
        if (arrow == null || !arrow.isValid()) {
            return;
        }
        while (activeEventArrowAges.size() >= MAX_ACTIVE_EVENT_ARROWS) {
            UUID oldest = activeEventArrowAges.keySet().iterator().next();
            cleanupEventArrow(oldest);
        }
        activeEventArrowAges.put(arrow.getUniqueId(), 0);
    }

    /** One generation-owned controller renders and expires all event arrows. */
    private void tickEventArrowProjectiles() {
        if (activeEventArrowAges.isEmpty()) {
            return;
        }
        int processed = 0;
        for (UUID arrowId : new ArrayList<>(activeEventArrowAges.keySet())) {
            if (++processed > MAX_ACTIVE_EVENT_ARROWS) {
                break;
            }
            Entity entity = Bukkit.getEntity(arrowId);
            if (!(entity instanceof Arrow arrow) || !arrow.isValid() || arrow.isDead()
                    || !isEventArrowPhaseAllowed(arrow)) {
                cleanupEventArrow(arrowId);
                continue;
            }
            int age = activeEventArrowAges.getOrDefault(arrowId, 0) + 1;
            if (age >= EVENT_ARROW_MAX_TICKS) {
                cleanupEventArrow(arrowId);
                continue;
            }
            activeEventArrowAges.put(arrowId, age);
            if (age % EVENT_ARROW_TRAIL_INTERVAL_TICKS == 0) {
                spawnEventArrowTrail(arrow, readString(arrow, keyArrowSpell), age);
            }
        }
    }

    private boolean isEventArrowPhaseAllowed(Arrow arrow) {
        if (arrow == null || !(arrow.getShooter() instanceof Entity shooter)) {
            return false;
        }
        String kind = readString(shooter, keyKind);
        if (EVENT_KIND_BOSS.equals(kind)) {
            return phase == EventPhase.BOSS_ACTIVE
                    || testCombatAiMode && isTestBoss(shooter);
        }
        return isEventSkeleton(shooter)
                && (isCombatPhase() || testCombatAiMode || hasLiveTestWaveEntities());
    }

    private void spawnEventArrowTrail(Arrow arrow, String spell, int age) {
        if (arrow == null || arrow.getWorld() == null) {
            return;
        }
        Location point = arrow.getLocation().clone().add(0.0D, 0.04D, 0.0D);
        for (Player viewer : eventAudience()) {
            if (!isEventParticleViewer(viewer, point)) {
                continue;
            }
            if (PACKET_QUALITY_MINIMAL_SAFE.equals(runtimeDiagnosticsSnapshot.packetQualityMode())
                    && age % 4 != 0) {
                continue;
            }
            recordParticleEmission(switch (spell) {
                case ARROW_SPELL_EXPLOSIVE -> 6;
                case ARROW_SPELL_POISON_NAUSEA -> 5;
                case "arrow_salvo" -> 4;
                case "rift_arrows" -> 4;
                default -> 2;
            });
            if (ARROW_SPELL_EXPLOSIVE.equals(spell)) {
                viewer.spawnParticle(Particle.FLAME, point, 3,
                        0.06D, 0.06D, 0.06D, 0.01D);
                viewer.spawnParticle(Particle.CRIT, point, 3,
                        0.04D, 0.04D, 0.04D, 0.02D);
                viewer.spawnParticle(Particle.DUST, point, 2,
                        0.04D, 0.04D, 0.04D, 0.0D,
                        new Particle.DustOptions(Color.fromRGB(255, 72, 28), 1.2F));
            } else if (ARROW_SPELL_POISON_NAUSEA.equals(spell)) {
                viewer.spawnParticle(Particle.WITCH, point, 3,
                        0.05D, 0.05D, 0.05D, 0.01D);
                viewer.spawnParticle(Particle.DUST, point, 2,
                        0.04D, 0.04D, 0.04D, 0.0D,
                        new Particle.DustOptions(Color.fromRGB(122, 255, 72), 1.05F));
            } else if (EndRiftAiPolicy.MiniBossSpell.ARROW_SALVO.id().equals(spell)) {
                viewer.spawnParticle(Particle.END_ROD, point, 2,
                        0.04D, 0.04D, 0.04D, 0.01D);
                viewer.spawnParticle(Particle.DUST, point, 2,
                        0.03D, 0.03D, 0.03D, 0.0D,
                        new Particle.DustOptions(Color.fromRGB(244, 60, 255), 1.0F));
            } else if (EndRiftAiPolicy.BossSpell.RIFT_ARROWS.id().equals(spell)) {
                viewer.spawnParticle(Particle.SOUL_FIRE_FLAME, point, 2,
                        0.04D, 0.04D, 0.04D, 0.005D);
                viewer.spawnParticle(Particle.CRIT, point, 2,
                        0.03D, 0.03D, 0.03D, 0.01D);
            } else {
                viewer.spawnParticle(Particle.CRIT, point, 2,
                        0.035D, 0.035D, 0.035D, 0.01D);
            }
        }
    }

    private void cleanupEventArrow(UUID arrowId) {
        if (arrowId == null) {
            return;
        }
        activeEventArrowAges.remove(arrowId);
        statusArrowEffectsApplied.remove(arrowId);
        detonatedEventArrows.remove(arrowId);
        Entity arrow = ownedEntities.remove(arrowId);
        if (arrow != null && arrow.isValid() && !arrow.isDead()) {
            arrow.remove();
        }
    }

    /** Detonate an elite skeleton arrow without ever mutating arena blocks. */
    private void detonateExplosiveArrow(Arrow arrow, Location impact) {
        if (arrow == null || impact == null || !isEventArrow(arrow)
                || !detonatedEventArrows.add(arrow.getUniqueId())) {
            return;
        }
        Location point = impact.clone();
        World world = point.getWorld();
        if (world != null) {
            LivingEntity shooter = arrow.getShooter() instanceof LivingEntity living ? living : null;
            int affected = 0;
            double radius = SkeletonArrowPolicy.EXPLOSIVE_DAMAGE_RADIUS_BLOCKS;
            for (Player player : activeLivingPlayers()) {
                if (!player.getWorld().equals(world)
                        || player.getLocation().distanceSquared(point) > radius * radius
                        || shooter != null && !realitySplitTargetAllowed(shooter, player)) {
                    continue;
                }
                if (shooter != null && shooter.isValid() && !shooter.isDead()) {
                    player.damage(SkeletonArrowPolicy.EXPLOSIVE_DAMAGE, shooter);
                } else {
                    player.damage(SkeletonArrowPolicy.EXPLOSIVE_DAMAGE);
                }
                affected++;
            }
            // This is intentionally a player-only impact transaction rather
            // than World#createExplosion: even a future Paper implementation
            // cannot yield blocks, fire, or cross-room entity damage here.
            spawnEventParticle(point, Particle.EXPLOSION, 1, 0.0D, 0.0D, 0.0D, 0.0D);
            world.playSound(point, Sound.ENTITY_GENERIC_EXPLODE, 0.65F, 1.35F);
            getLogger().info("SKELETON_EXPLOSIVE_ARROW_DETONATED arrow=" + arrow.getUniqueId()
                    + " damage=" + SkeletonArrowPolicy.EXPLOSIVE_DAMAGE
                    + " radius=" + radius + " affected_players=" + affected
                    + " breakBlocks=false fire=false");
        }
        cleanupEventArrow(arrow.getUniqueId());
    }

    private void clearActiveEventArrows() {
        for (UUID arrowId : new ArrayList<>(activeEventArrowAges.keySet())) {
            cleanupEventArrow(arrowId);
        }
        activeEventArrowAges.clear();
        statusArrowEffectsApplied.clear();
        detonatedEventArrows.clear();
    }

    /**
     * The official boss death is the hard boundary for every wave combat
     * entity.  Do this synchronously before the boss EntityDeathEvent is
     * emitted: a delayed victory cleanup used to leave wave combat mobs and
     * boss servants visible for one or more status ticks after victory.
     * Wave reward item entities are deliberately excluded so already-created
     * loot remains recoverable during the durable victory saga.
     */
    private int clearWaveCombatEntities(String reason) {
        clearCommanderAura();
        Set<UUID> combatIds = new LinkedHashSet<>();
        for (Entity entity : new ArrayList<>(ownedEntities.values())) {
            if (isWaveCombatKind(readString(entity, keyKind))) {
                combatIds.add(entity.getUniqueId());
            }
        }
        for (World world : Bukkit.getWorlds()) {
            for (Entity entity : new ArrayList<>(world.getEntities())) {
                if (isWaveCombatKind(readString(entity, keyKind))
                        && ownedByEvent(entity, eventId)) {
                    combatIds.add(entity.getUniqueId());
                }
            }
        }
        int removed = 0;
        for (UUID entityId : combatIds) {
            Entity entity = ownedEntities.get(entityId);
            if (entity == null) {
                entity = Bukkit.getEntity(entityId);
            }
            if (entity != null && isWaveCombatKind(readString(entity, keyKind))) {
                unbindEventEntityClient(entityId);
                if (entity.isValid() && !entity.isDead()) {
                    entity.remove();
                    removed++;
                }
            }
            ownedEntities.remove(entityId);
            waveGuardianEntities.remove(entityId);
            spellServants.remove(entityId);
            miniBossSpells.remove(entityId);
            nextMiniBossSpellMillis.remove(entityId);
            nextSkeletonArrowMillis.remove(entityId);
            nextWavePathRequestMillis.remove(entityId);
            lastWavePathLogMillis.remove(entityId);
            recentWaveTargets.remove(entityId);
            waveLastProgressLocations.remove(entityId);
            waveLastProgressAt.remove(entityId);
            nextWaveStuckRepositionMillis.remove(entityId);
            waveMobTactics.remove(entityId);
            combatTeleportPermits.remove(entityId);
            blockedTeleportLogAt.remove(entityId);
        }
        waveGuardianEntities.clear();
        spellServants.clear();
        miniBossSpells.clear();
        nextMiniBossSpellMillis.clear();
        nextSkeletonArrowMillis.clear();
        nextWavePathRequestMillis.clear();
        lastWavePathLogMillis.clear();
        recentWaveTargets.clear();
        waveLastProgressLocations.clear();
        waveLastProgressAt.clear();
        nextWaveStuckRepositionMillis.clear();
        nextWaveRoleVisualMillis = 0L;
        waveMobTactics.clear();
        combatTeleportPermits.clear();
        blockedTeleportLogAt.clear();
        waveCommanders.clear();
        nextCommanderAuraMillis = 0L;
        getLogger().info("END_EVENT_WAVE_COMBAT_CLEANUP event=" + eventId
                + " reason=" + reason + " removed=" + removed);
        return removed;
    }

    /**
     * AI is a runtime invariant for event combat entities.  A stale local
     * harness, another plugin, or a recovered entity may leave NoAI enabled;
     * restoring it here prevents an otherwise valid wave from becoming a
     * motionless and apparently un-hittable display.
     */
    private void ensureEventCombatAi(Entity entity) {
        if (entity == null) {
            return;
        }
        String kind = readString(entity, keyKind);
        if (!EVENT_KIND_BOSS.equals(kind) && !isWaveCombatKind(kind)) {
            return;
        }
        if (entity instanceof Mob mob) {
            if (testBossMovementFrozen
                    && ((testCombatAiMode && isTestBoss(entity)) || isOfficialBoss(entity))) {
                mob.setAI(false);
                mob.setAware(false);
                return;
            }
            boolean wasDisabled = !mob.hasAI();
            mob.setAI(true);
            mob.setAware(true);
            if (wasDisabled) {
                getLogger().info("EVENT_AI_RESTORED entity=" + entity.getUniqueId()
                        + " kind=" + kind + " phase=" + phase);
            }
        }
    }

    private boolean hasWaveCommander(int wave) {
        for (UUID commanderId : new HashSet<>(waveCommanders)) {
            Entity commander = ownedEntities.get(commanderId);
            if (commander == null || !isLiveOwnedEntity(commanderId)
                    || readInt(commander, keyWave, 0) != wave) {
                waveCommanders.remove(commanderId);
                continue;
            }
            return true;
        }
        return false;
    }

    private EndRiftObjective.Objective objectiveForWave(int wave) {
        try {
            return EndRiftObjective.objective(wave);
        } catch (IllegalArgumentException ignored) {
            return EndRiftObjective.Objective.RIFT_CARRIERS;
        }
    }

    /** Assign exactly one elite commander to each difficult objective. */
    private boolean assignWaveCommander(Entity entity, int wave, boolean elite) {
        EndRiftObjective.Objective objective = objectiveForWave(wave);
        if (entity == null || keyWaveCommander == null
                || !WaveCommanderPolicy.shouldAssign(objective, elite, hasWaveCommander(wave))) {
            return false;
        }
        entity.getPersistentDataContainer().set(keyWaveCommander,
                PersistentDataType.BYTE, (byte) 1);
        waveCommanders.add(entity.getUniqueId());
        getLogger().info("WAVE_COMMANDER_ASSIGNED event=" + eventId
                + " entity=" + entity.getUniqueId() + " wave=" + wave
                + " role=" + entity.getType() + " aura_radius="
                + WaveCommanderPolicy.AURA_RADIUS_BLOCKS
                + " max_live_mobs=" + PressureBudgetController.HARD_CAP);
        return true;
    }

    private boolean isWaveCommander(Entity entity) {
        return entity != null && keyWaveCommander != null
                && entity.getPersistentDataContainer().getOrDefault(
                keyWaveCommander, PersistentDataType.BYTE, (byte) 0) == (byte) 1;
    }

    /** Refresh the small Strength aura without scanning natural mobs. */
    private void tickWaveCommanderAura() {
        if (waveCommanders.isEmpty() && commanderAuraEntities.isEmpty()) {
            return;
        }
        long now = System.currentTimeMillis();
        if (now < nextCommanderAuraMillis) {
            return;
        }
        nextCommanderAuraMillis = now + COMMANDER_AURA_REFRESH_MILLIS;
        List<LivingEntity> commanders = waveCommanders.stream()
                .map(ownedEntities::get)
                .filter(entity -> entity instanceof LivingEntity
                        && isLiveOwnedEntity(entity.getUniqueId())
                        && isWaveCommander(entity))
                .map(entity -> (LivingEntity) entity)
                .toList();
        if (commanders.isEmpty()) {
            clearCommanderAura();
            waveCommanders.clear();
            return;
        }
        Set<UUID> desired = new LinkedHashSet<>();
        for (Entity entity : new ArrayList<>(ownedEntities.values())) {
            if (!(entity instanceof LivingEntity living) || !isLiveOwnedEntity(entity.getUniqueId())
                    || !isWaveCombatKind(readString(entity, keyKind))
                    || isWaveCommander(entity)) {
                continue;
            }
            boolean inAura = commanders.stream().anyMatch(commander ->
                    commander.getWorld().equals(living.getWorld())
                            && commander.getLocation().distanceSquared(living.getLocation())
                            <= WaveCommanderPolicy.AURA_RADIUS_BLOCKS
                            * WaveCommanderPolicy.AURA_RADIUS_BLOCKS);
            if (inAura) {
                desired.add(entity.getUniqueId());
                living.addPotionEffect(new PotionEffect(PotionEffectType.STRENGTH,
                        WaveCommanderPolicy.AURA_DURATION_TICKS,
                        WaveCommanderPolicy.AURA_AMPLIFIER, false, true, true), true);
                if (keyCommanderAura != null) {
                    living.getPersistentDataContainer().set(keyCommanderAura,
                            PersistentDataType.BYTE, (byte) 1);
                }
            }
        }
        for (UUID auraId : new HashSet<>(commanderAuraEntities)) {
            if (desired.contains(auraId)) {
                continue;
            }
            Entity entity = ownedEntities.get(auraId);
            if (entity instanceof LivingEntity living) {
                living.removePotionEffect(PotionEffectType.STRENGTH);
                if (keyCommanderAura != null) {
                    living.getPersistentDataContainer().remove(keyCommanderAura);
                }
            }
        }
        commanderAuraEntities.clear();
        commanderAuraEntities.addAll(desired);
        if (!desired.isEmpty()) {
            getLogger().info("WAVE_COMMANDER_AURA event=" + eventId
                    + " commanders=" + commanders.size() + " affected=" + desired.size()
                    + " radius=" + WaveCommanderPolicy.AURA_RADIUS_BLOCKS
                    + " duration_ticks=" + WaveCommanderPolicy.AURA_DURATION_TICKS);
        }
    }

    private void clearCommanderAura() {
        for (UUID auraId : new HashSet<>(commanderAuraEntities)) {
            Entity entity = ownedEntities.get(auraId);
            if (entity instanceof LivingEntity living) {
                living.removePotionEffect(PotionEffectType.STRENGTH);
                if (keyCommanderAura != null) {
                    living.getPersistentDataContainer().remove(keyCommanderAura);
                }
            }
        }
        commanderAuraEntities.clear();
        nextCommanderAuraMillis = 0L;
    }

    /** Each elite owns exactly one spell; there is no shared repeating task per mob. */
    private void tickMiniBosses() {
        if (!isMiniBossCombatPhase()) {
            return;
        }
        long now = System.currentTimeMillis();
        for (Map.Entry<UUID, EndRiftAiPolicy.MiniBossSpell> entry : new HashMap<>(miniBossSpells).entrySet()) {
            Entity entity = ownedEntities.get(entry.getKey());
            if (!(entity instanceof LivingEntity miniBoss) || !isLiveOwnedEntity(entity.getUniqueId())
                    || !isMiniBossCombatEntity(miniBoss)) {
                miniBossSpells.remove(entry.getKey());
                nextMiniBossSpellMillis.remove(entry.getKey());
                continue;
            }
            if (nextMiniBossSpellMillis.getOrDefault(entity.getUniqueId(), 0L) > now) {
                continue;
            }
            List<Player> candidates = activeLivingPlayers().stream()
                    .filter(player -> realitySplitTargetAllowed(entity, player))
                    .toList();
            if (candidates.isEmpty()) {
                nextMiniBossSpellMillis.put(entity.getUniqueId(), now + 1000L);
                continue;
            }
            Player current = miniBoss instanceof Mob mob && mob.getTarget() instanceof Player player
                    && realitySplitTargetAllowed(entity, player)
                    ? player : null;
            List<UUID> candidateIds = candidates.stream().map(Player::getUniqueId)
                    .sorted(Comparator.comparing(UUID::toString)).toList();
            EndRiftAiPolicy.TargetChoice choice = EndRiftAiPolicy.chooseFairTarget(
                    candidateIds, current == null ? null : current.getUniqueId(), List.of(), waveTargetCursor++);
            Player target = choice.target() == null ? null : Bukkit.getPlayer(choice.target());
            if (target == null || !realitySplitTargetAllowed(entity, target)) {
                nextMiniBossSpellMillis.put(entity.getUniqueId(), now + 1000L);
                continue;
            }
            if (miniBoss instanceof Mob mob) {
                mob.setTarget(target);
            }
            nextMiniBossSpellMillis.put(entity.getUniqueId(), now
                    + randomSeconds(config.miniBossTuning().spellMinSeconds(), config.miniBossTuning().spellMaxSeconds()) * 1000L);
            telegraphMiniBossSpell(miniBoss, target, entry.getValue());
        }
    }

    private void telegraphMiniBossSpell(LivingEntity miniBoss, Player target, EndRiftAiPolicy.MiniBossSpell spell) {
        if (taskRegistry == null || miniBoss == null || target == null
                || !realitySplitTargetAllowed(miniBoss, target)) {
            return;
        }
        long callbackGeneration = generation;
        UUID miniBossId = miniBoss.getUniqueId();
        Location mark = target.getLocation().clone();
        getLogger().info("MINIBOSS_SPELL_TELEGRAPH entity=" + miniBossId + " spell=" + spell.id()
                + " target=" + target.getUniqueId() + " generation=" + generation);
        final int[] ticks = {0};
        BukkitTask[] holder = new BukkitTask[1];
        holder[0] = Bukkit.getScheduler().runTaskTimer(this, () -> {
            if (taskRegistry == null || !taskRegistry.owns(callbackGeneration)
                    || !isMiniBossCombatPhase() || !miniBoss.isValid() || miniBoss.isDead()
                    || miniBossSpells.get(miniBossId) != spell) {
                holder[0].cancel();
                return;
            }
            ticks[0] += 5;
            Location effect = spell == EndRiftAiPolicy.MiniBossSpell.ECHO_PULSE
                    ? miniBoss.getLocation().add(0.0D, 1.0D, 0.0D) : mark;
            Particle particle = switch (spell) {
                case VOID_SNARE -> Particle.REVERSE_PORTAL;
                case ARROW_SALVO -> Particle.CRIT;
                case RIFT_EUPHORIA -> Particle.WITCH;
                default -> Particle.END_ROD;
            };
            spawnEventParticle(effect, particle, 8, 0.65D, 0.15D, 0.65D, 0.01D);
            renderSpellTelegraphVisual(miniBoss, mark, spell.id(), ticks[0],
                    config.miniBossTuning().spellTelegraphTicks());
            if (ticks[0] >= config.miniBossTuning().spellTelegraphTicks()) {
                holder[0].cancel();
                if (taskRegistry.owns(callbackGeneration) && isMiniBossCombatPhase()
                        && miniBoss.isValid() && !miniBoss.isDead()) {
                    executeMiniBossSpell(miniBoss, target, mark, spell, callbackGeneration);
                }
            }
        }, 0L, 5L);
        registerEncounterTask(holder[0]);
    }

    private void executeMiniBossSpell(LivingEntity miniBoss, Player target, Location mark,
                                      EndRiftAiPolicy.MiniBossSpell spell, long callbackGeneration) {
        if (taskRegistry == null || !taskRegistry.owns(callbackGeneration)
                || !isMiniBossCombatPhase() || !realitySplitTargetAllowed(miniBoss, target)) {
            return;
        }
        launchSpellFlight(miniBoss, mark,
                "MINIBOSS_SPELL_FLIGHT", spell.id(), target.getUniqueId(), false,
                callbackGeneration, () -> {
                    if (taskRegistry == null || !taskRegistry.owns(callbackGeneration)
                            || !isMiniBossCombatPhase() || !realitySplitTargetAllowed(miniBoss, target)
                            || !miniBoss.isValid() || miniBoss.isDead()
                            || miniBossSpells.get(miniBoss.getUniqueId()) != spell) {
                        return;
                    }
                    getLogger().info("MINIBOSS_SPELL_CAST entity=" + miniBoss.getUniqueId()
                            + " spell=" + spell.id() + " target=" + target.getUniqueId()
                            + " generation=" + callbackGeneration);
                    renderSpellImpactVisual(miniBoss,
                            spell == EndRiftAiPolicy.MiniBossSpell.ECHO_PULSE
                                    ? miniBoss.getLocation() : mark,
                            spell.id());
                    switch (spell) {
                        case RIFT_STEP -> miniBossRiftStep(miniBoss, target);
                        case VOID_SNARE -> miniBossVoidSnare(miniBoss, target, mark);
                        case ECHO_PULSE -> miniBossEchoPulse(miniBoss);
                        case ARROW_SALVO -> miniBossArrowSalvo(miniBoss, target);
                        case RIFT_EUPHORIA -> miniBossRiftEuphoria(miniBoss, target);
                    }
                });
    }

    /** Render one short impact burst; unlike the telegraph this is one bounded
     * batch per cast, so a busy arena cannot accumulate visual tasks. */
    private void renderSpellImpactVisual(LivingEntity caster, Location mark, String spellId) {
        SpellVisualPolicy.VisualProfile profile = SpellVisualPolicy.profile(spellId);
        if (caster == null || mark == null || profile == null || caster.getWorld() == null
                || mark.getWorld() == null || !caster.getWorld().equals(mark.getWorld())) {
            return;
        }
        Location center = mark.clone().add(0.0D, 0.12D, 0.0D);
        Location origin = caster.getLocation().clone().add(0.0D, 1.0D, 0.0D);
        Vector forward = center.toVector().subtract(origin.toVector());
        if (forward.lengthSquared() < 0.0001D) {
            forward = new Vector(0.0D, 0.0D, 1.0D);
        }
        forward.normalize();
        Vector horizontal = forward.clone();
        horizontal.setY(0.0D);
        if (horizontal.lengthSquared() < 0.0001D) {
            horizontal = new Vector(1.0D, 0.0D, 0.0D);
        }
        horizontal.normalize();
        Vector side = new Vector(-horizontal.getZ(), 0.0D, horizontal.getX()).normalize();
        Vector up = new Vector(0.0D, 1.0D, 0.0D);
        Particle.DustOptions dust = new Particle.DustOptions(
                Color.fromRGB(190, 76, 255), 1.25F);
        for (Player viewer : eventAudience()) {
            if (!isEventParticleViewer(viewer, center)) {
                continue;
            }
            spawnSpellImpactHalo(viewer, center, side, up, spellId);
            switch (spellId) {
                case "void_blast" -> {
                    spawnPatternRing(viewer, center, side, horizontal, 0.85D, 24,
                            0.0D, Particle.DRAGON_BREATH);
                    spawnPatternRing(viewer, center, side, horizontal, 1.65D, 32,
                            0.25D, Particle.FLAME);
                }
                case "rift_projectile" -> {
                    spawnPatternRing(viewer, center, side, up, 0.48D, 18,
                            0.0D, Particle.REVERSE_PORTAL);
                    viewer.spawnParticle(Particle.END_ROD, center, 12,
                            0.18D, 0.18D, 0.18D, 0.02D);
                }
                case "rift_arrows", "arrow_salvo" -> {
                    Particle trail = "arrow_salvo".equals(spellId)
                            ? Particle.CRIT : Particle.SOUL_FIRE_FLAME;
                    for (int lane = -1; lane <= 1; lane++) {
                        Vector offset = side.clone().multiply(lane * 0.28D);
                        spawnPatternSegment(viewer, origin.clone().add(offset),
                                center.clone().add(offset), trail, dust);
                    }
                }
                case "void_mark" -> {
                    Location[] corners = new Location[4];
                    double radius = 1.45D;
                    for (int index = 0; index < corners.length; index++) {
                        double angle = Math.PI / 4.0D + index * Math.PI / 2.0D;
                        corners[index] = center.clone()
                                .add(side.clone().multiply(Math.cos(angle) * radius))
                                .add(horizontal.clone().multiply(Math.sin(angle) * radius));
                    }
                    for (int index = 0; index < corners.length; index++) {
                        spawnPatternSegment(viewer, corners[index], corners[(index + 1) % corners.length],
                                Particle.REVERSE_PORTAL, dust);
                    }
                }
                case "summon", "summon_servants" -> {
                    spawnPatternRing(viewer, origin, side, horizontal, 1.05D, 24,
                            0.0D, Particle.SOUL_FIRE_FLAME);
                    viewer.spawnParticle(Particle.WITCH, origin, 18,
                            0.25D, 0.75D, 0.25D, 0.02D);
                }
                case "arena_inferno" -> {
                    spawnPatternRing(viewer, center, side, horizontal, 2.5D, 36,
                            0.0D, Particle.SOUL_FIRE_FLAME);
                    spawnPatternRing(viewer, center, side, horizontal, 3.4D, 48,
                            0.18D, Particle.FLAME);
                }
                case "rift_step" -> {
                    spawnPatternRing(viewer, origin, side, up, 0.75D, 20,
                            0.0D, Particle.PORTAL);
                    spawnPatternRing(viewer, center, side, up, 0.75D, 20,
                            0.35D, Particle.END_ROD);
                }
                case "void_snare" -> {
                    spawnPatternRing(viewer, center, side, up, 1.15D, 20,
                            0.0D, Particle.REVERSE_PORTAL);
                    spawnPatternRing(viewer, center, side, up, 0.55D, 12,
                            0.4D, Particle.SMOKE);
                }
                case "echo_pulse" -> {
                    spawnPatternRing(viewer, center, side, horizontal, 2.2D, 36,
                            0.0D, Particle.SCULK_SOUL);
                    viewer.spawnParticle(Particle.SONIC_BOOM, center, 1,
                            0.0D, 0.0D, 0.0D, 0.0D);
                }
                case "rift_euphoria" -> {
                    spawnPatternRing(viewer, center, side, up, 0.75D, 24,
                            0.0D, Particle.WITCH);
                    spawnPatternRing(viewer, center.clone().add(0.0D, 0.6D, 0.0D),
                            side, up, 1.25D, 28, 0.35D, Particle.REVERSE_PORTAL);
                    viewer.spawnParticle(Particle.DRAGON_BREATH, center, 14,
                            0.25D, 0.65D, 0.25D, 0.02D);
                }
                default -> viewer.spawnParticle(Particle.END_ROD, center, 8,
                        0.18D, 0.18D, 0.18D, 0.02D);
            }
        }
        getLogger().info("SPELL_IMPACT_VISUAL spell=" + spellId
                + " profile=" + profile.displayName());
    }

    /**
     * Render the readable wind-up for both boss and elite spells.  Every
     * spell has a different silhouette: rings, glyphs, lanes, chains or a
     * pulse.  The effect is audience-scoped and particle-only, so it never
     * replaces a vanilla texture or creates a hidden gameplay entity.
     */
    private void renderSpellTelegraphVisual(LivingEntity caster, Location mark,
                                            String spellId, int elapsedTicks,
                                            int totalTelegraphTicks) {
        SpellVisualPolicy.VisualProfile profile = SpellVisualPolicy.profile(spellId);
        if (caster == null || mark == null || spellId == null || profile == null
                || caster.getWorld() == null || mark.getWorld() == null
                || !caster.getWorld().equals(mark.getWorld())) {
            return;
        }
        Location origin = caster.getLocation().clone().add(0.0D, 1.0D, 0.0D);
        Location destination = mark.clone().add(0.0D, 0.12D, 0.0D);
        Vector direction = destination.toVector().subtract(origin.toVector());
        if (direction.lengthSquared() < 0.0001D) {
            direction = new Vector(0.0D, 0.0D, 1.0D);
        }
        double travelDistance = Math.max(1.0D, direction.length());
        direction.normalize();
        Vector horizontal = direction.clone();
        horizontal.setY(0.0D);
        if (horizontal.lengthSquared() < 0.0001D) {
            horizontal = new Vector(1.0D, 0.0D, 0.0D);
        }
        horizontal.normalize();
        Vector side = new Vector(-horizontal.getZ(), 0.0D, horizontal.getX()).normalize();
        Vector up = new Vector(0.0D, 1.0D, 0.0D);
        double progress = Math.max(0.0D, Math.min(1.0D,
                elapsedTicks / (double) Math.max(1, totalTelegraphTicks)));
        double phaseAngle = elapsedTicks * 0.24D;
        for (Player viewer : eventAudience()) {
            if (!isEventParticleViewer(viewer, destination)
                    && !isEventParticleViewer(viewer, origin)) {
                continue;
            }
            spawnSpellTelegraphGlyph(viewer, destination, side, up, spellId, phaseAngle, progress);
            switch (spellId) {
                case "void_blast" -> {
                    double radius = 0.65D + progress * 1.15D;
                    spawnPatternRing(viewer, destination, side, horizontal, radius, 18,
                            phaseAngle, Particle.DRAGON_BREATH);
                    spawnPatternSegment(viewer, origin, destination, Particle.END_ROD,
                            new Particle.DustOptions(Color.fromRGB(244, 39, 125), 1.15F));
                }
                case "rift_projectile" -> {
                    Location moving = origin.clone().add(direction.clone().multiply(progress));
                    spawnPatternRing(viewer, moving, side, up, 0.26D + progress * 0.10D,
                            14, phaseAngle, Particle.REVERSE_PORTAL);
                    spawnPatternSegment(viewer, origin, moving, Particle.DUST,
                            new Particle.DustOptions(Color.fromRGB(69, 218, 255), 1.20F));
                }
                case "rift_arrows", "arrow_salvo" -> {
                    Particle trail = "arrow_salvo".equals(spellId) ? Particle.CRIT : Particle.SOUL_FIRE_FLAME;
                    Color color = "arrow_salvo".equals(spellId)
                            ? Color.fromRGB(244, 60, 255) : Color.fromRGB(255, 72, 72);
                    Particle.DustOptions dust = new Particle.DustOptions(color, 1.10F);
                    for (int lane = -1; lane <= 1; lane++) {
                        double offset = lane * (0.22D + progress * 0.10D);
                        Location laneStart = origin.clone().add(side.clone().multiply(offset));
                        Location laneEnd = destination.clone().add(side.clone().multiply(offset * 1.4D));
                        spawnPatternSegment(viewer, laneStart, laneEnd, trail, dust);
                    }
                }
                case "void_mark" -> {
                    double radius = 0.80D + progress * 1.35D;
                    Location[] corners = new Location[4];
                    for (int index = 0; index < corners.length; index++) {
                        double angle = Math.PI / 4.0D + index * Math.PI / 2.0D + phaseAngle * 0.35D;
                        corners[index] = destination.clone()
                                .add(side.clone().multiply(Math.cos(angle) * radius))
                                .add(horizontal.clone().multiply(Math.sin(angle) * radius));
                        viewer.spawnParticle(Particle.END_ROD, corners[index], 2,
                                0.015D, 0.015D, 0.015D, 0.0D);
                    }
                    Particle.DustOptions dust = new Particle.DustOptions(
                            Color.fromRGB(190, 76, 255), 1.30F);
                    for (int index = 0; index < corners.length; index++) {
                        spawnPatternSegment(viewer, corners[index], corners[(index + 1) % corners.length],
                                Particle.REVERSE_PORTAL, dust);
                    }
                }
                case "summon_servants" -> {
                    Location center = origin.clone().add(0.0D, 0.25D, 0.0D);
                    spawnPatternRing(viewer, center, side, horizontal, 0.70D + progress * 0.50D,
                            16, phaseAngle, Particle.SOUL_FIRE_FLAME);
                    spawnPatternSegment(viewer, center.clone().subtract(up.clone().multiply(0.45D)),
                            center.clone().add(up.clone().multiply(0.85D)),
                            Particle.WITCH, new Particle.DustOptions(Color.fromRGB(125, 47, 255), 1.0F));
                }
                case "arena_inferno" -> {
                    double radius = 1.4D + progress * 2.5D;
                    spawnPatternRing(viewer, destination, side, horizontal, radius, 24,
                            phaseAngle, Particle.SOUL_FIRE_FLAME);
                    spawnPatternRing(viewer, destination, side, horizontal, radius * 0.72D,
                            18, -phaseAngle, Particle.FLAME);
                }
                case "rift_step" -> {
                    for (int lane = -1; lane <= 1; lane += 2) {
                        Location laneStart = origin.clone().add(side.clone().multiply(lane * 0.18D));
                        Location laneEnd = destination.clone().add(side.clone().multiply(lane * 0.30D));
                        spawnPatternSegment(viewer, laneStart, laneEnd, Particle.PORTAL,
                                new Particle.DustOptions(Color.fromRGB(69, 218, 255), 1.0F));
                    }
                }
                case "void_snare" -> {
                    double outer = Math.max(0.22D, 1.20D - progress * 0.65D);
                    spawnPatternRing(viewer, destination, side, up, outer, 16,
                            phaseAngle, Particle.REVERSE_PORTAL);
                    spawnPatternRing(viewer, destination, side, up, outer * 0.58D, 10,
                            -phaseAngle, Particle.SMOKE);
                }
                case "echo_pulse" -> {
                    Location center = origin.clone();
                    double radius = 0.25D + progress * 2.20D;
                    spawnPatternRing(viewer, center, side, horizontal, radius, 24,
                            phaseAngle, Particle.SCULK_SOUL);
                    viewer.spawnParticle(Particle.SONIC_BOOM, center, 1,
                            0.0D, 0.0D, 0.0D, 0.0D);
                }
                case "rift_euphoria" -> {
                    double radius = 0.45D + progress * 0.85D;
                    spawnPatternRing(viewer, destination, side, up, radius, 20,
                            phaseAngle, Particle.WITCH);
                    spawnPatternRing(viewer, destination.clone().add(0.0D, 0.45D, 0.0D),
                            side, up, radius * 1.35D, 24, -phaseAngle, Particle.REVERSE_PORTAL);
                    spawnPatternSegment(viewer, origin, destination, Particle.DRAGON_BREATH,
                            new Particle.DustOptions(Color.fromRGB(122, 255, 72), 1.0F));
                }
                default -> viewer.spawnParticle(Particle.END_ROD, destination, 4,
                        0.08D, 0.08D, 0.08D, 0.01D);
            }
        }
    }

    /**
     * Sends every event spell through a short, visible particle flight before
     * applying its gameplay effect.  The callback is owned by the current
     * event generation so a reset, cancellation, or phase change cannot leave
     * a delayed damage task behind.
     */
    private void launchSpellFlight(LivingEntity caster, Location destination,
                                   String logMarker, String spellId, UUID targetId, boolean forced,
                                   long callbackGeneration, Runnable impact) {
        if (taskRegistry == null || caster == null || destination == null
                || impact == null || !isSpellFlightAllowed(caster, forced)
                || caster.getWorld() == null || destination.getWorld() == null
                || !caster.getWorld().equals(destination.getWorld())) {
            return;
        }
        Location start = caster.getEyeLocation().clone();
        Location end = destination.clone().add(0.0D, 0.75D, 0.0D);
        Vector delta = end.toVector().subtract(start.toVector());
        getLogger().info(logMarker + " caster=" + caster.getUniqueId()
                + " spell=" + spellId + " target=" + targetId
                + " effect=" + SPELL_FLIGHT_EFFECT + " visual=particle-only pattern=" + spellId
                + " ticks=" + SPELL_FLIGHT_TICKS
                + " generation=" + callbackGeneration);
        final int[] ticks = {0};
        final BukkitTask[] holder = new BukkitTask[1];
        holder[0] = Bukkit.getScheduler().runTaskTimer(this, () -> {
            boolean allowed = taskRegistry != null
                    && taskRegistry.owns(callbackGeneration)
                    && isSpellFlightAllowed(caster, forced);
            if (!allowed) {
                holder[0].cancel();
                return;
            }
            double progress = Math.min(1.0D, ++ticks[0] / (double) SPELL_FLIGHT_TICKS);
            Location point = start.clone().add(delta.clone().multiply(progress));
            if (ticks[0] % SPELL_FLIGHT_RENDER_INTERVAL_TICKS == 0 || progress >= 1.0D) {
                spawnSpellFlightPattern(caster.getWorld(), point, delta, spellId, ticks[0]);
            }
            if (progress >= 1.0D) {
                holder[0].cancel();
                impact.run();
            }
        }, 0L, 1L);
        registerEncounterTask(holder[0]);
    }

    /**
     * Renders one named, particle-only flight pattern for each event spell.
     * There is intentionally no ItemDisplay or custom model in this path:
     * the geometry is sent by the server as vanilla particles and therefore
     * remains visible without changing any vanilla texture.
     */
    private void spawnSpellFlightPattern(World world, Location point, Vector direction,
                                          String spellId, int tick) {
        if (world == null || point == null || direction == null || spellId == null) {
            return;
        }
        double maxDistanceSquared = 64.0D * 64.0D;
        for (Player player : eventAudience()) {
            if (!player.isOnline() || !player.getWorld().equals(world)
                    || player.getLocation().distanceSquared(point) > maxDistanceSquared) {
                continue;
            }
            spawnSpellFlightPattern(player, point, direction, spellId, tick);
        }
    }

    private void spawnSpellFlightPattern(Player player, Location point, Vector direction,
                                          String spellId, int tick) {
        if (player == null || point == null || direction == null || spellId == null
                || !player.isOnline() || player.getWorld() == null) {
            return;
        }
        World world = player.getWorld();
        if (!world.equals(point.getWorld()) || player.getLocation().distanceSquared(point) > 64.0D * 64.0D) {
            return;
        }
        if (PACKET_QUALITY_MINIMAL_SAFE.equals(runtimeDiagnosticsSnapshot.packetQualityMode())
                && tick % 4 != 0) {
            return;
        }
        recordParticleEmission(estimatedSpellFlightParticles(spellId));
        spawnSpellSignature(player, point, direction, spellId, tick);
        Vector forward = direction.clone();
        if (forward.lengthSquared() < 0.0001D) {
            forward = new Vector(0.0D, 0.0D, 1.0D);
        }
        forward.normalize();
        Vector reference = Math.abs(forward.getY()) > 0.85D
                ? new Vector(1.0D, 0.0D, 0.0D)
                : new Vector(0.0D, 1.0D, 0.0D);
        Vector side = forward.clone().crossProduct(reference);
        if (side.lengthSquared() < 0.0001D) {
            side = new Vector(1.0D, 0.0D, 0.0D);
        }
        side.normalize();
        Vector vertical = side.clone().crossProduct(forward).normalize();
        double phase = tick * 0.78D;

        switch (spellId) {
            case "void_blast" -> {
                player.spawnParticle(Particle.DRAGON_BREATH, point, 12,
                        0.14D, 0.14D, 0.14D, 0.015D);
                player.spawnParticle(Particle.DUST, point, 7,
                        0.04D, 0.04D, 0.04D, 0.0D,
                        new Particle.DustOptions(Color.fromRGB(244, 39, 125), 1.35F));
                spawnPatternRing(player, point, side, vertical, 0.18D + (tick % 3) * 0.05D,
                        10, phase, Particle.FLAME);
            }
            case "rift_projectile" -> spawnRiftProjectileTrail(player, point, direction, tick);
            case "arrow_salvo" -> {
                Particle.DustOptions salvoDust = new Particle.DustOptions(
                        Color.fromRGB(244, 60, 255), 1.15F);
                player.spawnParticle(Particle.END_ROD, point, 5,
                        0.05D, 0.05D, 0.05D, 0.01D);
                player.spawnParticle(Particle.DUST, point, 5,
                        0.04D, 0.04D, 0.04D, 0.0D, salvoDust);
                spawnPatternRing(player, point, side, vertical,
                        0.13D + (tick % 3) * 0.04D, 8, phase, Particle.CRIT);
            }
            case "rift_arrows" -> {
                Particle.DustOptions riftArrowDust = new Particle.DustOptions(
                        Color.fromRGB(255, 72, 72), 1.25F);
                player.spawnParticle(Particle.SOUL_FIRE_FLAME, point, 7,
                        0.06D, 0.06D, 0.06D, 0.01D);
                player.spawnParticle(Particle.DUST, point, 5,
                        0.04D, 0.04D, 0.04D, 0.0D, riftArrowDust);
                Vector arrowSide = side.clone().multiply(0.22D);
                spawnPatternSegment(player, point.clone().subtract(arrowSide),
                        point.clone().add(arrowSide), Particle.CRIT, riftArrowDust);
            }
            case "void_mark" -> {
                Particle.DustOptions markDust = new Particle.DustOptions(Color.fromRGB(190, 76, 255), 1.25F);
                double halfDiagonal = 0.31D + (tick % 2) * 0.04D;
                Location[] corners = new Location[4];
                for (int i = 0; i < corners.length; i++) {
                    double angle = phase * 0.35D + Math.PI / 4.0D + i * Math.PI / 2.0D;
                    corners[i] = point.clone()
                            .add(side.clone().multiply(Math.cos(angle) * halfDiagonal))
                            .add(vertical.clone().multiply(Math.sin(angle) * halfDiagonal));
                    player.spawnParticle(Particle.END_ROD, corners[i], 2,
                            0.015D, 0.015D, 0.015D, 0.0D);
                    player.spawnParticle(Particle.DUST, corners[i], 2,
                            0.015D, 0.015D, 0.015D, 0.0D, markDust);
                }
                for (int i = 0; i < corners.length; i++) {
                    spawnPatternSegment(player, corners[i], corners[(i + 1) % corners.length],
                            Particle.END_ROD, markDust);
                }
            }
            case "summon", "summon_servants" -> {
                Vector up = new Vector(0.0D, 1.0D, 0.0D);
                for (int i = 0; i < 6; i++) {
                    double angle = phase + i * Math.PI / 3.0D;
                    Location spiral = point.clone()
                            .add(side.clone().multiply(Math.cos(angle) * 0.24D))
                            .add(vertical.clone().multiply(Math.sin(angle) * 0.24D))
                            .add(up.clone().multiply((i - 2.5D) * 0.07D));
                    player.spawnParticle(Particle.SOUL_FIRE_FLAME, spiral, 2,
                            0.015D, 0.015D, 0.015D, 0.005D);
                    player.spawnParticle(Particle.WITCH, spiral, 1,
                            0.01D, 0.01D, 0.01D, 0.0D);
                }
            }
            case "rift_step" -> {
                for (int i = 0; i < 6; i++) {
                    double angle = phase + i * Math.PI / 3.0D;
                    Vector along = forward.clone().multiply((i - 2.5D) * 0.12D);
                    Location first = point.clone().add(along.clone())
                            .add(side.clone().multiply(Math.cos(angle) * 0.23D))
                            .add(vertical.clone().multiply(Math.sin(angle) * 0.23D));
                    Location second = point.clone().add(along)
                            .subtract(side.clone().multiply(Math.cos(angle) * 0.23D))
                            .add(vertical.clone().multiply(Math.sin(angle) * 0.23D));
                    player.spawnParticle(Particle.PORTAL, first, 2,
                            0.015D, 0.015D, 0.015D, 0.01D);
                    player.spawnParticle(Particle.END_ROD, second, 1,
                            0.01D, 0.01D, 0.01D, 0.0D);
                }
            }
            case "void_snare" -> {
                double radius = Math.max(0.16D, 0.44D - tick * 0.035D);
                spawnPatternRing(player, point, side, vertical, radius, 12, phase,
                        Particle.REVERSE_PORTAL);
                for (int i = 0; i < 6; i++) {
                    double angle = phase + i * Math.PI / 3.0D;
                    Location chain = point.clone()
                            .add(side.clone().multiply(Math.cos(angle) * radius))
                            .add(vertical.clone().multiply(Math.sin(angle) * radius));
                    player.spawnParticle(Particle.SMOKE, chain, 1,
                            0.01D, 0.01D, 0.01D, 0.0D);
                }
            }
            case "echo_pulse" -> {
                double radius = 0.10D + tick * 0.075D;
                spawnPatternRing(player, point, side, vertical, radius, 14, phase,
                        Particle.SCULK_SOUL);
                player.spawnParticle(Particle.SONIC_BOOM, point, 1,
                        0.0D, 0.0D, 0.0D, 0.0D);
            }
            default -> player.spawnParticle(Particle.END_ROD, point, 4,
                    0.06D, 0.06D, 0.06D, 0.0D);
        }
    }

    /**
     * Adds a compact signature to the moving particle projectile.  The
     * signature is deliberately different for every spell, but all shapes are
     * viewer-scoped and bounded so five players do not turn a short cast into a
     * particle storm.
     */
    private void spawnSpellSignature(Player player, Location point, Vector direction,
                                     String spellId, int tick) {
        if (player == null || point == null || direction == null || spellId == null
                || !player.isOnline() || point.getWorld() == null
                || !player.getWorld().equals(point.getWorld())
                || player.getLocation().distanceSquared(point) > 64.0D * 64.0D) {
            return;
        }
        Vector forward = direction.clone();
        if (forward.lengthSquared() < 0.0001D) {
            forward = new Vector(0.0D, 0.0D, 1.0D);
        }
        forward.normalize();
        Vector reference = Math.abs(forward.getY()) > 0.85D
                ? new Vector(1.0D, 0.0D, 0.0D) : new Vector(0.0D, 1.0D, 0.0D);
        Vector side = forward.clone().crossProduct(reference);
        if (side.lengthSquared() < 0.0001D) {
            side = new Vector(1.0D, 0.0D, 0.0D);
        }
        side.normalize();
        Vector vertical = side.clone().crossProduct(forward).normalize();
        Color color = spellVisualColor(spellId);
        Particle.DustOptions dust = new Particle.DustOptions(color, 1.15F);
        double phase = tick * 0.78D;
        switch (spellId) {
            case "void_blast" -> {
                spawnPatternRing(player, point, side, vertical, 0.22D, 14, phase, Particle.FLAME);
                player.spawnParticle(Particle.DRAGON_BREATH, point, 6,
                        0.03D, 0.03D, 0.03D, 0.01D);
            }
            case "rift_projectile" -> {
                spawnPatternRing(player, point, side, vertical, 0.25D, 14, phase, Particle.REVERSE_PORTAL);
                spawnPatternSegment(player, point.clone().subtract(forward.clone().multiply(0.35D)),
                        point.clone().add(forward.clone().multiply(0.35D)), Particle.END_ROD, dust);
            }
            case "rift_arrows", "arrow_salvo" -> {
                Particle arrowParticle = "arrow_salvo".equals(spellId) ? Particle.CRIT : Particle.SOUL_FIRE_FLAME;
                for (int lane = -1; lane <= 1; lane++) {
                    Location start = point.clone().add(side.clone().multiply(lane * 0.25D))
                            .subtract(forward.clone().multiply(0.22D));
                    Location end = point.clone().add(side.clone().multiply(lane * 0.25D))
                            .add(forward.clone().multiply(0.30D));
                    spawnPatternSegment(player, start, end, arrowParticle, dust);
                }
            }
            case "void_mark" -> {
                Location[] corners = new Location[4];
                for (int i = 0; i < corners.length; i++) {
                    double angle = Math.PI / 4.0D + i * Math.PI / 2.0D + phase * 0.25D;
                    corners[i] = point.clone()
                            .add(side.clone().multiply(Math.cos(angle) * 0.30D))
                            .add(vertical.clone().multiply(Math.sin(angle) * 0.30D));
                }
                for (int i = 0; i < corners.length; i++) {
                    player.spawnParticle(Particle.END_ROD, corners[i], 1,
                            0.0D, 0.0D, 0.0D, 0.0D);
                }
                for (int i = 0; i < corners.length; i++) {
                    spawnPatternSegment(player, corners[i], corners[(i + 1) % corners.length],
                            Particle.END_ROD, dust);
                }
            }
            case "summon", "summon_servants" -> {
                spawnPatternRing(player, point, side, vertical, 0.26D, 12, phase, Particle.SOUL_FIRE_FLAME);
                for (int index = 0; index < 4; index++) {
                    Location spark = point.clone().add(vertical.clone().multiply((index - 1.5D) * 0.12D));
                    player.spawnParticle(Particle.WITCH, spark, 1,
                            0.01D, 0.01D, 0.01D, 0.0D);
                }
            }
            case "arena_inferno" -> {
                spawnPatternRing(player, point, side, vertical, 0.38D, 16, phase, Particle.SOUL_FIRE_FLAME);
                spawnPatternRing(player, point, side, vertical, 0.20D, 12, -phase, Particle.FLAME);
            }
            case "rift_step" -> {
                spawnPatternRing(player, point, side, vertical, 0.30D, 10, phase, Particle.PORTAL);
                spawnPatternRing(player, point, side, vertical, 0.14D, 10, -phase, Particle.END_ROD);
            }
            case "void_snare" -> {
                spawnPatternRing(player, point, side, vertical, 0.32D, 14, phase, Particle.REVERSE_PORTAL);
                for (int index = 0; index < 4; index++) {
                    double angle = phase + index * Math.PI * 0.5D;
                    Location spoke = point.clone().add(side.clone().multiply(Math.cos(angle) * 0.30D))
                            .add(vertical.clone().multiply(Math.sin(angle) * 0.30D));
                    spawnPatternSegment(player, point, spoke, Particle.SMOKE, dust);
                }
            }
            case "echo_pulse" -> {
                spawnPatternRing(player, point, side, vertical, 0.34D, 18, phase, Particle.SCULK_SOUL);
                player.spawnParticle(Particle.SONIC_BOOM, point, 1,
                        0.0D, 0.0D, 0.0D, 0.0D);
            }
            default -> spawnPatternRing(player, point, side, vertical, 0.22D, 12, phase, Particle.END_ROD);
        }
    }

    /** A second, short halo makes the impact readable after the flight ends. */
    private void spawnSpellImpactHalo(Player player, Location center, Vector side,
                                      Vector up, String spellId) {
        if (player == null || center == null || side == null || up == null || spellId == null) {
            return;
        }
        Particle.DustOptions dust = new Particle.DustOptions(spellVisualColor(spellId), 1.25F);
        switch (spellId) {
            case "void_blast" -> {
                spawnPatternRing(player, center, side, up, 1.05D, 18, 0.0D, Particle.DRAGON_BREATH);
                spawnPatternRing(player, center, side, up, 1.55D, 12, 0.25D, Particle.FLAME);
            }
            case "rift_projectile", "rift_step" -> {
                spawnPatternRing(player, center, side, up, 0.72D, 16, 0.0D, Particle.REVERSE_PORTAL);
                spawnPatternSegment(player, center.clone().subtract(up.clone().multiply(0.45D)),
                        center.clone().add(up.clone().multiply(0.75D)), Particle.END_ROD, dust);
            }
            case "rift_arrows", "arrow_salvo" -> {
                for (int lane = -1; lane <= 1; lane++) {
                    Vector offset = side.clone().multiply(lane * 0.42D);
                    spawnPatternSegment(player, center.clone().add(offset).subtract(up.clone().multiply(0.45D)),
                            center.clone().add(offset).add(up.clone().multiply(0.45D)),
                            "arrow_salvo".equals(spellId) ? Particle.CRIT : Particle.SOUL_FIRE_FLAME, dust);
                }
            }
            case "void_mark", "void_snare" -> {
                Location[] corners = signatureSquare(center, side, up, 1.05D, 0.0D);
                for (int index = 0; index < corners.length; index++) {
                    spawnPatternSegment(player, corners[index], corners[(index + 1) % corners.length],
                            Particle.REVERSE_PORTAL, dust);
                }
            }
            case "summon", "summon_servants" -> {
                spawnPatternRing(player, center, side, up, 0.90D, 16, 0.0D, Particle.SOUL_FIRE_FLAME);
                player.spawnParticle(Particle.WITCH, center, 10,
                        0.18D, 0.5D, 0.18D, 0.02D);
            }
            case "arena_inferno" -> {
                spawnPatternRing(player, center, side, up, 2.1D, 24, 0.0D, Particle.SOUL_FIRE_FLAME);
                spawnPatternRing(player, center, side, up, 1.25D, 16, 0.2D, Particle.FLAME);
            }
            case "echo_pulse" -> {
                spawnPatternRing(player, center, side, up, 1.70D, 24, 0.0D, Particle.SCULK_SOUL);
                player.spawnParticle(Particle.SONIC_BOOM, center, 1,
                        0.0D, 0.0D, 0.0D, 0.0D);
            }
            default -> spawnPatternRing(player, center, side, up, 0.75D, 14, 0.0D, Particle.END_ROD);
        }
    }

    /** Draws a compact rotating glyph during the telegraph wind-up. */
    private void spawnSpellTelegraphGlyph(Player player, Location center, Vector side,
                                          Vector up, String spellId, double phase, double progress) {
        if (player == null || center == null || side == null || up == null || spellId == null) {
            return;
        }
        double radius = 0.28D + progress * 0.32D;
        Particle.DustOptions dust = new Particle.DustOptions(spellVisualColor(spellId), 1.05F);
        switch (spellId) {
            case "void_blast", "arena_inferno" ->
                    spawnPatternRing(player, center, side, up, radius, 14, phase, Particle.FLAME);
            case "rift_projectile", "rift_step" ->
                    spawnPatternRing(player, center, side, up, radius, 12, -phase, Particle.REVERSE_PORTAL);
            case "rift_arrows", "arrow_salvo" -> {
                for (int lane = -1; lane <= 1; lane++) {
                    Vector offset = side.clone().multiply(lane * radius * 0.65D);
                    spawnPatternSegment(player, center.clone().add(offset).subtract(up.clone().multiply(radius)),
                            center.clone().add(offset).add(up.clone().multiply(radius)),
                            "arrow_salvo".equals(spellId) ? Particle.CRIT : Particle.SOUL_FIRE_FLAME, dust);
                }
            }
            case "void_mark", "void_snare" -> {
                Location[] corners = signatureSquare(center, side, up, radius, phase * 0.25D);
                for (int index = 0; index < corners.length; index++) {
                    spawnPatternSegment(player, corners[index], corners[(index + 1) % corners.length],
                            Particle.END_ROD, dust);
                }
            }
            case "summon_servants", "summon" -> {
                spawnPatternRing(player, center, side, up, radius, 12, phase, Particle.SOUL_FIRE_FLAME);
                spawnPatternSegment(player, center.clone().subtract(up.clone().multiply(radius)),
                        center.clone().add(up.clone().multiply(radius)), Particle.WITCH, dust);
            }
            case "echo_pulse" -> {
                spawnPatternRing(player, center, side, up, radius, 16, phase, Particle.SCULK_SOUL);
                player.spawnParticle(Particle.SONIC_BOOM, center, 1,
                        0.0D, 0.0D, 0.0D, 0.0D);
            }
            default -> spawnPatternRing(player, center, side, up, radius, 10, phase, Particle.END_ROD);
        }
    }

    private Location[] signatureSquare(Location center, Vector axisA, Vector axisB,
                                       double radius, double phase) {
        Location[] corners = new Location[4];
        for (int index = 0; index < corners.length; index++) {
            double angle = Math.PI / 4.0D + index * Math.PI / 2.0D + phase;
            corners[index] = center.clone()
                    .add(axisA.clone().multiply(Math.cos(angle) * radius))
                    .add(axisB.clone().multiply(Math.sin(angle) * radius));
        }
        return corners;
    }

    private Color spellVisualColor(String spellId) {
        return switch (spellId) {
            case "void_blast" -> Color.fromRGB(244, 39, 125);
            case "rift_projectile", "rift_step" -> Color.fromRGB(69, 218, 255);
            case "rift_arrows" -> Color.fromRGB(255, 72, 72);
            case "arrow_salvo" -> Color.fromRGB(244, 60, 255);
            case "void_mark", "void_snare" -> Color.fromRGB(190, 76, 255);
            case "summon", "summon_servants" -> Color.fromRGB(125, 47, 255);
            case "arena_inferno" -> Color.fromRGB(255, 110, 32);
            case "echo_pulse" -> Color.fromRGB(80, 220, 190);
            default -> Color.fromRGB(220, 220, 255);
        };
    }

    private String bossCueId(String cueBaseId, BossVisualCuePolicy.CueStage stage) {
        if (cueBaseId == null || cueBaseId.isBlank() || stage == null) {
            return "";
        }
        return cueBaseId.trim().toLowerCase(Locale.ROOT) + ":" + stage.name().toLowerCase(Locale.ROOT);
    }

    private String bossCueBaseId(String cueId) {
        if (cueId == null || cueId.isBlank()) {
            return "";
        }
        String normalized = cueId.trim().toLowerCase(Locale.ROOT);
        int split = normalized.lastIndexOf(':');
        return split < 0 ? normalized : normalized.substring(0, split);
    }

    private BossVisualCuePolicy.CueStage bossCueStage(String cueId) {
        if (cueId == null || cueId.isBlank()) {
            return null;
        }
        int split = cueId.lastIndexOf(':');
        if (split < 0 || split >= cueId.length() - 1) {
            return null;
        }
        try {
            return BossVisualCuePolicy.CueStage.valueOf(
                    cueId.substring(split + 1).trim().toUpperCase(Locale.ROOT));
        } catch (IllegalArgumentException ignored) {
            return null;
        }
    }

    private long currentBossVisualCueTick() {
        return System.currentTimeMillis() / 50L;
    }

    private String bossCueAnimationId(String cueId) {
        String spellId = bossCueBaseId(cueId);
        BossVisualCuePolicy.CueStage stage = bossCueStage(cueId);
        if (spellId.isBlank() || stage == null) {
            return BossAnimationId.UNKNOWN.wireId();
        }
        String animation = BossVisualCuePolicy.animationFor(spellId, stage);
        if (!BossAnimationId.isKnown(animation)) {
            getLogger().severe("BOSS_ANIMATION_CATALOG_ERROR event=" + eventId
                    + " spell=" + spellId + " stage=" + stage
                    + " animation=" + animation);
            return BossAnimationId.UNKNOWN.wireId();
        }
        return animation;
    }

    private Sound bossCueSound(String soundId) {
        if (soundId == null || soundId.isBlank()) {
            return Sound.BLOCK_RESPAWN_ANCHOR_CHARGE;
        }
        String enumName = soundId.trim().toUpperCase(Locale.ROOT);
        if (enumName.startsWith("MINECRAFT:")) {
            enumName = enumName.substring("MINECRAFT:".length());
        }
        enumName = enumName.replace('.', '_');
        try {
            return Sound.valueOf(enumName);
        } catch (IllegalArgumentException ignored) {
            return Sound.BLOCK_RESPAWN_ANCHOR_CHARGE;
        }
    }

    private Particle bossCueParticle(String particleId) {
        if (particleId == null || particleId.isBlank()) {
            return Particle.END_ROD;
        }
        return switch (particleId.trim().toUpperCase(Locale.ROOT)) {
            case "DRAGON_BREATH" -> Particle.DRAGON_BREATH;
            case "REVERSE_PORTAL" -> Particle.REVERSE_PORTAL;
            case "SOUL_FIRE_FLAME" -> Particle.SOUL_FIRE_FLAME;
            case "END_ROD" -> Particle.END_ROD;
            case "ELECTRIC_SPARK" -> Particle.ELECTRIC_SPARK;
            case "SCULK_SOUL" -> Particle.SCULK_SOUL;
            case "CRIT" -> Particle.CRIT;
            case "SMOKE" -> Particle.SMOKE;
            case "WITCH" -> Particle.WITCH;
            case "PORTAL" -> Particle.PORTAL;
            case "FLASH" -> Particle.FLASH;
            case "SOUL" -> Particle.SOUL;
            case "SCULK_CHARGE" -> Particle.SCULK_CHARGE;
            case "DUST_CYAN", "DUST_RED", "DUST_PURPLE", "DUST_GREEN", "DUST_WHITE", "DUST_MAGENTA" ->
                    Particle.DUST;
            default -> Particle.END_ROD;
        };
    }

    private Particle.DustOptions bossCueDust(String particleId) {
        if (particleId == null || particleId.isBlank()) {
            return null;
        }
        return switch (particleId.trim().toUpperCase(Locale.ROOT)) {
            case "DUST_CYAN" -> new Particle.DustOptions(Color.fromRGB(69, 218, 255), 1.15F);
            case "DUST_RED" -> new Particle.DustOptions(Color.fromRGB(255, 72, 72), 1.15F);
            case "DUST_PURPLE" -> new Particle.DustOptions(Color.fromRGB(190, 76, 255), 1.15F);
            case "DUST_GREEN" -> new Particle.DustOptions(Color.fromRGB(122, 255, 72), 1.10F);
            case "DUST_WHITE" -> new Particle.DustOptions(Color.WHITE, 1.0F);
            case "DUST_MAGENTA" -> new Particle.DustOptions(Color.fromRGB(244, 60, 255), 1.10F);
            default -> null;
        };
    }

    private void spawnBossCueParticle(Player viewer, Location point, String particleId, int count,
                                      double offsetX, double offsetY, double offsetZ, double extra) {
        if (viewer == null || point == null || point.getWorld() == null
                || !viewer.isOnline() || !viewer.getWorld().equals(point.getWorld())) {
            return;
        }
        Particle particle = bossCueParticle(particleId);
        Particle.DustOptions dust = bossCueDust(particleId);
        recordParticleEmission(Math.max(0, count));
        if (particle == Particle.DUST) {
            viewer.spawnParticle(Particle.DUST, point, count,
                    offsetX, offsetY, offsetZ, 0.0D,
                    dust == null ? new Particle.DustOptions(Color.WHITE, 1.0F) : dust);
            return;
        }
        // SCULK_CHARGE has a Float payload in the 1.21 Bukkit API.  The
        // generic overload otherwise reaches CraftParticle without data and
        // aborts the scheduled boss-cue task mid-cast.
        if (particle == Particle.SCULK_CHARGE) {
            viewer.spawnParticle(Particle.SCULK_CHARGE, point, count,
                    offsetX, offsetY, offsetZ, 0.0D,
                    Float.valueOf((float) extra));
            return;
        }
        viewer.spawnParticle(particle, point, count, offsetX, offsetY, offsetZ, extra);
        if (dust != null) {
            viewer.spawnParticle(Particle.DUST, point, Math.max(1, count / 2),
                    offsetX * 0.75D, offsetY * 0.75D, offsetZ * 0.75D, 0.0D, dust);
        }
    }

    private void spawnRiftProjectileTrail(Player player, Location point, Vector direction, int tick) {
        if (player == null || point == null || point.getWorld() == null || direction == null
                || !player.isOnline() || !player.getWorld().equals(point.getWorld())
                || player.getLocation().distanceSquared(point) > 64.0D * 64.0D) {
            return;
        }
        recordParticleEmission(29);
        Vector forward = direction.clone();
        if (forward.lengthSquared() < 0.0001D) {
            forward = new Vector(0.0D, 0.0D, 1.0D);
        }
        forward.normalize();
        Vector reference = Math.abs(forward.getY()) > 0.85D
                ? new Vector(1.0D, 0.0D, 0.0D)
                : new Vector(0.0D, 1.0D, 0.0D);
        Vector side = forward.clone().crossProduct(reference).normalize();
        Vector vertical = side.clone().crossProduct(forward).normalize();
        Particle.DustOptions riftDust = new Particle.DustOptions(Color.fromRGB(69, 218, 255), 1.20F);
        for (int i = 0; i < 8; i++) {
            double angle = tick * 0.95D + i * Math.PI / 4.0D;
            double radius = 0.16D + i * 0.025D;
            Location spiral = point.clone()
                    .add(side.clone().multiply(Math.cos(angle) * radius))
                    .add(vertical.clone().multiply(Math.sin(angle) * radius))
                    .add(forward.clone().multiply((i - 3.5D) * 0.035D));
            player.spawnParticle(Particle.REVERSE_PORTAL, spiral, 2,
                    0.015D, 0.015D, 0.015D, 0.01D);
            player.spawnParticle(Particle.DUST, spiral, 1,
                    0.01D, 0.01D, 0.01D, 0.0D, riftDust);
        }
        player.spawnParticle(Particle.DRAGON_BREATH, point, 5,
                0.04D, 0.04D, 0.04D, 0.01D);
    }

    private void spawnPatternRing(Player player, Location center, Vector axisA, Vector axisB,
                                  double radius, int points, double phase, Particle particle) {
        spawnPatternRing(player, center, axisA, axisB, radius, points, phase, particle, null);
    }

    private void spawnPatternRing(Player player, Location center, Vector axisA, Vector axisB,
                                  double radius, int points, double phase, Particle particle,
                                  Particle.DustOptions dust) {
        if (player == null || center == null || center.getWorld() == null || !player.isOnline()
                || !player.getWorld().equals(center.getWorld())
                || player.getLocation().distanceSquared(center) > 64.0D * 64.0D) {
            return;
        }
        recordParticleEmission(Math.max(0, points));
        for (int i = 0; i < points; i++) {
            double angle = phase + (Math.PI * 2.0D * i / points);
            Location ringPoint = center.clone()
                    .add(axisA.clone().multiply(Math.cos(angle) * radius))
                    .add(axisB.clone().multiply(Math.sin(angle) * radius));
            if (particle == Particle.DUST && dust != null) {
                player.spawnParticle(particle, ringPoint, 1,
                        0.0D, 0.0D, 0.0D, 0.0D, dust);
            } else {
                player.spawnParticle(particle, ringPoint, 1,
                        0.0D, 0.0D, 0.0D, 0.0D);
            }
        }
    }

    private void spawnPatternSegment(Player player, Location start, Location end, Particle particle,
                                     Particle.DustOptions dust) {
        if (player == null || start == null || end == null || start.getWorld() == null
                || !player.isOnline() || !player.getWorld().equals(start.getWorld())
                || player.getLocation().distanceSquared(start) > 64.0D * 64.0D) {
            return;
        }
        Vector delta = end.toVector().subtract(start.toVector());
        int steps = 4;
        recordParticleEmission((steps - 1) * (dust == null ? 1 : 2));
        for (int i = 1; i < steps; i++) {
            Location linePoint = start.clone().add(delta.clone().multiply(i / (double) steps));
            if (particle == Particle.DUST) {
                // Particle.DUST requires DustOptions as its data payload;
                // sending it through the generic overload throws on Paper
                // and aborts the repeating telegraph task.
                Particle.DustOptions safeDust = dust != null
                        ? dust : new Particle.DustOptions(Color.WHITE, 1.0F);
                player.spawnParticle(Particle.DUST, linePoint, 1,
                        0.0D, 0.0D, 0.0D, 0.0D, safeDust);
            } else if (particle == Particle.SCULK_CHARGE) {
                // SCULK_CHARGE also has required typed data in the 1.21
                // Bukkit API.  The generic overload throws when the payload
                // is omitted, which can abort the repeating boss-cue task.
                player.spawnParticle(Particle.SCULK_CHARGE, linePoint, 1,
                        0.0D, 0.0D, 0.0D, 0.0D,
                        Float.valueOf(0.0F));
            } else {
                player.spawnParticle(particle, linePoint, 1,
                        0.0D, 0.0D, 0.0D, 0.0D);
                if (dust != null) {
                    player.spawnParticle(Particle.DUST, linePoint, 1,
                            0.0D, 0.0D, 0.0D, 0.0D, dust);
                }
            }
        }
    }

    private boolean isSpellFlightAllowed(LivingEntity caster, boolean forced) {
        if (caster == null || !caster.isValid() || caster.isDead()) {
            return false;
        }
        String kind = readString(caster, keyKind);
        if (EVENT_KIND_BOSS.equals(kind)) {
            return phase == EventPhase.BOSS_ACTIVE || forced
                    || testCombatAiMode && isTestBoss(caster);
        }
        return (EVENT_KIND_ELITE.equals(kind) || EVENT_KIND_WAVE_GUARDIAN.equals(kind))
                && isMiniBossCombatPhase();
    }

    private boolean isMiniBossCombatEntity(Entity entity) {
        return entity instanceof LivingEntity
                && (EVENT_KIND_ELITE.equals(readString(entity, keyKind))
                || EVENT_KIND_WAVE_GUARDIAN.equals(readString(entity, keyKind)))
                && !readString(entity, keyMiniBossSpell).isBlank();
    }

    private void miniBossRiftStep(LivingEntity miniBoss, Player target) {
        Location anchor = coreCombatAnchorLocation();
        Location destination = findSafeCombatLocation(anchor, target.getLocation(), config.containmentRadius());
        if (destination != null) {
            teleportCombatEntity(miniBoss, destination);
        }
        target.damage(WaveDamagePolicy.minimumCombatDamage(
                config.miniBossTuning().riftStepDamage(), WAVE_MOB_DAMAGE_REDUCTION), miniBoss);
        target.addPotionEffect(new PotionEffect(PotionEffectType.SLOWNESS,
                SLOWNESS_DEBUFF_TICKS, abilityDebuffAmplifier("mini-rift-step"), false, true, true));
        spawnEventParticle(target.getLocation().add(0.0D, 1.0D, 0.0D), Particle.PORTAL,
                24, 0.5D, 0.8D, 0.5D, 0.02D);
    }

    private void miniBossVoidSnare(LivingEntity miniBoss, Player target, Location mark) {
        target.damage(WaveDamagePolicy.minimumCombatDamage(
                config.miniBossTuning().voidSnareDamage(), WAVE_MOB_DAMAGE_REDUCTION), miniBoss);
        target.addPotionEffect(new PotionEffect(PotionEffectType.SLOWNESS,
                SLOWNESS_DEBUFF_TICKS, abilityDebuffAmplifier("mini-void-snare"), false, true, true));
        target.addPotionEffect(new PotionEffect(PotionEffectType.WEAKNESS,
                MINI_VOID_SNARE_DEBUFF_TICKS, abilityDebuffAmplifier("mini-void-snare"), false, true, true));
        spawnEventParticle(mark, Particle.REVERSE_PORTAL, 28, 1.2D, 0.1D, 1.2D, 0.02D);
    }

    private void miniBossEchoPulse(LivingEntity miniBoss) {
        Location center = miniBoss.getLocation();
        for (Player player : activeLivingPlayers()) {
            if (!realitySplitTargetAllowed(miniBoss, player)) {
                continue;
            }
            if (player.getLocation().distanceSquared(center) > 25.0D) {
                continue;
            }
            player.damage(WaveDamagePolicy.minimumCombatDamage(
                    config.miniBossTuning().echoPulseDamage(), WAVE_MOB_DAMAGE_REDUCTION), miniBoss);
            Vector push = player.getLocation().toVector().subtract(center.toVector());
            if (push.lengthSquared() < 0.01D) {
                push = new Vector(0.0D, 0.25D, 0.0D);
            }
            player.setVelocity(push.normalize().multiply(0.35D).setY(0.22D));
            player.addPotionEffect(new PotionEffect(PotionEffectType.WEAKNESS,
                    MINI_ECHO_PULSE_DEBUFF_TICKS, abilityDebuffAmplifier("mini-echo-pulse"), false, true, true));
        }
        spawnEventParticle(center.add(0.0D, 1.0D, 0.0D), Particle.END_ROD,
                32, 1.0D, 0.6D, 1.0D, 0.03D);
    }

    private void miniBossArrowSalvo(LivingEntity miniBoss, Player target) {
        if (miniBoss == null || target == null || !isCombatTarget(target)) {
            return;
        }
        riftArrowVolley(miniBoss, target, EndRiftAiPolicy.MiniBossSpell.ARROW_SALVO.id(),
                SkeletonCombatPolicy.arrowProfile(true));
        spawnEventParticle(target.getLocation().add(0.0D, 1.0D, 0.0D), Particle.END_ROD,
                18, 0.45D, 0.7D, 0.45D, 0.02D);
        miniBoss.getWorld().playSound(miniBoss.getLocation(), Sound.ENTITY_SKELETON_SHOOT,
                0.9F, 1.35F);
    }

    /**
     * A miniboss-only control spell: one bounded visual narcotic profile plus
     * ten seconds of Wither.  The profile is selected per cast, while the
     * server remains authoritative and never depends on the optional client.
     */
    private void miniBossRiftEuphoria(LivingEntity miniBoss, Player target) {
        if (miniBoss == null || target == null || !isCombatTarget(target)) {
            return;
        }
        EndRiftAiPolicy.NarcoticEffect effect = EndRiftAiPolicy.randomNarcoticEffect(
                random.nextLong());
        PotionEffectType narcoticType = narcoticPotionEffect(effect);
        target.addPotionEffect(new PotionEffect(narcoticType,
                MINIBOSS_NARCOTIC_DURATION_TICKS, 0, false, true, true), true);
        target.addPotionEffect(new PotionEffect(PotionEffectType.WITHER,
                MINIBOSS_WITHER_DURATION_TICKS, 0, false, true, true), true);
        target.playSound(target.getLocation(), Sound.ENTITY_WARDEN_HEARTBEAT, 0.7F, 0.65F);
        spawnEventParticle(target.getLocation().add(0.0D, 1.0D, 0.0D),
                Particle.WITCH, 28, 0.5D, 0.8D, 0.5D, 0.02D);
        getLogger().info("MINIBOSS_NARCOTIC_EFFECT entity=" + miniBoss.getUniqueId()
                + " target=" + target.getUniqueId() + " effect=" + effect.id()
                + " potion=" + effect.potionEffectId()
                + " duration_ticks=" + MINIBOSS_NARCOTIC_DURATION_TICKS
                + " wither_ticks=" + MINIBOSS_WITHER_DURATION_TICKS);
    }

    private void enforceCombatLeash(Entity entity, Location anchor, double radius, String logMarker) {
        if (entity == null || anchor == null || entity.getWorld() == null
                || !entity.getWorld().equals(anchor.getWorld())) {
            return;
        }
        Location current = entity.getLocation();
        boolean standingOnCore = isCoreBlockPosition(current);
        boolean outsideHorizontalRadius = horizontalDistanceSquared(current, anchor) > radius * radius;
        boolean outsideVerticalRadius = outsideCombatVertical(current, anchor);
        int chamber = realitySplitChamberId(entity);
        boolean outsideClosedChamber = chamber >= 0
                && !realitySplitChamberController.allChambersComplete(generation)
                && !ChamberIsolationPolicy.containsPoint(chamber,
                current.getX() - anchor.getX(), current.getZ() - anchor.getZ(),
                realitySplitChamberController.assignment().chamberCount());
        if (!standingOnCore && !outsideHorizontalRadius && !outsideVerticalRadius
                && !outsideClosedChamber) {
            return;
        }
        // The anchor is the solid Core block.  Never prefer it as an entity
        // destination: resolve to a nearby passable floor position instead.
        double minCoreDistance = EVENT_KIND_BOSS.equals(readString(entity, keyKind))
                ? MIN_BOSS_CORE_DISTANCE_BLOCKS : MIN_WAVE_CORE_DISTANCE_BLOCKS;
        Location from = current.clone();
        Location safe = findSafeCombatLocation(anchor, null, radius - 0.75D, minCoreDistance,
                outsideClosedChamber ? chamber : -1);
        if (safe != null && teleportCombatEntity(entity, safe)) {
            if (EVENT_KIND_BOSS.equals(readString(entity, keyKind))) {
                getLogger().info("BOSS_MOVE_TELEPORT boss=" + entity.getUniqueId()
                        + " reason=leash from=" + locationText(from) + " to=" + locationText(safe)
                        + " target=" + (entity instanceof Mob mob && mob.getTarget() != null
                        ? mob.getTarget().getUniqueId() : "none") + " phase=" + phase);
            } else {
                getLogger().info(logMarker + " entity=" + entity.getUniqueId()
                        + " location=" + locationText(safe)
                        + (outsideClosedChamber ? " chamber=" + chamber : ""));
            }
        }
    }

    private PotionEffectType narcoticPotionEffect(EndRiftAiPolicy.NarcoticEffect effect) {
        if (effect == null) {
            return PotionEffectType.NAUSEA;
        }
        return switch (effect.potionEffectId()) {
            case "DARKNESS" -> PotionEffectType.DARKNESS;
            case "GLOWING" -> PotionEffectType.GLOWING;
            case "POISON" -> PotionEffectType.POISON;
            case "BLINDNESS" -> PotionEffectType.BLINDNESS;
            case "SLOWNESS" -> PotionEffectType.SLOWNESS;
            case "MINING_FATIGUE" -> PotionEffectType.MINING_FATIGUE;
            case "WEAKNESS" -> PotionEffectType.WEAKNESS;
            case "NAUSEA" -> PotionEffectType.NAUSEA;
            default -> PotionEffectType.NAUSEA;
        };
    }

    private double horizontalDistanceSquared(Location first, Location second) {
        if (first == null || second == null || first.getWorld() == null || second.getWorld() == null
                || !first.getWorld().equals(second.getWorld())) {
            return Double.POSITIVE_INFINITY;
        }
        double deltaX = first.getX() - second.getX();
        double deltaZ = first.getZ() - second.getZ();
        return deltaX * deltaX + deltaZ * deltaZ;
    }

    private double boundedCombatRadius(double configuredRadius) {
        return Math.max(1.0D, Math.min(MAX_COMBAT_RADIUS_BLOCKS, configuredRadius));
    }

    private int abilityDebuffAmplifier(String abilityId) {
        if (abilityId == null) {
            return 0;
        }
        return switch (abilityId) {
            case "wave-arrow" -> 0;
            case "mini-rift-step", "mini-void-snare", "mini-echo-pulse" -> 1;
            case "boss-void-blast", "boss-arena-inferno", "boss-rift-projectile" -> 1;
            case "boss-void-mark" -> 2;
            case "boss-final-strike" -> 1;
            default -> 0;
        };
    }

    /** Number used by bounded wave scaling; never grows past the configured roster cap. */
    private int eventScalePlayers() {
        int players = officialRewardRoster.size();
        if (players <= 0) {
            players = activeLivingPlayers().size();
        }
        int configuredMin = config == null ? WaveScalingPolicy.MIN_PLAYERS : config.minPlayers();
        int configuredMax = config == null ? WaveScalingPolicy.MAX_PLAYERS : config.maxPlayers();
        return Math.max(configuredMin, Math.min(configuredMax, players));
    }

    /**
     * Freeze boss scaling to the official roster once the ritual commits it.
     * Before that point this falls back to the bounded live audience so local
     * test bosses still use the same deterministic policy.
     */
    private double computedBossMaxHealth() {
        return BossHealthPolicy.maxHealthForPlayers(eventScalePlayers());
    }

    private boolean isOfficialBoss(LivingEntity boss) {
        return boss != null && isOfficialEntity(boss) && keyBossMaxHealth != null
                && boss.getPersistentDataContainer().has(keyBossMaxHealth, PersistentDataType.DOUBLE);
    }

    private boolean isOfficialBoss(Entity entity) {
        return entity instanceof LivingEntity living && isOfficialBoss(living);
    }

    /** Read the frozen real-entity max health persisted on the current boss. */
    private double bossMaxHealth(LivingEntity boss) {
        double fallback = computedBossMaxHealth();
        if (boss == null || keyBossMaxHealth == null) {
            return fallback;
        }
        Double persisted = boss.getPersistentDataContainer().get(
                keyBossMaxHealth, PersistentDataType.DOUBLE);
        if (persisted == null || !Double.isFinite(persisted) || persisted <= 0.0D) {
            return fallback;
        }
        return BossHealthPolicy.clampCurrent(persisted, BossHealthPolicy.MAX_HEALTH);
    }

    private double configuredCombatVerticalRadius() {
        return config == null ? 3.0D : Math.max(0.0D,
                Math.min(3.0D, config.arenaVerticalRadius()));
    }

    /** Compare block levels, not entity fractional feet, for a block radius. */
    private boolean outsideCombatVertical(Location location, Location anchor) {
        if (location == null || anchor == null) {
            return true;
        }
        return Math.abs(location.getBlockY() - anchor.getBlockY())
                > Math.ceil(configuredCombatVerticalRadius());
    }

    private Location findSafeCombatLocation(Location anchor, Location preferred, double radius) {
        return findSafeCombatLocation(anchor, preferred, radius, MIN_WAVE_CORE_DISTANCE_BLOCKS);
    }

    /**
     * Resolve a combat destination on the real arena floor.  The Core block is
     * an anchor, never a valid entity destination: every caller supplies a
     * minimum horizontal separation so a failed path or teleport cannot stack
     * an event mob on the Core.  Candidate inspection is bounded and the pure
     * BossMovementPolicy owns the deterministic choice.
     */
    private Location findSafeCombatLocation(Location anchor, Location preferred, double radius,
                                            double minCoreDistance) {
        return findSafeCombatLocation(anchor, preferred, radius, minCoreDistance, -1);
    }

    /**
     * Chamber-aware variant used only by Wave 6.  Filtering candidates before
     * the pure movement policy is important: choosing a safe point first and
     * clamping it afterwards could still make Paper path through a neighbouring
     * room on the way to that point.
     */
    private Location findSafeCombatLocation(Location anchor, Location preferred, double radius,
                                            double minCoreDistance, int chamberId) {
        if (anchor == null || anchor.getWorld() == null) {
            return null;
        }
        double safeRadius = Math.max(1.0D, radius);
        double safeMinDistance = Math.max(0.0D, Math.min(minCoreDistance, safeRadius - 0.25D));
        int chamberCount = realitySplitChamberController.assignment().chamberCount();
        Location center = anchor.clone();
        List<BossMovementPolicy.Candidate> candidates = new ArrayList<>();
        Map<String, Location> candidateLocations = new LinkedHashMap<>();
        for (int attempt = 0; attempt < 48; attempt++) {
            double angle = attempt * 2.399963229728653D;
            double distance = attempt == 0 ? 0.0D : safeMinDistance + 0.75D + (attempt % 7) * 1.65D;
            Location candidate = attempt < 4 && preferred != null
                    ? preferred.clone().add(Math.cos(angle) * (attempt * 0.25D), 0.0D,
                    Math.sin(angle) * (attempt * 0.25D))
                    : center.clone().add(Math.cos(angle) * distance, 0.0D, Math.sin(angle) * distance);
            if (chamberId >= 0 && !ChamberIsolationPolicy.containsPoint(
                    chamberId, candidate.getX() - center.getX(), candidate.getZ() - center.getZ(),
                    chamberCount)) {
                continue;
            }
            Block feet = candidate.getBlock();
            Block head = feet.getRelative(BlockFace.UP);
            Block floor = feet.getRelative(BlockFace.DOWN);
            Location resolved = new Location(candidate.getWorld(), feet.getX() + 0.5D,
                    feet.getY(), feet.getZ() + 0.5D);
            String id = "candidate-" + attempt;
            BossMovementPolicy.Candidate policyCandidate = new BossMovementPolicy.Candidate(
                    id, resolved.getX(), resolved.getY(), resolved.getZ(),
                    feet.isPassable(), head.isPassable(), floor.getType().isSolid(),
                    feet.isLiquid() || head.isLiquid() || floor.isLiquid(),
                    isFireBlock(feet) || isFireBlock(head) || isFireBlock(floor),
                    isWebBlock(feet) || isWebBlock(head) || isWebBlock(floor),
                    isTemporaryMovementHazard(feet) || isTemporaryMovementHazard(head)
                            || isTemporaryMovementHazard(floor),
                    isCoreBlockPosition(resolved), floor.getType().name());
            candidates.add(policyCandidate);
            candidateLocations.put(id, resolved);
        }
        BossMovementPolicy.Candidate selected = BossMovementPolicy.chooseSafeDestination(
                new BossMovementPolicy.Anchor(center.getX(), center.getY(), center.getZ()),
                preferred == null ? null : new BossMovementPolicy.Target(
                        preferred.getX(), preferred.getY(), preferred.getZ()),
                candidates, safeRadius, configuredCombatVerticalRadius(), safeMinDistance,
                Set.of("COBWEB", "POWDER_SNOW", "SWEET_BERRY_BUSH", "FIRE", "SOUL_FIRE"));
        if (selected == null) {
            selected = BossMovementPolicy.chooseStuckFallback(
                    new BossMovementPolicy.Anchor(center.getX(), center.getY(), center.getZ()),
                    candidates, safeRadius, configuredCombatVerticalRadius(), safeMinDistance,
                    Set.of("COBWEB", "POWDER_SNOW", "SWEET_BERRY_BUSH", "FIRE", "SOUL_FIRE"));
        }
        return selected == null ? null : candidateLocations.get(selected.id());
    }

    private boolean isFireBlock(Block block) {
        if (block == null) {
            return false;
        }
        Material material = block.getType();
        return material == Material.FIRE || material == Material.SOUL_FIRE;
    }

    private boolean isWebBlock(Block block) {
        return block != null && block.getType() == Material.COBWEB;
    }

    private boolean isTemporaryMovementHazard(Block block) {
        if (block == null) {
            return true;
        }
        Material material = block.getType();
        return material == Material.POWDER_SNOW || material == Material.SWEET_BERRY_BUSH
                || material == Material.MAGMA_BLOCK
                || material == Material.POINTED_DRIPSTONE;
    }

    private boolean isCombatPhase() {
        if (testCombatAiMode) {
            return true;
        }
        return switch (phase) {
            case WAVE_1, INTERMISSION_1, WAVE_2, INTERMISSION_2, WAVE_3,
                    INTERMISSION_3, WAVE_4, CORE_RESTORATION, WAVE_5,
                    INTERMISSION_5, WAVE_6, INTERMISSION_6, WAVE_7,
                    PRE_BOSS_COOLDOWN, BOSS_CINEMATIC,
                    BOSS_ACTIVE, BOSS_FINISH -> true;
            default -> false;
        };
    }

    /**
     * Keep stale wave entities from fighting during an intermission or the
     * boss fight, while explicitly keeping the final reality-split wave on
     * the same controller as waves 1-5.  Disposable local AI tests are the
     * sole exception because they intentionally run outside the official
     * state machine.
     */
    private boolean isWaveAiCombatPhase(int wave) {
        if (testCombatAiMode) {
            return true;
        }
        return switch (wave) {
            case 1 -> phase == EventPhase.WAVE_1;
            case 2 -> phase == EventPhase.WAVE_2;
            case 3 -> phase == EventPhase.WAVE_3;
            case 4 -> phase == EventPhase.WAVE_4;
            case 5 -> phase == EventPhase.WAVE_5;
            case 6 -> phase == EventPhase.WAVE_6;
            case 7 -> phase == EventPhase.WAVE_7;
            default -> false;
        };
    }

    /**
     * Wave zero is reserved for boss-servant summons.  They are not an
     * official numbered wave, but while the boss is active they still belong
     * to this generation's bounded AI controller and must chase players.
     */
    private boolean isWaveAiCombatEntity(Entity entity) {
        if (entity == null || !isWaveCombatKind(readString(entity, keyKind))) {
            return false;
        }
        if (isWaveAiCombatPhase(readInt(entity, keyWave, 0))) {
            return true;
        }
        // Disposable `/cmend test wave` entities intentionally live while
        // the official state machine is READY_FOR_PLAYERS.  They are still
        // event-owned and must exercise the same path/target controller; a
        // natural mob can never reach this method because tickWaveMobAi()
        // iterates only ownedEntities.
        if (!isOfficialEntity(entity)
                && "local".equalsIgnoreCase(config == null ? "" : config.environment())) {
            return true;
        }
        return spellServants.contains(entity.getUniqueId())
                && (phase == EventPhase.BOSS_ACTIVE || testCombatAiMode);
    }

    private boolean isMiniBossCombatPhase() {
        return testCombatAiMode || phase == EventPhase.WAVE_1 || phase == EventPhase.WAVE_2
                || phase == EventPhase.WAVE_3 || phase == EventPhase.WAVE_4
                || phase == EventPhase.WAVE_5 || phase == EventPhase.WAVE_6
                || phase == EventPhase.WAVE_7
                || hasLiveTestWaveEntities();
    }

    private boolean hasLiveTestWaveEntities() {
        for (Entity entity : ownedEntities.values()) {
            if (isWaveCombatKind(readString(entity, keyKind))
                    && !isOfficialEntity(entity) && isLiveOwnedEntity(entity.getUniqueId())) {
                return true;
            }
        }
        return false;
    }

    private boolean isActiveArenaParticipant(Player player) {
        if (player == null || !player.isOnline() || player.isDead() || player.getWorld() == null
                || player.getHealth() <= 0.0D
                || player.getGameMode() == GameMode.SPECTATOR
                || player.getGameMode() == GameMode.CREATIVE
                || !player.getWorld().getName().equals(worldName)) {
            return false;
        }
        return isArenaLocation(player.getLocation());
    }

    private boolean isCreativeTestTarget(Player player) {
        return creativeTestTask != null && creativeTestPlayerUuid != null
                && creativeTestPlayerUuid.equals(player == null ? null : player.getUniqueId())
                && player != null && player.isOnline() && !player.isDead()
                && player.getHealth() > 0.0D && player.getGameMode() == GameMode.CREATIVE
                && player.getWorld() != null && player.getWorld().getName().equals(worldName)
                && isArenaLocation(player.getLocation());
    }

    private boolean isCombatTarget(Player player) {
        return isActiveArenaParticipant(player) || isCreativeTestTarget(player);
    }

    private boolean isTransitionRunePhase(EventPhase candidate) {
        return candidate == EventPhase.INTERMISSION_1
                || candidate == EventPhase.INTERMISSION_2
                || candidate == EventPhase.INTERMISSION_3
                || candidate == EventPhase.INTERMISSION_5
                || candidate == EventPhase.INTERMISSION_6;
    }

    private boolean isOfficialAttempt() {
        return !testCombatAiMode && generation > 0L && !officialRewardRoster.isEmpty();
    }

    /** Schema 4 is the only configuration allowed to enter the current flow. */
    private boolean isOfficialCurrentAttempt() {
        return isOfficialAttempt() && config != null && config.isCurrentFlow();
    }

    /** The chamber controller is used by the seventh numbered wave. */
    private int chamberWaveNumber() {
        return isOfficialCurrentAttempt() ? 7 : 6;
    }

    /** True when the entity belongs to the currently active isolated chamber wave. */
    private boolean isChamberWaveEntity(Entity entity) {
        return entity != null && readInt(entity, keyWave, 0) == chamberWaveNumber();
    }

    /**
     * A visual spectator does not need to be in the official reward roster.
     * Anyone physically inside the configured arena must receive the same
     * client UUID bindings, otherwise skeletons fall back to the vanilla skin
     * for operators and local spectators standing just outside the pads.
     */
    private boolean isEventVisualViewer(Player player) {
        if (player == null || !player.isOnline()) {
            return false;
        }
        World world = Bukkit.getWorld(worldName);
        return world != null && world.equals(player.getWorld())
                && (isCombatTarget(player) || isArenaLocation(player.getLocation()));
    }

    /**
     * Current intermissions are an actual transition-rune hold, not an unattended
     * timer. A generous watchdog prevents a disconnected roster from leaving
     * the event in an unbounded half-state; the normal path completes only
     * after every frozen player has held a unique rune for five seconds.
     */
    private void tickCurrentIntermission() {
        if (!isTransitionRunePhase(phase)) {
            return;
        }
        long now = System.currentTimeMillis();
        if (phaseDeadlineMillis <= 0L) {
            phaseDeadlineMillis = now + 10 * 60_000L;
            transitionRuneDeadlineMillis = phaseDeadlineMillis;
        }
        if (now >= phaseDeadlineMillis) {
            getLogger().warning("END_RIFT_INTERMISSION_TIMEOUT event=" + eventId
                    + " phase=" + phase + " roster=" + officialRewardRoster);
            removeTransitionRuneVisuals();
            pads.clear();
            padOccupants.clear();
            runeVisualOccupants.clear();
            transitionRuneController.reset();
            transitionRuneRenderStates.clear();
            transitionRuneWave = 0;
            phaseDeadlineMillis = 0L;
            forcePhase(EventPhase.READY_FOR_PLAYERS, "transition rune watchdog timeout");
            return;
        }
        int completedWave = transitionRuneWave > 0
                ? transitionRuneWave : completedWaveForIntermission(phase);
        if (completedWave < 1 || completedWave > (isOfficialCurrentAttempt() ? 6 : 5)) {
            forcePhase(EventPhase.RECOVERY_REQUIRED, "invalid transition rune wave");
            return;
        }
        if (pads.size() != officialRewardRoster.size()
                && !prepareTransitionRunes(completedWave)) {
            getLogger().severe("END_RIFT_INTERMISSION_RUNE_SETUP_FAILED event=" + eventId
                    + " completed_wave=" + completedWave);
            forcePhase(EventPhase.RECOVERY_REQUIRED, "transition rune setup failed");
            return;
        }
        Set<UUID> roster = new LinkedHashSet<>(officialRewardRoster);
        List<TransitionRunePolicy.RuneOccupancy> occupancies = new ArrayList<>();
        for (Map.Entry<String, UUID> entry : padOccupants.entrySet()) {
            Player player = Bukkit.getPlayer(entry.getValue());
            boolean connected = player != null && player.isOnline();
            boolean alive = connected && !player.isDead() && player.getHealth() > 0.0D;
            boolean eligible = alive && player.getGameMode() != GameMode.SPECTATOR
                    && player.getGameMode() != GameMode.CREATIVE
                    && isArenaLocation(player.getLocation());
            occupancies.add(new TransitionRunePolicy.RuneOccupancy(
                    entry.getValue(), entry.getKey(), connected, alive, eligible));
        }
        TransitionRuneController.Observation observation = transitionRuneController.observe(
                roster, occupancies, now);
        transitionRuneRenderStates.clear();
        for (EventSnapshot.PadSnapshot pad : pads) {
            String key = padKey(pad);
            transitionRuneRenderStates.put(key, padOccupants.containsKey(key)
                    ? observation.renderState() : TransitionRuneController.RenderState.EMPTY);
        }
        refreshRuneOverlayVisuals();
        if (!observation.justCompleted()) {
            return;
        }
        int nextWave = completedWave + 1;
        removeTransitionRuneVisuals();
        pads.clear();
        padOccupants.clear();
        runeVisualOccupants.clear();
        transitionRuneController.reset();
        transitionRuneRenderStates.clear();
        transitionRuneWave = 0;
        transitionRuneDeadlineMillis = 0L;
        phaseDeadlineMillis = 0L;
        activeWave = nextWave;
        EventPhase nextPhase = wavePhase(nextWave);
        if (nextPhase == null || !transition(nextPhase,
                "transition runes held after wave " + completedWave,
                eventId + ":wave:" + nextWave)) {
            forcePhase(EventPhase.RECOVERY_REQUIRED, "transition rune handoff failed");
            return;
        }
        if (nextWave == chamberWaveNumber()) {
            realitySplitChamberController.begin(generation, new ArrayList<>(officialRewardRoster));
        }
        saveStateAsync();
        announceEventTitle("§dВОЛНА " + nextWave,
                "§fРазлом снова открывает проход", true);
        spawnWave(nextWave, false);
    }

    private EventPhase wavePhase(int wave) {
        return switch (wave) {
            case 1 -> EventPhase.WAVE_1;
            case 2 -> EventPhase.WAVE_2;
            case 3 -> EventPhase.WAVE_3;
            case 4 -> EventPhase.WAVE_4;
            case 5 -> EventPhase.WAVE_5;
            case 6 -> EventPhase.WAVE_6;
            case 7 -> EventPhase.WAVE_7;
            default -> null;
        };
    }

    private boolean prepareTransitionRunes(int completedWave) {
        if (completedWave < 1
                || completedWave > (isOfficialCurrentAttempt() ? 6 : 5)
                || !isOfficialAttempt()) {
            return false;
        }
        World world = Bukkit.getWorld(worldName);
        if (world == null || officialRewardRoster.isEmpty()) {
            return false;
        }
        removeTransitionRuneVisuals();
        pads.clear();
        padOccupants.clear();
        runeVisualOccupants.clear();
        transitionRuneRenderStates.clear();
        List<Double> radii = completedWave >= 4
                ? List.of(9.0D, 11.0D, 13.0D, 15.0D, 17.0D)
                : transitionPadRadii();
        PadLayout.Result layout = PadLayout.compute(officialRewardRoster.size(),
                completedWave * 37.0D, radii);
        if (!layout.valid() || layout.points().size() != officialRewardRoster.size()) {
            return false;
        }
        Set<String> coordinates = new HashSet<>();
        List<EventSnapshot.PadSnapshot> planned = new ArrayList<>();
        for (PadLayout.Point point : layout.points()) {
            Block padBlock = findSafePadBlock(world, point, coordinates);
            if (padBlock == null) {
                return false;
            }
            coordinates.add(padBlock.getX() + ":" + padBlock.getY() + ":" + padBlock.getZ());
            double dx = padBlock.getX() + 0.5D - (coreX + 0.5D);
            double dz = padBlock.getZ() + 0.5D - (coreZ + 0.5D);
            planned.add(new EventSnapshot.PadSnapshot(
                    padBlock.getX(), padBlock.getY(), padBlock.getZ(),
                    Math.sqrt(dx * dx + dz * dz), Math.atan2(dz, dx),
                    padBlock.getBlockData().getAsString()));
        }
        pads.addAll(planned);
        transitionRuneWave = completedWave;
        transitionRuneDeadlineMillis = System.currentTimeMillis() + 10 * 60_000L;
        phaseDeadlineMillis = transitionRuneDeadlineMillis;
        transitionRuneController.reset();
        rebuildPersistedVisuals();
        getLogger().info("END_RIFT_TRANSITION_RUNES_READY event=" + eventId
                + " completed_wave=" + completedWave + " count=" + pads.size()
                + " hold_ms=5000 timeout_ms=600000");
        return true;
    }

    private List<Double> transitionPadRadii() {
        if (config == null || config.padRadii().isEmpty()) {
            return List.of(5.0D, 7.0D, 9.0D, 11.0D, 13.0D);
        }
        List<Double> radii = new ArrayList<>(config.padRadii());
        radii.addAll(List.of(9.0D, 11.0D, 13.0D, 15.0D, 17.0D));
        return radii.stream().filter(value -> Double.isFinite(value) && value > 0.0D)
                .distinct().toList();
    }

    private void tickPreBossCooldown() {
        if (phase != EventPhase.PRE_BOSS_COOLDOWN || !isOfficialAttempt()) {
            return;
        }
        long now = System.currentTimeMillis();
        if (phaseDeadlineMillis <= 0L) {
            phaseDeadlineMillis = now + 20_000L;
            announceEventTitle("§5ТИШИНА ПЕРЕД РАЗЛОМОМ",
                    "§fДвадцать секунд до пробуждения Хранителя", true);
            saveStateAsync();
            return;
        }
        if (now < phaseDeadlineMillis) {
            renderPreBossCooldownVisual(now);
            return;
        }
        phaseDeadlineMillis = 0L;
        if (!transition(EventPhase.BOSS_CINEMATIC,
                "Wave 7 complete; pre-boss cooldown complete", eventId + ":boss-cinematic")) {
            forcePhase(EventPhase.RECOVERY_REQUIRED, "pre-boss cooldown handoff failed");
            return;
        }
        phaseDeadlineMillis = now + BOSS_CINEMATIC_DURATION_TICKS * 50L;
        scheduleOfficialBossSpawn();
    }

    private void renderPreBossCooldownVisual(long now) {
        Location core = coreCombatAnchorLocation();
        if (core == null) {
            return;
        }
        double rotation = now * 0.0012D;
        for (Player viewer : eventAudience()) {
            if (!isEventParticleViewer(viewer, core)) {
                continue;
            }
            spawnPatternRing(viewer, core.clone().add(0.0D, 0.08D, 0.0D),
                    new Vector(1.0D, 0.0D, 0.0D), new Vector(0.0D, 0.0D, 1.0D),
                    6.0D, 24, rotation, Particle.REVERSE_PORTAL);
            viewer.spawnParticle(Particle.END_ROD, core.clone().add(0.0D, 1.0D, 0.0D),
                    3, 0.35D, 0.7D, 0.35D, 0.01D);
        }
    }

    /**
     * The cinematic has no combat entity yet.  This watchdog makes the
     * durable phase self-healing if an admin command or a delayed scheduler
     * callback leaves the spawn task absent; a restart still recovers the
     * transient phase to READY_FOR_PLAYERS before this method can run.
     */
    private void tickBossCinematic() {
        if (phase != EventPhase.BOSS_CINEMATIC || liveBoss() != null) {
            return;
        }
        if (bossSpawnTask == null) {
            scheduleOfficialBossSpawn();
        }
    }

    private void tickWaveCompletion() {
        int completedWave = activeWave;
        if (!tickWaveObjective()) {
            return;
        }
        // Wave 4 is an obelisk assault. Pressure mobs are cleanup-only; the
        // objective is the physical obelisk set, not a second kill-all gate.
        if (completedWave == 4) {
            clearWaveCombatEntities("current-wave-4-obelisks-complete");
        }
        if (waveSpawnGroupIndex < waveSpawnSchedule.size()
                || completedWave != 4 && countLiveWaveEntitiesForWave(completedWave) > 0) {
            return;
        }
        if (!spawnWaveCompletionLoot(completedWave)) {
            return;
        }
        announceWaveComplete(completedWave);
        clearWaveObjectiveState();
        getLogger().info("END_RIFT_WAVE_COMPLETED event=" + eventId + " wave=" + completedWave
                + " objective=" + EndRiftObjective.objective(completedWave));
        if (completedWave == 7) {
            activeWave = 0;
            if (!transition(EventPhase.PRE_BOSS_COOLDOWN,
                    "Current Wave 7 defeated; pre-boss cooldown", eventId + ":current:pre-boss")) {
                forcePhase(EventPhase.RECOVERY_REQUIRED, "Current pre-boss transition failed");
                return;
            }
            phaseDeadlineMillis = System.currentTimeMillis()
                    + EndRiftObjective.PRE_BOSS_SECONDS * 1_000L;
            announceEventTitle("§5ПЕРЕД ПОСЛЕДНЕЙ ПЕЧАТЬЮ",
                    "§fДвадцать секунд тишины перед пробуждением Хранителя", true);
            saveStateAsync();
            return;
        }
        if (completedWave == 4) {
            activeWave = 0;
            if (!transition(EventPhase.CORE_RESTORATION,
                    "Wave 4 obelisk assault cleared; core restoration",
                    eventId + ":core-restoration")) {
                forcePhase(EventPhase.RECOVERY_REQUIRED, "Core restoration transition failed");
                return;
            }
            phaseDeadlineMillis = System.currentTimeMillis() + 6_000L;
            getLogger().info("END_RIFT_CORE_RESTORATION_STARTED event=" + eventId
                    + " generation=" + generation + " duration_ms=6000 next_wave=5");
            announceEventTitle("§bЯДРО ВОССТАНАВЛИВАЕТСЯ",
                    "§fРазлом собирает силы для внешнего рубежа", true);
            saveStateAsync();
            return;
        }
        if (completedWave == 5) {
            activeWave = 0;
            if (!transition(EventPhase.INTERMISSION_5,
                    "Wave 5 black fog cleared; transition runes",
                    eventId + ":intermission:5")) {
                forcePhase(EventPhase.RECOVERY_REQUIRED, "Wave 5 intermission transition failed");
                return;
            }
            if (!prepareTransitionRunes(5)) {
                forcePhase(EventPhase.RECOVERY_REQUIRED, "Wave 5 transition rune setup failed");
                return;
            }
            announceEventTitle("§5ПЕРЕХОД РАЗЛОМА",
                    "§fЗаймите все руны и удерживайте их пять секунд", true);
            saveStateAsync();
            return;
        }
        int nextIntermissionWave = completedWave;
        EventPhase intermission = switch (nextIntermissionWave) {
            case 1 -> EventPhase.INTERMISSION_1;
            case 2 -> EventPhase.INTERMISSION_2;
            case 3 -> EventPhase.INTERMISSION_3;
            case 6 -> EventPhase.INTERMISSION_6;
            default -> null;
        };
        if (intermission == null || !transition(intermission,
                "Current wave defeated; transition runes", eventId + ":current:intermission:" + completedWave)) {
            forcePhase(EventPhase.RECOVERY_REQUIRED, "Current intermission transition failed");
            return;
        }
        if (!prepareTransitionRunes(completedWave)) {
            forcePhase(EventPhase.RECOVERY_REQUIRED, "Current transition rune setup failed");
            return;
        }
        announceEventTitle("§5ПЕРЕХОД РАЗЛОМА",
                "§fЗаймите все руны и удерживайте их пять секунд", true);
        saveStateAsync();
    }

    private void tickCoreRestoration() {
        if (!isOfficialCurrentAttempt() || phase != EventPhase.CORE_RESTORATION) {
            return;
        }
        long now = System.currentTimeMillis();
        Location core = coreCombatAnchorLocation();
        if (core != null && now / 250L != (now - 50L) / 250L) {
            spawnEventParticle(core.clone().add(0.0D, 1.0D, 0.0D), Particle.END_ROD,
                    8, 0.7D, 1.0D, 0.7D, 0.02D);
            renderCoreRestorationRing(core, now);
        }
        if (phaseDeadlineMillis <= 0L) {
            phaseDeadlineMillis = now + 6_000L;
            getLogger().info("END_RIFT_CORE_RESTORATION_STARTED event=" + eventId
                    + " generation=" + generation + " duration_ms=6000 next_wave=5");
            return;
        }
        if (now < phaseDeadlineMillis) {
            return;
        }
        phaseDeadlineMillis = 0L;
        if (!transition(EventPhase.WAVE_5,
                "Current core restoration complete; Black Fog begins",
                eventId + ":current:wave:5")) {
            forcePhase(EventPhase.RECOVERY_REQUIRED, "Current Wave 5 transition failed");
            return;
        }
        getLogger().info("END_RIFT_CORE_RESTORATION_COMPLETED event=" + eventId
                + " generation=" + generation + " next_wave=5");
        World currentWorld = Bukkit.getWorld(worldName);
        Location currentCore = coreCombatAnchorLocation();
        if (currentWorld == null || currentCore == null) {
            forcePhase(EventPhase.RECOVERY_REQUIRED, "Current Wave 5 world/core unavailable");
            return;
        }
        spawnWaveForObjective(5, currentWorld, currentCore);
        saveStateAsync();
    }

    private void renderCoreRestorationRing(Location core, long now) {
        for (Player viewer : eventAudience()) {
            if (isEventParticleViewer(viewer, core)) {
                spawnPatternRing(viewer, core.clone().add(0.0D, 0.08D, 0.0D),
                        new Vector(1.0D, 0.0D, 0.0D), new Vector(0.0D, 0.0D, 1.0D),
                        2.0D + Math.sin(now * 0.004D) * 0.3D, 24, now * 0.003D,
                        Particle.END_ROD);
            }
        }
    }

    /**
     * Drops the guaranteed reward bundle physically on the Core after a wave.
     * The wave number is committed after the item entities are created, while
     * the persistent item tags make a retry after a process interruption
     * discover an already-created bundle instead of duplicating it.
     */
    private boolean spawnWaveCompletionLoot(int wave) {
        if (waveRewardsIssued.contains(wave)) {
            return true;
        }
        World world = Bukkit.getWorld(worldName);
        Location drop = coreLocation();
        Map<String, Integer> configured = config.waveReward(wave);
        List<UUID> recipients = new ArrayList<>(officialRewardRoster);
        if (world == null || drop == null || configured.isEmpty() || recipients.isEmpty()) {
            getLogger().severe("WAVE_REWARD_FAILED event=" + eventId + " wave=" + wave
                    + " reason=missing-world-core-config-or-roster");
            return false;
        }

        List<Item> spawned = new ArrayList<>();
        long ownerExpiresAt = System.currentTimeMillis() + WAVE_REWARD_OWNER_WINDOW_MILLIS;
        Material sharedRare = sharedRareMaterial(wave);
        boolean sharedRareAwarded = sharedRare != null
                && WaveRewardPolicy.sharedRareRoll(eventId, wave,
                config.waveRewardSharedRareChance(wave));
        try {
            for (int recipientIndex = 0; recipientIndex < recipients.size(); recipientIndex++) {
                UUID recipient = recipients.get(recipientIndex);
                WaveRewardPolicy.RewardBundle bundle = WaveRewardPolicy.bundle(
                        wave, recipientIndex, recipients.size(), configured);
                int materialIndex = 0;
                for (WaveRewardPolicy.RewardStack stack : bundle.stacks()) {
                    Material material = Material.matchMaterial(stack.material());
                    int amount = stack.amount();
                    if (material == null || amount < 1
                            || hasExistingWaveReward(world, wave, recipient, material, amount)) {
                        materialIndex++;
                        continue;
                    }
                    double angle = (recipientIndex * 2.399963229728653D + materialIndex * 0.37D)
                            % (Math.PI * 2.0D);
                    Location itemDrop = drop.clone().add(Math.cos(angle) * 0.35D, 0.15D,
                            Math.sin(angle) * 0.35D);
                    Item item = world.dropItem(itemDrop, rewardItemStack(material, amount, recipient));
                    // Paper's player-pickup flag is represented by pickupDelay.  Set it
                    // before restoring the short presentation delay, otherwise
                    // setCanPlayerPickup(true) silently changes the delay to zero.
                    item.setCanPlayerPickup(true);
                    item.setCanMobPickup(false);
                    item.setPickupDelay(20);
                    item.setVelocity(new Vector(0.0D, 0.18D, 0.0D));
                    tag(item, EVENT_KIND_WAVE_REWARD, wave, true);
                    tagWaveReward(item, recipient, ownerExpiresAt, false, amount);
                    setLootProfile(item, "wave-reward");
                    spawned.add(item);
                    materialIndex++;
                }
            }
            int sharedRareAmount = wave >= 5 ? 2 : 1;
            if (sharedRareAwarded && !hasExistingSharedWaveReward(world, wave)) {
                Item item = world.dropItem(drop.clone().add(0.0D, 0.15D, 0.0D),
                        new ItemStack(sharedRare, sharedRareAmount));
                item.setCanPlayerPickup(true);
                item.setCanMobPickup(false);
                item.setPickupDelay(20);
                item.setVelocity(new Vector(0.0D, 0.28D, 0.0D));
                tag(item, EVENT_KIND_WAVE_REWARD, wave, true);
                tagWaveReward(item, null, 0L, true, sharedRareAmount);
                setLootProfile(item, "wave-reward-shared-rare");
                spawned.add(item);
            }
            if (!allWaveRewardItemsPresent(world, wave, recipients, configured)
                    || sharedRareAwarded && !hasExistingSharedWaveReward(world, wave)) {
                getLogger().severe("WAVE_REWARD_FAILED event=" + eventId + " wave=" + wave
                        + " reason=recipient-bundles-not-materialized");
                return false;
            }
            waveRewardsIssued.add(wave);
            if (!saveStateSync()) {
                waveRewardsIssued.remove(wave);
                for (Item item : spawned) {
                    ownedEntities.remove(item.getUniqueId());
                    if (item.isValid()) {
                        item.remove();
                    }
                }
                getLogger().severe("WAVE_REWARD_FAILED event=" + eventId + " wave=" + wave
                        + " reason=state-commit-failed");
                return false;
            }
        } catch (RuntimeException error) {
            waveRewardsIssued.remove(wave);
            for (Item item : spawned) {
                ownedEntities.remove(item.getUniqueId());
                if (item.isValid()) {
                    item.remove();
                }
            }
            getLogger().log(Level.SEVERE, "WAVE_REWARD_FAILED event=" + eventId + " wave=" + wave,
                    error);
            return false;
        }

        spawnEventParticle(drop.clone().add(0.0D, 0.6D, 0.0D), Particle.TOTEM_OF_UNDYING,
                32, 0.55D, 0.45D, 0.55D, 0.05D);
        spawnEventParticle(drop.clone().add(0.0D, 0.8D, 0.0D), Particle.END_ROD,
                20, 0.35D, 0.35D, 0.35D, 0.03D);
        world.playSound(drop, Sound.ENTITY_PLAYER_LEVELUP, 0.85F, 1.15F);
        getLogger().info("WAVE_REWARD_SPAWNED event=" + eventId + " wave=" + wave
                + " location=" + locationText(drop) + " recipients=" + recipients.size()
                + " owner_window_ms=" + WAVE_REWARD_OWNER_WINDOW_MILLIS
                + " shared_rare_awarded=" + sharedRareAwarded
                + " shared_rare_key=end-event:" + eventId + ":wave:" + wave + ":shared-rare");
        return true;
    }

    private void tagWaveReward(Item item, UUID owner, long expiresAt, boolean shared) {
        tagWaveReward(item, owner, expiresAt, shared,
                item == null || item.getItemStack() == null ? 0 : item.getItemStack().getAmount());
    }

    /**
     * Keep personal physical rewards separate while they are on the floor.
     * Bukkit's Item entity merge compares ItemStack components, not the PDC
     * stored on the entity. Without this hidden owner component, two equal
     * bundles can merge and the surviving entity would retain only one
     * recipient's pickup authorization.
     */
    private ItemStack rewardItemStack(Material material, int amount, UUID owner) {
        ItemStack stack = new ItemStack(material, amount);
        if (owner == null || keyRewardStackOwner == null) {
            return stack;
        }
        ItemMeta meta = stack.getItemMeta();
        if (meta == null) {
            return stack;
        }
        meta.getPersistentDataContainer().set(keyRewardStackOwner,
                PersistentDataType.STRING, owner.toString());
        stack.setItemMeta(meta);
        return stack;
    }

    private void tagWaveReward(Item item, UUID owner, long expiresAt, boolean shared, int expectedAmount) {
        if (item == null) {
            return;
        }
        PersistentDataContainer data = item.getPersistentDataContainer();
        data.set(keyRewardShared, PersistentDataType.BYTE, shared ? (byte) 1 : (byte) 0);
        data.set(keyRewardExpiresAt, PersistentDataType.LONG, Math.max(0L, expiresAt));
        data.set(keyRewardAmount, PersistentDataType.INTEGER, Math.max(0, expectedAmount));
        if (owner == null) {
            data.remove(keyRewardOwner);
        } else {
            data.set(keyRewardOwner, PersistentDataType.STRING, owner.toString());
        }
    }

    private boolean hasExistingWaveReward(World world, int wave, UUID owner, Material material, int expectedAmount) {
        if (world == null || eventId.isBlank() || owner == null || material == null || expectedAmount < 1) {
            return false;
        }
        return world.getEntitiesByClass(Item.class).stream()
                .anyMatch(item -> item.isValid()
                        && EVENT_KIND_WAVE_REWARD.equals(readString(item, keyKind))
                        && wave == readInt(item, keyWave, 0)
                        && ownedByEvent(item, eventId)
                        && owner.toString().equals(item.getPersistentDataContainer()
                        .getOrDefault(keyRewardOwner, PersistentDataType.STRING, ""))
                        && item.getItemStack().getType() == material
                        && item.getPersistentDataContainer().getOrDefault(
                        keyRewardAmount, PersistentDataType.INTEGER, item.getItemStack().getAmount())
                        >= expectedAmount
                        && item.getPersistentDataContainer().getOrDefault(
                        keyRewardShared, PersistentDataType.BYTE, (byte) 0) == (byte) 0);
    }

    private boolean hasExistingSharedWaveReward(World world, int wave) {
        if (world == null || eventId.isBlank()) {
            return false;
        }
        return world.getEntitiesByClass(Item.class).stream()
                .anyMatch(item -> item.isValid()
                        && EVENT_KIND_WAVE_REWARD.equals(readString(item, keyKind))
                        && wave == readInt(item, keyWave, 0)
                        && ownedByEvent(item, eventId)
                        && item.getPersistentDataContainer().getOrDefault(
                        keyRewardShared, PersistentDataType.BYTE, (byte) 0) == (byte) 1);
    }

    private boolean allWaveRewardItemsPresent(World world, int wave, List<UUID> recipients,
                                              Map<String, Integer> configured) {
        if (world == null || recipients == null || recipients.isEmpty() || configured == null
                || configured.isEmpty()) {
            return false;
        }
        for (UUID recipient : recipients) {
            int recipientIndex = recipients.indexOf(recipient);
            WaveRewardPolicy.RewardBundle bundle = WaveRewardPolicy.bundle(
                    wave, recipientIndex, recipients.size(), configured);
            for (WaveRewardPolicy.RewardStack stack : bundle.stacks()) {
                Material material = Material.matchMaterial(stack.material());
                if (material != null && !hasExistingWaveReward(world, wave, recipient, material, stack.amount())) {
                    return false;
                }
            }
        }
        return true;
    }

    private Material sharedRareMaterial(int wave) {
        // One shared physical rare drop is separate from each participant's
        // bundle and is guarded by its own idempotency key.  Early waves stay
        // personal; the team roll begins with the Wave 4 shared reward.
        return wave >= 4 && wave <= WaveRewardPolicy.MAX_SUPPORTED_WAVE
                ? Material.NETHERITE_SCRAP : null;
    }

    /** Start one canonical numbered wave, or a local disposable visual probe. */
    private void spawnWave(int wave, boolean test) {
        World world = Bukkit.getWorld(worldName);
        Location core = coreLocation();
        if (world == null || core == null || !EndRiftObjective.isNumberedWave(wave)) {
            getLogger().warning("WAVE_SPAWN_REFUSED event=" + eventId + " wave=" + wave
                    + " reason=invalid-world-core-or-wave");
            return;
        }
        if (!test) {
            if (!isOfficialAttempt()) {
                getLogger().warning("WAVE_SPAWN_REFUSED event=" + eventId + " wave=" + wave
                        + " reason=no-official-roster");
                return;
            }
            spawnWaveForObjective(wave, world, core);
            return;
        }
        EventConfig.WaveDefinition definition = switch (wave) {
            case 1 -> config.wave1();
            case 2 -> config.wave2();
            case 3 -> config.wave3();
            case 4 -> config.wave4();
            case 5 -> config.wave5();
            case 6 -> config.wave6();
            case 7 -> config.wave7();
            default -> null;
        };
        if (definition == null) {
            return;
        }
        clearWaveObjectiveState();
        WaveMechanicsPolicy.WaveCounts configured = new WaveMechanicsPolicy.WaveCounts(
                definition.endermen(), definition.spiders(), definition.skeletons(),
                definition.eliteEndermen(), definition.eliteSkeletons());
        WaveMechanicsPolicy.WaveCounts scaled = WaveScalingPolicy.scale(
                configured, Math.max(2, eventScalePlayers()),
                Math.min(Math.max(1, config.waveHardCap()), PressureBudgetController.HARD_CAP));
        if (diagnosticsFailureInjection) {
            // This probe must exercise the same diagnostics boundary without
            // mutating the user's current map or official roster.  Record the
            // failure as a real transition transaction and return before any
            // visual/entity/task mutation begins.
            if (diagnostics != null) {
                diagnostics.recordWaveTransitionStarted(eventId, generation,
                        Math.max(0, wave - 1), wave, scaled.total(),
                        activeEventTaskCount(), "local diagnostics failure probe");
                RuntimeException failure = new IllegalStateException(
                        "local diagnostics failure probe");
                diagnostics.recordWaveTransitionFailed(eventId, generation, wave,
                        activeEventTaskCount(), failure);
                getLogger().log(Level.WARNING, "WAVE_DIAGNOSTICS_FAILURE_INJECTED event="
                        + eventId + " wave=" + wave, failure);
            }
            return;
        }
        activeWave = wave;
        waveSpawnWave = wave;
        waveSpawnGroupIndex = 1;
        waveSpawnEntityOffset = 0;
        waveSpawnSchedule = List.of(scaled);
        // Keep the disposable probe on the same visual path as an official
        // wave.  The flags are cleared by clearWaveObjectiveState(), so this
        // cannot keep a test animation alive after /cmend wave clear.
        testWaveFrontVisualMode = true;
        testPortalVisualMode = wave == 3;
        spawnWaveArrivalEffect(world, core, wave, false);
        startWaveFrontAnimation(world, core, wave, false);
        startWaveObjective(wave, world, core);
        if (wave == 4) {
            testWave4ObeliskMode = true;
            currentWaveScalePlayers = Math.max(2, eventScalePlayers());
            startWave4ObeliskAssault(world, core, currentWaveScalePlayers);
        } else {
            spawnWaveGroup(world, core, wave, wave == MAX_EVENT_WAVE, true, scaled, 0);
        }
        getLogger().info("WAVE_TEST_STARTED event=" + eventId + " wave=" + wave
                + " planned=" + scaled.total());
    }

    /**
     * Official numbered-wave entry point with a durable transition trace.
     *
     * Wave creation is one of the few places where a scheduler exception can
     * otherwise look like a silent stop: the state transition has already
     * committed, but the first spawn/visual callback has not.  Keep the
     * diagnostics transaction around the existing production entry point so
     * every current wave, including Wave 7, reports STARTED, COMMITTED or
     * FAILED without introducing a second gameplay path.
     */
    private void spawnWaveForObjective(int wave, World world, Location core) {
        if (world == null || core == null || !EndRiftObjective.isNumberedWave(wave)
                || !isOfficialCurrentAttempt()) {
            spawnWaveForObjectiveInternal(wave, world, core);
            return;
        }
        int plannedMobs = plannedWaveCountForDiagnostics(wave);
        if (diagnostics != null) {
            diagnostics.recordWaveTransitionStarted(eventId, generation,
                    Math.max(0, wave - 1), wave, plannedMobs,
                    activeEventTaskCount(), "canonical-wave-spawn");
        }
        try {
            spawnWaveForObjectiveInternal(wave, world, core);
            if (diagnostics != null) {
                diagnostics.recordWaveTransitionCommitted(eventId, generation, wave,
                        plannedMobs, activeEventTaskCount());
            }
        } catch (RuntimeException error) {
            if (diagnostics != null) {
                diagnostics.recordWaveTransitionFailed(eventId, generation, wave,
                        activeEventTaskCount(), error);
            }
            throw error;
        }
    }

    /** Pure/config-only estimate used only in the transition journal. */
    private int plannedWaveCountForDiagnostics(int wave) {
        if (config == null || !EndRiftObjective.isNumberedWave(wave)) {
            return 0;
        }
        EventConfig.WaveDefinition definition = switch (wave) {
            case 1 -> config.wave1();
            case 2 -> config.wave2();
            case 3 -> config.wave3();
            case 4 -> config.wave4();
            case 5 -> config.wave5();
            case 6 -> config.wave6();
            case 7 -> config.wave7();
            default -> null;
        };
        if (definition == null) {
            return 0;
        }
        int players = eventScalePlayers();
        WaveMechanicsPolicy.WaveCounts scaled;
        if (wave == 4) {
            scaled = currentWave4MobCounts(players);
        } else {
            WaveMechanicsPolicy.WaveCounts configured = new WaveMechanicsPolicy.WaveCounts(
                    definition.endermen(), definition.spiders(), definition.skeletons(),
                    definition.eliteEndermen(), definition.eliteSkeletons());
            int hardCap = Math.min(Math.max(1, config.waveHardCap()),
                    PressureBudgetController.HARD_CAP);
            scaled = WaveMechanicsPolicy.clampToPressure(
                    WaveScalingPolicy.scale(configured, players, hardCap), players);
        }
        return Math.max(0, scaled.total());
    }

    /** Internal implementation kept free of diagnostics bookkeeping. */
    private void spawnWaveForObjectiveInternal(int wave, World world, Location core) {
        if (world == null || core == null || !EndRiftObjective.isNumberedWave(wave)
                || !isOfficialCurrentAttempt()) {
            getLogger().warning("END_RIFT_WAVE_SPAWN_REFUSED event=" + eventId + " wave=" + wave
                    + " reason=invalid-official-context");
            return;
        }
        clearWaveObjectiveState();
        EventConfig.WaveDefinition definition = switch (wave) {
            case 1 -> config.wave1();
            case 2 -> config.wave2();
            case 3 -> config.wave3();
            case 4 -> config.wave4();
            case 5 -> config.wave5();
            case 6 -> config.wave6();
            case 7 -> config.wave7();
            default -> null;
        };
        if (definition == null) {
            throw new IllegalStateException("missing Current wave definition " + wave);
        }
        int players = eventScalePlayers();
        currentWaveScalePlayers = players;
        activeWave = wave;
        waveSpawnWave = wave;
        waveSpawnGroupIndex = 0;
        waveSpawnEntityOffset = 0;
        waveNextSpawnAtMillis = 0L;
        WaveMechanicsPolicy.WaveCounts scaled;
        if (wave == 4) {
            scaled = currentWave4MobCounts(players);
            currentWave4MobsStarted = false;
            currentWave4StartupFailed = false;
            // Wave 4 owns one bounded pressure pack.  The old tower scheduler
            // could split this profile into delayed groups and make the
            // obelisk objective wait on mobs that were never part of the Current
            // assault contract.
            waveSpawnSchedule = List.of(scaled);
        } else {
            WaveMechanicsPolicy.WaveCounts configured = new WaveMechanicsPolicy.WaveCounts(
                    definition.endermen(), definition.spiders(), definition.skeletons(),
                    definition.eliteEndermen(), definition.eliteSkeletons());
            int hardCap = Math.min(Math.max(1, config.waveHardCap()),
                    PressureBudgetController.HARD_CAP);
            scaled = WaveScalingPolicy.scale(configured, players, hardCap);
            scaled = WaveMechanicsPolicy.clampToPressure(scaled, players);
            waveSpawnSchedule = List.of(scaled);
        }
        if (waveSpawnSchedule.isEmpty()) {
            throw new IllegalStateException("Current wave has no bounded spawn groups");
        }
        if (wave == 7) {
            realitySplitChamberController.begin(generation, new ArrayList<>(officialRewardRoster));
            teleportCurrentParticipantsToChambers(world, core);
        }
        playEventMusic(config.phaseMusic("wave-" + wave));
        announceEventTitle("§dВОЛНА " + wave, "§f" + EndRiftObjective.title(wave), true);
        spawnWaveArrivalEffect(world, core, wave, false);
        startWaveFrontAnimation(world, core, wave, false);
        startWaveObjective(wave, world, core);
        if (wave != 4) {
            spawnNextWaveGroup(world, core);
            scheduleWaveGroups(world, core);
        } else {
            startWave4ObeliskAssault(world, core, players);
        }
        getLogger().info("END_RIFT_WAVE_STARTED event=" + eventId + " generation=" + generation
                + " wave=" + wave + " objective=" + EndRiftObjective.objective(wave)
                + " players=" + players + " planned_mobs=" + scaled.total()
                + " groups=" + waveSpawnSchedule.size()
                + " obelisks=" + ObeliskScalingPolicy.obeliskCount(players));
    }

    private WaveMechanicsPolicy.WaveCounts currentWave4MobCounts(int players) {
        int stalkers;
        int brutes;
        int channelers;
        if (players <= 4) {
            stalkers = 2;
            brutes = 1;
            channelers = 0;
        } else if (players <= 7) {
            stalkers = 3;
            brutes = 1;
            channelers = 0;
        } else if (players <= 10) {
            stalkers = 3;
            brutes = 1;
            channelers = 1;
        } else if (players <= 15) {
            stalkers = 4;
            brutes = 1;
            channelers = 1;
        } else {
            stalkers = 5;
            brutes = 2;
            channelers = 1;
        }
        return new WaveMechanicsPolicy.WaveCounts(brutes, stalkers, channelers, 0, 0);
    }

    /**
     * Show a readable wave front for every official wave, including wave one.
     * The effect is a short, bounded animation: a custom transparent floor
     * ring grows from the Core while viewer-scoped particles draw the moving
     * edge, spokes and inner echo.  It never replaces a player block.
     */
    private void startWaveFrontAnimation(World world, Location core, int wave, boolean guardianWave) {
        cancelWaveFrontAnimation();
        Location anchor = coreCombatAnchorLocation();
        if (world == null || core == null || anchor == null || taskRegistry == null) {
            getLogger().warning("WAVE_FRONT_REFUSED event=" + eventId
                    + " wave=" + wave + " reason=missing-floor-anchor-or-task-registry");
            return;
        }
        waveFrontWave = Math.max(1, Math.min(MAX_EVENT_WAVE, wave));
        waveFrontGuardian = guardianWave;
        waveFrontElapsedTicks = 0;
        WaveVisualPolicy.Frame firstFrame = WaveVisualPolicy.frame(
                EndRiftObjective.objective(waveFrontWave), waveFrontElapsedTicks, false);
        ItemDisplay texture = spawnWaveFrontTexture(world, anchor, firstFrame);
        waveFrontTextureUuid = texture == null ? null : texture.getUniqueId();
        long callbackGeneration = generation;
        getLogger().info("WAVE_FRONT_STARTED event=" + eventId
                + " generation=" + callbackGeneration + " wave=" + waveFrontWave
                + " guardian=" + guardianWave + " radius=" + firstFrame.outerRadius()
                + " floor_y=" + combatFloorY());
        waveFrontVisualTask = Bukkit.getScheduler().runTaskTimer(this, () -> {
            if (taskRegistry == null || !taskRegistry.owns(callbackGeneration)
                    || !isCombatPhase() && !testCombatAiMode && !testWaveFrontVisualMode) {
                cancelWaveFrontAnimation();
                return;
            }
            if (!tickWaveFrontAnimation(world, callbackGeneration)) {
                BukkitTask finished = waveFrontVisualTask;
                waveFrontVisualTask = null;
                if (finished != null) {
                    finished.cancel();
                }
            }
        }, 0L, 5L);
        registerEncounterTask(waveFrontVisualTask);
    }

    private boolean tickWaveFrontAnimation(World world, long callbackGeneration) {
        if (world == null || taskRegistry == null || !taskRegistry.owns(callbackGeneration)) {
            return false;
        }
        Location anchor = coreCombatAnchorLocation();
        if (anchor == null || !world.equals(anchor.getWorld())) {
            return false;
        }
        WaveVisualPolicy.Frame frame = WaveVisualPolicy.frame(
                EndRiftObjective.objective(waveFrontWave), waveFrontElapsedTicks, false);
        renderWaveFrontFrame(anchor, frame);
        // A frame is emitted every five ticks; keep it available at FINE so
        // normal server logs contain state transitions, not animation spam.
        getLogger().fine("WAVE_FRONT_FRAME event=" + eventId
                + " generation=" + callbackGeneration + " wave=" + frame.wave()
                + " elapsed_ticks=" + frame.elapsedTicks()
                + " radius=" + String.format(Locale.ROOT, "%.2f", frame.outerRadius())
                + " points=" + frame.outerPoints());
        if (!WaveVisualPolicy.active(waveFrontElapsedTicks)) {
            getLogger().info("WAVE_FRONT_COMPLETED event=" + eventId
                    + " generation=" + callbackGeneration + " wave=" + frame.wave());
            world.playSound(anchor, waveFrontGuardian ? Sound.ENTITY_ENDER_DRAGON_GROWL
                    : Sound.BLOCK_BEACON_POWER_SELECT, waveFrontGuardian ? 0.8F : 0.55F,
                    waveFrontGuardian ? 0.55F : 1.35F);
            UUID completedTexture = waveFrontTextureUuid;
            BukkitTask cleanup = Bukkit.getScheduler().runTaskLater(this, () -> {
                if (Objects.equals(waveFrontTextureUuid, completedTexture)) {
                    cancelWaveFrontAnimation();
                }
            }, 10L);
            if (taskRegistry != null) {
                registerEncounterTask(cleanup);
            }
            return false;
        }
        waveFrontElapsedTicks += 5;
        return true;
    }

    private void renderWaveFrontFrame(Location anchor, WaveVisualPolicy.Frame frame) {
        if (anchor == null || anchor.getWorld() == null || frame == null) {
            return;
        }
        ItemDisplay texture = waveFrontTextureUuid == null ? null
                : ownedEntities.get(waveFrontTextureUuid) instanceof ItemDisplay display ? display : null;
        if (texture != null && texture.isValid()) {
            applyWaveFrontTextureFrame(texture, anchor, frame);
        }
        Location floor = anchor.clone();
        // combatFloorY() is the solid block's integer Y.  The visual must be
        // placed above that block, on the same surface where rune overlays
        // and player feet are rendered; using the raw floor Y puts the ring
        // inside the arena and makes it look missing.
        floor.setY(combatFloorY() + 1.0D + frame.floorY());
        Particle edgeParticle = waveFrontGuardian ? Particle.DRAGON_BREATH
                : switch (Math.floorMod(frame.wave() - 1, 5)) {
                    case 0 -> Particle.END_ROD;
                    case 1 -> Particle.REVERSE_PORTAL;
                    case 2 -> Particle.ELECTRIC_SPARK;
                    case 3 -> Particle.SOUL_FIRE_FLAME;
                    default -> Particle.FLAME;
                };
        Particle innerParticle = waveFrontGuardian ? Particle.REVERSE_PORTAL
                : frame.wave() % 2 == 0 ? Particle.END_ROD : Particle.CRIT;
        Color color = waveFrontGuardian ? Color.fromRGB(244, 39, 125)
                : switch (Math.floorMod(frame.wave() - 1, 5)) {
                    case 0 -> Color.fromRGB(69, 218, 255);
                    case 1 -> Color.fromRGB(190, 76, 255);
                    case 2 -> Color.fromRGB(255, 126, 48);
                    case 3 -> Color.fromRGB(93, 255, 189);
                    default -> Color.fromRGB(255, 226, 96);
                };
        Particle.DustOptions dust = new Particle.DustOptions(color,
                (float) (1.0D + frame.radialEnergy() * 0.65D));
        Vector x = new Vector(1.0D, 0.0D, 0.0D);
        Vector z = new Vector(0.0D, 0.0D, 1.0D);
        double spin = System.currentTimeMillis() * 0.0018D + frame.wave() * 0.37D;
        int outerPoints = Math.min(WAVE_FRONT_PARTICLE_MAX_POINTS, frame.outerPoints());
        int innerPoints = Math.min(36, frame.innerPoints());
        for (Player player : eventAudience()) {
            if (!isEventParticleViewer(player, floor)) {
                continue;
            }
            spawnPatternRing(player, floor, x, z, frame.outerRadius(),
                    outerPoints, spin, edgeParticle);
            spawnPatternRing(player, floor.clone().add(0.0D, 0.05D, 0.0D), x, z,
                    frame.innerRadius(), innerPoints, -spin * 1.25D, innerParticle);
            int spokes = Math.min(12, Math.max(6, outerPoints / 8));
            for (int spoke = 0; spoke < spokes; spoke++) {
                double angle = spin + Math.PI * 2.0D * spoke / spokes;
                Location start = floor.clone().add(Math.cos(angle) * frame.innerRadius(),
                        0.02D + frame.pulseHeight() * 0.25D, Math.sin(angle) * frame.innerRadius());
                Location end = floor.clone().add(Math.cos(angle) * frame.outerRadius(),
                        0.02D + frame.pulseHeight(), Math.sin(angle) * frame.outerRadius());
                spawnPatternSegment(player, start, end, edgeParticle, dust);
            }
            player.spawnParticle(Particle.DUST, floor.clone().add(0.0D, 0.04D, 0.0D),
                    Math.min(12, 4 + frame.wave()), 0.35D, 0.02D, 0.35D, 0.0D, dust);
            if (frame.completed()) {
                player.spawnParticle(Particle.END_ROD, floor.clone().add(0.0D, 0.25D, 0.0D),
                        18, 0.8D, 0.12D, 0.8D, 0.04D);
            }
        }
    }

    private ItemDisplay spawnWaveFrontTexture(World world, Location anchor,
                                               WaveVisualPolicy.Frame frame) {
        if (world == null || anchor == null || frame == null) {
            return null;
        }
        double radius = Math.max(0.5D, Math.min(WaveVisualPolicy.MAX_RADIUS_BLOCKS,
                frame.outerRadius()));
        Location origin = anchor.clone().add(-radius, 0.0D, -radius);
        origin.setY(combatFloorY() + 1.0D + frame.floorY());
        ItemDisplay display = world.spawn(origin, ItemDisplay.class, entity -> {
            entity.setItemStack(overlayItem(MODEL_WAVE_FRONT_OVERLAY, "end_event_wave_ring"));
            entity.setBrightness(new Display.Brightness(15, 15));
            entity.setItemDisplayTransform(ItemDisplay.ItemDisplayTransform.NONE);
            entity.setBillboard(Display.Billboard.FIXED);
            entity.setViewRange(48.0F);
            entity.setDisplayWidth((float) (radius * 2.0D));
            entity.setDisplayHeight(0.16F);
            entity.setPersistent(false);
            entity.setGravity(false);
            entity.setInvulnerable(true);
            entity.setShadowRadius(0.0F);
        });
        tag(display, EVENT_KIND_DISPLAY, frame.wave(), false);
        waveFrontVisuals.add(display.getUniqueId());
        applyWaveFrontTextureFrame(display, anchor, frame);
        return display;
    }

    private void applyWaveFrontTextureFrame(ItemDisplay display, Location anchor,
                                             WaveVisualPolicy.Frame frame) {
        if (display == null || anchor == null || frame == null || !display.isValid()) {
            return;
        }
        double radius = Math.max(0.5D, Math.min(WaveVisualPolicy.MAX_RADIUS_BLOCKS,
                frame.outerRadius()));
        Location origin = anchor.clone().add(-radius, 0.0D, -radius);
        origin.setY(combatFloorY() + 1.0D + frame.floorY());
        display.teleport(origin);
        float diameter = (float) Math.max(1.0D, radius * 2.0D);
        display.setDisplayWidth(diameter);
        display.setDisplayHeight(0.16F);
        display.setTransformation(new Transformation(
                new Vector3f(), new AxisAngle4f(),
                new Vector3f(diameter, 0.035F, diameter), new AxisAngle4f()));
    }

    private void cancelWaveFrontAnimation() {
        if (waveFrontVisualTask != null) {
            waveFrontVisualTask.cancel();
            waveFrontVisualTask = null;
        }
        for (UUID visualId : new HashSet<>(waveFrontVisuals)) {
            Entity visual = ownedEntities.remove(visualId);
            if (visual != null && visual.isValid()) {
                visual.remove();
            }
        }
        waveFrontVisuals.clear();
        waveFrontTextureUuid = null;
        waveFrontElapsedTicks = 0;
        waveFrontWave = 0;
        waveFrontGuardian = false;
    }

    /** Spawn the next bounded group for the canonical numbered-wave flow. */
    private void spawnNextWaveGroup(World world, Location core) {
        if (world == null || core == null || waveSpawnGroupIndex >= waveSpawnSchedule.size()) {
            return;
        }
        WaveMechanicsPolicy.WaveCounts group = waveSpawnSchedule.get(waveSpawnGroupIndex);
        int groupNumber = waveSpawnGroupIndex + 1;
        spawnWaveGroup(world, core, waveSpawnWave, waveSpawnWave == MAX_EVENT_WAVE,
                false, group, waveSpawnEntityOffset);
        waveSpawnEntityOffset += group.total();
        waveSpawnGroupIndex++;
        waveNextSpawnAtMillis = waveSpawnGroupIndex < waveSpawnSchedule.size()
                ? System.currentTimeMillis() + 6_000L : 0L;
        getLogger().info("END_RIFT_WAVE_GROUP_SPAWN event=" + eventId
                + " wave=" + waveSpawnWave + " group=" + groupNumber + "/"
                + waveSpawnSchedule.size() + " spawned=" + group.total()
                + " next_ms=" + waveNextSpawnAtMillis);
    }

    /** Generation-fenced cadence for the canonical wave group scheduler. */
    private void scheduleWaveGroups(World world, Location core) {
        cancelWaveSpawnTask();
        if (world == null || core == null || waveSpawnGroupIndex >= waveSpawnSchedule.size()
                || taskRegistry == null) {
            return;
        }
        long callbackGeneration = generation;
        waveSpawnTask = Bukkit.getScheduler().runTaskTimer(this, () -> {
            if (taskRegistry == null || !taskRegistry.owns(callbackGeneration)
                    || activeWave != waveSpawnWave || phase != wavePhase(waveSpawnWave)) {
                cancelWaveSpawnTask();
                return;
            }
            if (waveNextSpawnAtMillis > 0L
                    && System.currentTimeMillis() >= waveNextSpawnAtMillis) {
                spawnNextWaveGroup(world, core);
                if (waveSpawnGroupIndex >= waveSpawnSchedule.size()) {
                    cancelWaveSpawnTask();
                }
            }
        }, 20L, 20L);
        registerEncounterTask(waveSpawnTask);
    }

    private void cancelWaveSpawnTask() {
        if (waveSpawnTask != null) {
            waveSpawnTask.cancel();
            waveSpawnTask = null;
        }
    }

    private void spawnWaveGroup(World world, Location core, int wave, boolean guardianWave, boolean test,
                                WaveMechanicsPolicy.WaveCounts group, int baseIndex) {
        if (world == null || core == null || group == null) {
            return;
        }
        int nextIndex = baseIndex;
        int portalPackSlot = 0;
        for (int index = 0; index < group.endermen(); index++) {
            portalPackSlot = tagWaveThreePusher(
                    spawnEnderman(world, core, wave, false, guardianWave, test, nextIndex, nextIndex),
                    wave, portalPackSlot);
            nextIndex++;
        }
        for (int index = 0; index < group.eliteEndermen(); index++) {
            portalPackSlot = tagWaveThreePusher(
                    spawnEnderman(world, core, wave, true, guardianWave, test, nextIndex, nextIndex),
                    wave, portalPackSlot);
            nextIndex++;
        }
        for (int index = 0; index < group.eliteSkeletons(); index++) {
            portalPackSlot = tagWaveThreePusher(
                    spawnSkeleton(world, core, wave, true, guardianWave, test, nextIndex, nextIndex),
                    wave, portalPackSlot);
            nextIndex++;
        }
        for (int index = 0; index < group.spiders(); index++) {
            portalPackSlot = tagWaveThreePusher(
                    spawnOwnedMob(world, core, EntityType.SPIDER, wave,
                            guardianWave ? EVENT_KIND_WAVE_GUARDIAN : EVENT_KIND_WAVE_MOB, test, nextIndex),
                    wave, portalPackSlot);
            nextIndex++;
        }
        for (int index = 0; index < group.skeletons(); index++) {
            portalPackSlot = tagWaveThreePusher(
                    spawnSkeleton(world, core, wave, false, guardianWave, test, nextIndex, nextIndex),
                    wave, portalPackSlot);
            nextIndex++;
        }
    }

    /**
     * Spawn the bounded Wave 4 pressure pack.  This is deliberately kept
     * separate from the Wave 4 pressure composition: the current roles are fixed by
     * the obelisk profile and are not allowed to create delayed duplicate
     * groups.
     */
    private void spawnWave4PressurePack(World world, Location core,
                                           ObeliskScalingPolicy.Profile profile,
                                           boolean test) {
        if (world == null || core == null || profile == null
                || profile.mobCount() <= 0 || countLiveWaveEntitiesForWave(4)
                >= profile.mobCount()) {
            return;
        }
        WaveMechanicsPolicy.WaveCounts composition = currentWave4MobCounts(currentWaveScalePlayers);
        int index = 0;
        int spawned = 0;
        for (int i = 0; i < composition.spiders(); i++) {
            String role = "STALKER";
            Entity entity = spawnOwnedMob(world, core, EntityType.SPIDER, 4,
                    EVENT_KIND_WAVE_MOB, test, index++);
            if (entity == null) {
                continue;
            }
            tagWave4Role(entity, role);
            if (entity instanceof LivingEntity living) {
                living.setCustomName(ChatColor.DARK_PURPLE + switch (role) {
                    case "STALKER" -> "Охотник Разлома";
                    case "BRUTE" -> "Брут Разлома";
                    default -> "Каналер Разлома";
                });
                living.setCustomNameVisible(true);
            }
            spawned++;
        }
        for (int i = 0; i < composition.endermen(); i++) {
            String role = "BRUTE";
            Entity entity = spawnEnderman(world, core, 4, true, false, test,
                    index++, index);
            if (entity == null) {
                continue;
            }
            tagWave4Role(entity, role);
            if (entity instanceof LivingEntity living) {
                living.setCustomName(ChatColor.DARK_PURPLE + "Брут Разлома");
                living.setCustomNameVisible(true);
            }
            spawned++;
        }
        for (int i = 0; i < composition.skeletons(); i++) {
            String role = "CHANNELER";
            Entity entity = spawnSkeleton(world, core, 4, true, false, test,
                    index++, index);
            if (entity == null) {
                continue;
            }
            tagWave4Role(entity, role);
            if (entity instanceof LivingEntity living) {
                living.setCustomName(ChatColor.DARK_PURPLE + "Каналер Разлома");
                living.setCustomNameVisible(true);
            }
            spawned++;
        }
        getLogger().info("END_RIFT_OBELISK_PRESSURE_PACK event=" + eventId
                + " generation=" + generation + " planned=" + profile.mobCount()
                + " spawned=" + spawned + " composition=stalker:" + composition.spiders()
                + ",brute:" + composition.endermen()
                + ",channeler:" + composition.skeletons());
    }

    private void tagWave4Role(Entity entity, String role) {
        if (entity == null || keyObeliskWave4Role == null || role == null || role.isBlank()) {
            return;
        }
        entity.getPersistentDataContainer().set(keyObeliskWave4Role,
                PersistentDataType.STRING, role.toUpperCase(Locale.ROOT));
    }

    private boolean isWave4ObeliskChannelerActive() {
        for (Entity entity : ownedEntities.values()) {
            if (entity == null || !isLiveOwnedEntity(entity.getUniqueId())
                    || !(entity instanceof LivingEntity living)
                    || readInt(entity, keyWave, 0) != 4
                    || !"CHANNELER".equalsIgnoreCase(readString(entity, keyObeliskWave4Role))
                    || living.isDead() || living.getHealth() <= 0.0D) {
                continue;
            }
            return true;
        }
        return false;
    }

    private int activeWave4FireballCount() {
        int count = 0;
        for (RiftFireballRuntimeState state : activeRiftFireballs.values()) {
            Entity entity = Bukkit.getEntity(state.entityId());
            if (entity != null && entity.isValid()
                    && EVENT_KIND_RIFT_FIREBALL.equals(readString(entity, keyKind))
                    && state.generation() == generation
                    && state.isWave4Obelisk()) {
                count++;
            }
        }
        return count;
    }

    private void renderWave4ChannelerBeams() {
        Set<String> desired = new LinkedHashSet<>();
        List<Wave4ObeliskRuntimeState> targets = activeWave4Obelisks.values().stream()
                .filter(state -> state.stage() == ObeliskStage.ACTIVE && state.health() > 0)
                .toList();
        if (targets.isEmpty()) {
            clearWorldVfxBeamsByPrefix("current-obelisk-channeler-");
            return;
        }
        int targetIndex = 0;
        for (Entity entity : new ArrayList<>(ownedEntities.values())) {
            if (!(entity instanceof LivingEntity living)
                    || !isWave4ObeliskChannelerActive()
                    || !"CHANNELER".equalsIgnoreCase(readString(entity, keyObeliskWave4Role))) {
                continue;
            }
            Wave4ObeliskRuntimeState target = targets.get(targetIndex++ % targets.size());
            String key = "current-obelisk-channeler-" + entity.getUniqueId();
            desired.add(key);
            Location from = living.getEyeLocation();
            Location to = target.base().clone().add(0.0D, 2.5D, 0.0D);
            for (Player viewer : eventAudience()) {
                sendWorldBeamPacket(viewer, key, from, to, 0x45DAFF, 0.045F);
            }
        }
        clearWorldVfxBeamsOutside("current-obelisk-channeler-", desired);
    }

    private int tagWaveThreePusher(Entity entity, int wave, int packSlot) {
        if (entity == null) {
            return packSlot;
        }
        if (wave == 3 && Wave3PortalPolicy.isPusher(packSlot)
                && keyPortalPusher != null) {
            entity.getPersistentDataContainer().set(keyPortalPusher,
                    PersistentDataType.BYTE, (byte) 1);
            if (entity instanceof LivingEntity living) {
                living.setCustomName(ChatColor.GOLD + "Толкатель Врат");
                living.setCustomNameVisible(true);
                AttributeInstance knockback = living.getAttribute(Attribute.GENERIC_ATTACK_KNOCKBACK);
                if (knockback != null) {
                    knockback.setBaseValue(knockback.getBaseValue()
                            + Wave3PortalPolicy.PUSHER_KNOCKBACK_AMPLIFIER * 0.4D);
                }
            }
            getLogger().info("WAVE_PORTAL_PUSHER_ASSIGNED event=" + eventId
                    + " entity=" + entity.getUniqueId()
                    + " slot=" + packSlot + " count_cap=" + Wave3PortalPolicy.PUSHERS_PER_PACK);
        }
        return packSlot + 1;
    }

    /** Initialise the one canonical objective owned by the current wave. */
    private void startCanonicalObjective(int wave, World world, Location core) {
        if (world == null || core == null || wave < 1
                || !EndRiftObjective.isNumberedWave(wave)) {
            return;
        }
        waveObjectiveStartedMillis = System.currentTimeMillis();
        waveObjectiveLastSecond = -1;
        waveObjectiveComplete = false;
        waveObjectiveMobCount = countLiveWaveEntitiesForWave(wave);
        switch (EndRiftObjective.objective(wave)) {
            case RIFT_CARRIERS -> {
                currentCarrierCharges = 0;
                currentCarrierUuid = null;
                currentCarrierChargeUuid = null;
                currentCarrierChargeLocation = null;
                currentCarrierReplacementCount = 0;
                currentCarrierState = RiftCarrierPolicy.initial(generation);
                announceEventTitle("§dНОСИТЕЛИ РАЗЛОМА",
                        "§fТри заряда должны вернуться к ядру", true);
            }
            case RIFT_HUNT -> {
                currentHuntCycles = 0;
                currentHuntNextMarkMillis = waveObjectiveStartedMillis + 2_000L;
                waveTwoMarkedPlayerUuid = null;
                announceEventTitle("§dОХОТА РАЗЛОМА",
                        "§fМетка переходит между выжившими", true);
            }
            case RIFT_GATES -> {
                currentPrepareSequentialPortals(world, core);
                announceEventTitle("§dВОРОТА РАЗЛОМА",
                        "§fЗакройте врата по очереди", true);
            }
            case BLACK_FOG -> {
                currentFogCycle = 0;
                blackFogPhase = BlackFogPhase.COMBAT;
                blackFogPhaseDeadlineMillis = waveObjectiveStartedMillis
                        + BlackFogTimingPolicy.combatSeconds(currentFogCycle) * 1_000L;
                currentFogZoneCount = 0;
                currentFogZoneSide = 0;
                currentSafeZoneCenters.clear();
                currentFogLastImpactAt.clear();
                announceEventTitle("§dЧЁРНЫЙ ТУМАН",
                        "§fИщите зелёный свет, когда арена погаснет", true);
            }
            case COLLAPSE_RINGS -> {
                currentCollapsedRings = 0;
                currentRingNextCollapseAtMillis = 0L;
                collapseRingEncounterState = null;
                collapseRingGuardUuids.clear();
                collapseRingPrisonerDisplayUuid = null;
                collapseRingIceCells.clear();
                collapseRingIceOriginals.clear();
                spawnCurrentRingVisuals(world, core);
                announceEventTitle("§dКОЛЬЦА КОЛЛАПСА",
                        "§fРазрушьте три рубежа Разлома", true);
            }
            case REALITY_SPLIT -> {
                wave6Complete = false;
                announceEventTitle("§dРАСКОЛ РЕАЛЬНОСТИ",
                        "§fКаждая комната должна пережить свой бой", true);
            }
        }
        getLogger().info("WAVE_OBJECTIVE_STARTED event=" + eventId
                + " wave=" + wave + " objective=" + EndRiftObjective.objective(wave)
                + " mobs=" + waveObjectiveMobCount + " generation=" + generation);
    }

    private void startWaveObjective(int wave, World world, Location core) {
        if (!EndRiftObjective.isNumberedWave(wave) || world == null || core == null) {
            return;
        }
        startCanonicalObjective(wave, world, core);
    }

    /** Three floor-anchored portals; only the first incomplete one is active. */
    private void currentPrepareSequentialPortals(World world, Location core) {
        wavePortals.remove(3);
        portalCaptureStates.remove(3);
        List<Location> portals = new ArrayList<>();
        List<PortalCapturePolicy.PortalState> states = new ArrayList<>();
        for (int index = 0; index < EndRiftObjective.GATE_COUNT; index++) {
            double angle = -Math.PI / 2.0D + index * Math.PI * 2.0D
                    / EndRiftObjective.GATE_COUNT;
            portals.add(core.clone().add(Math.cos(angle) * 8.0D, 0.0D,
                    Math.sin(angle) * 8.0D));
            states.add(PortalCapturePolicy.initial());
        }
        wavePortals.put(3, portals);
        portalCaptureStates.put(3, states);
        spawnPortalObjectiveVisuals(world, portals);
        getLogger().info("END_RIFT_PORTAL_VISUALS event=" + eventId
                + " portals=" + portals.size() + " layers=FRAME,INNER,SHARD"
                + " floor_anchored=true model_data=true");
        getLogger().info("END_RIFT_PORTALS_READY event=" + eventId + " count=3 sequential=true");
    }

    /** Render and advance the bounded controller for the current objective. */
    private boolean tickCurrentObjective() {
        int objectiveWave = activeWave;
        if (!isOfficialAttempt() || !EndRiftObjective.isNumberedWave(objectiveWave)) {
            return true;
        }
        if (waveObjectiveStartedMillis <= 0L) {
            World world = Bukkit.getWorld(worldName);
            Location core = coreCombatAnchorLocation();
            if (world != null && core != null) {
                startCanonicalObjective(objectiveWave, world, core);
            }
        }
        long now = System.currentTimeMillis();
        waveObjectiveLastSecond = (int) Math.max(0L,
                (now - waveObjectiveStartedMillis) / 1_000L);
        switch (EndRiftObjective.objective(objectiveWave)) {
            case RIFT_CARRIERS -> tickCurrentCarrierObjective(now);
            case RIFT_HUNT -> tickCurrentHuntObjective(now);
            case RIFT_GATES -> updatePortalObjective(now);
            case OBELISK_ASSAULT -> {
                // The physical obelisk controller owns this objective's
                // progress; it is ticked by the Wave 4 branch below.
            }
            case BLACK_FOG -> tickBlackFogObjective(now);
            case COLLAPSE_RINGS -> tickCurrentCollapseRingObjective(now);
            case REALITY_SPLIT -> tickCurrentChamberObjective(now);
        }
        renderWaveObjective(now);
        boolean allGroupsSpawned = waveSpawnGroupIndex >= waveSpawnSchedule.size();
        boolean noMobs = countLiveWaveEntitiesForWave(activeWave) == 0;
        if (allGroupsSpawned && noMobs && currentObjectiveProgressComplete(objectiveWave)) {
            waveObjectiveComplete = true;
        }
        return waveObjectiveComplete;
    }

    private boolean tickWaveObjective() {
        if (!isOfficialCurrentAttempt() || !EndRiftObjective.isNumberedWave(activeWave)) {
            return true;
        }
        if (activeWave == 4) {
            return tickWave4ObeliskAssault();
        }
        return tickCurrentObjective();
    }

    private boolean currentObjectiveProgressComplete(int objectiveWave) {
        return switch (EndRiftObjective.objective(objectiveWave)) {
            case RIFT_CARRIERS -> currentCarrierCharges >= EndRiftObjective.REQUIRED_CARRIER_DELIVERIES;
            case RIFT_HUNT -> currentHuntCycles >= EndRiftObjective.REQUIRED_HUNT_CYCLES;
            case RIFT_GATES -> waveObjectiveComplete;
            case OBELISK_ASSAULT -> waveObjectiveComplete;
            case BLACK_FOG -> currentFogCycle >= EndRiftObjective.REQUIRED_FOG_CYCLES;
            case COLLAPSE_RINGS -> currentCollapsedRings >= EndRiftObjective.REQUIRED_COLLAPSE_RINGS;
            case REALITY_SPLIT -> waveObjectiveComplete;
        };
    }

    private void tickCurrentCarrierObjective(long now) {
        if (currentCarrierState == null || currentCarrierState.generation() != generation) {
            currentCarrierState = RiftCarrierPolicy.initial(generation);
            syncCurrentCarrierFields();
        }
        if (RiftCarrierPolicy.isComplete(currentCarrierState)) {
            return;
        }
        boolean allGroupsSpawned = waveSpawnGroupIndex >= waveSpawnSchedule.size();
        if (currentCarrierState.phase() == RiftCarrierPolicy.Phase.CARRIER_ACTIVE
                && !isLiveOwnedEntity(currentCarrierState.carrier())) {
            Location fallback = currentCarrierChargeLocation == null
                    ? coreCombatAnchorLocation() : currentCarrierChargeLocation.clone();
            if (fallback != null) {
                spawnCurrentCarrierCharge(fallback);
            }
        }
        if (currentCarrierState.phase() == RiftCarrierPolicy.Phase.CHARGE_DROPPED) {
            Entity charge = currentCarrierChargeEntity();
            if (charge == null || !charge.isValid()) {
                Location fallback = currentCarrierChargeLocation == null
                        ? coreCombatAnchorLocation() : currentCarrierChargeLocation.clone();
                if (fallback != null) {
                    spawnCurrentCarrierCharge(fallback);
                }
            } else {
                currentCarrierChargeLocation = charge.getLocation().clone();
                Player pickup = activeLivingPlayers().stream()
                        .filter(player -> player.getLocation().distanceSquared(charge.getLocation()) <= 2.25D)
                        .sorted(Comparator.comparing(player -> player.getUniqueId().toString()))
                        .findFirst().orElse(null);
                if (pickup != null) {
                    currentCarrierState = RiftCarrierPolicy.pickUp(currentCarrierState, generation,
                            pickup.getUniqueId(), charge.getUniqueId(), eventTickCounter);
                    syncCurrentCarrierFields();
                    if (currentCarrierState.phase() == RiftCarrierPolicy.Phase.CHARGE_CARRIED) {
                        pickup.getWorld().playSound(pickup.getLocation(), Sound.BLOCK_RESPAWN_ANCHOR_CHARGE,
                                0.8F, 1.35F);
                        getLogger().info("END_RIFT_CARRIER_PICKED_UP event=" + eventId
                                + " player=" + pickup.getUniqueId()
                                + " charge=" + charge.getUniqueId());
                    }
                }
            }
        }
        if (currentCarrierState.phase() == RiftCarrierPolicy.Phase.CHARGE_CARRIED) {
            Entity charge = currentCarrierChargeEntity();
            Player holder = Bukkit.getPlayer(currentCarrierState.holder());
            if (charge != null && holder != null && holder.isOnline()) {
                // The charge is an event-owned Display and therefore also
                // passes through the anti-escape teleport guard.  Use the
                // same scoped permit as combat entities; a raw teleport is
                // rejected as an external move and leaves the carried visual
                // behind at the pickup point.
                teleportCombatEntity(charge,
                        holder.getLocation().clone().add(0.0D, 1.15D, 0.0D));
                currentCarrierChargeLocation = charge.getLocation().clone();
                Location core = coreCombatAnchorLocation();
                boolean atCore = core != null && holder.getWorld().equals(core.getWorld())
                        && holder.getLocation().distanceSquared(core) <= 6.25D;
                RiftCarrierPolicy.State before = currentCarrierState;
                currentCarrierState = RiftCarrierPolicy.deliver(currentCarrierState, generation,
                        holder.getUniqueId(), atCore, eventTickCounter);
                if (currentCarrierState != before) {
                    if (currentCarrierState.delivered() > before.delivered()) {
                        removeCurrentCarrierChargeVisual();
                        currentCarrierCharges = currentCarrierState.delivered();
                        if (core != null) {
                            spawnEventParticle(core.clone().add(0.0D, 1.0D, 0.0D),
                                    Particle.END_ROD, 24, 0.5D, 0.8D, 0.5D, 0.03D);
                            core.getWorld().playSound(core, Sound.BLOCK_BEACON_POWER_SELECT,
                                    0.9F, 1.45F);
                        }
                        getLogger().info("END_RIFT_CARRIER_DELIVERED event=" + eventId
                                + " charge=" + currentCarrierCharges + "/3 player=" + holder.getUniqueId());
                    }
                    syncCurrentCarrierFields();
                }
            } else {
                releaseCurrentCarrierHolder(currentCarrierState.holder(), "holder-unavailable");
            }
        }
        if ((currentCarrierState.phase() == RiftCarrierPolicy.Phase.CHARGE_DROPPED
                || currentCarrierState.phase() == RiftCarrierPolicy.Phase.CHARGE_CARRIED)
                && RiftCarrierPolicy.expired(currentCarrierState, eventTickCounter)) {
            Entity next = findCurrentCarrierCandidate();
            if (next != null) {
                removeCurrentCarrierChargeVisual();
                currentCarrierState = RiftCarrierPolicy.timeoutTransfer(currentCarrierState,
                        generation, next.getUniqueId(), eventTickCounter);
                syncCurrentCarrierFields();
                getLogger().info("END_RIFT_CARRIER_TIMEOUT_TRANSFER event=" + eventId
                        + " entity=" + next.getUniqueId()
                        + " delivered=" + currentCarrierCharges);
            } else if (allGroupsSpawned
                    && currentCarrierReplacementCount < CARRIER_REPLACEMENT_CAP) {
                RiftCarrierPolicy.State replacementState = RiftCarrierPolicy.expireForReplacement(
                        currentCarrierState, generation, eventTickCounter);
                if (replacementState != currentCarrierState) {
                    removeCurrentCarrierChargeVisual();
                    currentCarrierState = replacementState;
                    syncCurrentCarrierFields();
                    World world = Bukkit.getWorld(worldName);
                    Location core = coreCombatAnchorLocation();
                    if (spawnCurrentCarrierReplacement(world, core)) {
                        getLogger().info("END_RIFT_CARRIER_TIMEOUT_REPLACEMENT event=" + eventId
                                + " delivered=" + currentCarrierCharges);
                    }
                }
            }
        }
        if (currentCarrierState.phase() == RiftCarrierPolicy.Phase.WAITING_FOR_CARRIER
                || currentCarrierState.phase() == RiftCarrierPolicy.Phase.READY_FOR_NEXT_CARRIER) {
            Entity next = findCurrentCarrierCandidate();
            if (next != null) {
                currentCarrierState = RiftCarrierPolicy.selectCarrier(currentCarrierState,
                        generation, next.getUniqueId());
                syncCurrentCarrierFields();
                if (next instanceof LivingEntity living) {
                    living.setCustomName(ChatColor.AQUA + "Носитель Заряда");
                    living.setCustomNameVisible(true);
                }
                getLogger().info("END_RIFT_CARRIER_SELECTED event=" + eventId
                        + " entity=" + next.getUniqueId()
                        + " charge=" + (currentCarrierCharges + 1));
            } else if (allGroupsSpawned
                    && RiftCarrierPolicy.shouldSpawnReplacement(currentCarrierState,
                    generation, true, 0)
                    && currentCarrierReplacementCount < CARRIER_REPLACEMENT_CAP) {
                World world = Bukkit.getWorld(worldName);
                Location core = coreCombatAnchorLocation();
                spawnCurrentCarrierReplacement(world, core);
            }
        }
        if (currentCarrierState.phase() == RiftCarrierPolicy.Phase.CARRIER_ACTIVE
                && now % 500L < 150L) {
            Entity carrier = ownedEntities.get(currentCarrierState.carrier());
            Location core = coreCombatAnchorLocation();
            if (carrier != null && core != null) {
                for (Player viewer : eventAudience()) {
                    if (isEventParticleViewer(viewer, core)) {
                        sendWorldBeamPacket(viewer, "wave1-carrier",
                                carrier.getLocation().add(0.0D, 1.0D, 0.0D),
                                core.clone().add(0.0D, 1.0D, 0.0D), 0x4EE6FF,
                                WORLD_VFX_BEAM_DEFAULT_WIDTH);
                        viewer.spawnParticle(Particle.END_ROD,
                                carrier.getLocation().add(0.0D, 1.0D, 0.0D),
                                3, 0.12D, 0.22D, 0.12D, 0.01D);
                    }
                }
            }
        }
    }

    private void syncCurrentCarrierFields() {
        if (currentCarrierState == null) {
            currentCarrierUuid = null;
            currentCarrierChargeUuid = null;
            return;
        }
        currentCarrierCharges = currentCarrierState.delivered();
        currentCarrierUuid = currentCarrierState.carrier();
        currentCarrierChargeUuid = currentCarrierState.charge();
    }

    /** Drop a carried W1 charge immediately when its holder leaves the valid encounter. */
    private void releaseCurrentCarrierHolder(UUID holder, String reason) {
        if (currentCarrierState == null || holder == null
                || currentCarrierState.phase() != RiftCarrierPolicy.Phase.CHARGE_CARRIED) {
            return;
        }
        RiftCarrierPolicy.State next = RiftCarrierPolicy.releaseHolder(
                currentCarrierState, generation, holder, eventTickCounter);
        if (next == currentCarrierState) {
            return;
        }
        currentCarrierState = next;
        syncCurrentCarrierFields();
        Entity charge = currentCarrierChargeEntity();
        if (charge != null && charge.isValid()) {
            currentCarrierChargeLocation = charge.getLocation().clone();
        }
        getLogger().info("END_RIFT_CARRIER_HOLDER_RELEASED event=" + eventId
                + " holder=" + holder + " reason=" + reason
                + " delivered=" + currentCarrierCharges);
    }

    /**
     * Recover Wave 1 when every scheduled carrier has disappeared before the
     * three charges are delivered.  The replacement is still an ordinary
     * event-owned mob, so normal combat, loot and cleanup paths remain the
     * authority.  The hard cap prevents a bad world or a broken client from
     * turning this recovery path into an infinite spawn loop.
     */
    private boolean spawnCurrentCarrierReplacement(World world, Location core) {
        if (world == null || core == null || currentCarrierReplacementCount >= CARRIER_REPLACEMENT_CAP
                || currentCarrierState == null || RiftCarrierPolicy.isComplete(currentCarrierState)) {
            return false;
        }
        int replacementIndex = 10_000 + currentCarrierReplacementCount;
        Enderman replacement = spawnEnderman(world, core, 1, false, false,
                false, replacementIndex, replacementIndex);
        if (replacement == null || !replacement.isValid()) {
            getLogger().warning("END_RIFT_CARRIER_REPLACEMENT_REFUSED event=" + eventId
                    + " delivered=" + currentCarrierState.delivered()
                    + " attempt=" + (currentCarrierReplacementCount + 1)
                    + " cap=" + CARRIER_REPLACEMENT_CAP);
            return false;
        }
        currentCarrierReplacementCount++;
        getLogger().info("END_RIFT_CARRIER_REPLACEMENT_SPAWNED event=" + eventId
                + " entity=" + replacement.getUniqueId()
                + " delivered=" + currentCarrierState.delivered()
                + " count=" + currentCarrierReplacementCount
                + " cap=" + CARRIER_REPLACEMENT_CAP);
        return true;
    }

    private Entity findCurrentCarrierCandidate() {
        return ownedEntities.values().stream()
                .filter(entity -> isWaveCombatKind(readString(entity, keyKind)))
                .filter(entity -> readInt(entity, keyWave, 0) == activeWave)
                .filter(entity -> isLiveOwnedEntity(entity.getUniqueId()))
                .filter(entity -> currentCarrierState == null
                        || !entity.getUniqueId().equals(currentCarrierState.carrier()))
                .sorted(Comparator.comparing(entity -> entity.getUniqueId().toString()))
                .findFirst().orElse(null);
    }

    private Entity currentCarrierChargeEntity() {
        return currentCarrierState == null || currentCarrierState.charge() == null
                ? null : ownedEntities.get(currentCarrierState.charge());
    }

    private void spawnCurrentCarrierCharge(Location requested) {
        if (currentCarrierState == null
                || currentCarrierState.phase() != RiftCarrierPolicy.Phase.CARRIER_ACTIVE
                || currentCarrierState.carrier() == null || requested == null
                || requested.getWorld() == null) {
            return;
        }
        removeCurrentCarrierChargeVisual();
        ItemDisplay display = requested.getWorld().spawn(
                requested.clone().add(0.0D, 0.18D, 0.0D), ItemDisplay.class, value -> {
                    value.setItemStack(overlayItem(MODEL_PORTAL_SHARD_OVERLAY,
                            "end_event_portal_shard"));
                    value.setBrightness(new Display.Brightness(15, 15));
                    value.setBillboard(Display.Billboard.CENTER);
                    value.setGravity(false);
                    value.setInvulnerable(true);
                    value.setPersistent(false);
                    value.setViewRange(48.0F);
                    value.setTransformation(new Transformation(
                            new Vector3f(-0.35F, -0.35F, -0.35F), new AxisAngle4f(),
                            new Vector3f(0.70F, 0.70F, 0.70F), new AxisAngle4f()));
                });
        tag(display, EVENT_KIND_DISPLAY, 1, true);
        if (keyCurrentCarrierCharge != null) {
            display.getPersistentDataContainer().set(keyCurrentCarrierCharge,
                    PersistentDataType.BYTE, (byte) 1);
        }
        ownedEntities.put(display.getUniqueId(), display);
        waveObjectiveVisuals.add(display.getUniqueId());
        currentCarrierChargeLocation = display.getLocation().clone();
        RiftCarrierPolicy.State next = RiftCarrierPolicy.carrierDied(currentCarrierState,
                generation, currentCarrierState.carrier(), display.getUniqueId(), eventTickCounter);
        if (next == currentCarrierState) {
            ownedEntities.remove(display.getUniqueId());
            waveObjectiveVisuals.remove(display.getUniqueId());
            display.remove();
            return;
        }
        currentCarrierState = next;
        syncCurrentCarrierFields();
        renderCurrentCarrierCharge(display);
        getLogger().info("END_RIFT_CARRIER_CHARGE_CREATED event=" + eventId
                + " charge=" + display.getUniqueId() + " timeout_ticks="
                + RiftCarrierPolicy.CHARGE_TIMEOUT_TICKS);
    }

    private void renderCurrentCarrierCharge(ItemDisplay display) {
        if (display == null || !display.isValid()) {
            return;
        }
        Location center = display.getLocation();
        for (Player viewer : eventAudience()) {
            if (isEventParticleViewer(viewer, center)) {
                viewer.spawnParticle(Particle.REVERSE_PORTAL, center, 8,
                        0.22D, 0.35D, 0.22D, 0.02D);
                viewer.spawnParticle(Particle.END_ROD, center, 3,
                        0.08D, 0.15D, 0.08D, 0.01D);
            }
        }
    }

    private void removeCurrentCarrierChargeVisual() {
        if (currentCarrierChargeUuid == null) {
            currentCarrierChargeLocation = null;
            return;
        }
        Entity charge = ownedEntities.remove(currentCarrierChargeUuid);
        if (charge == null) {
            charge = Bukkit.getEntity(currentCarrierChargeUuid);
        }
        if (charge != null && charge.isValid()) {
            charge.remove();
        }
        waveObjectiveVisuals.remove(currentCarrierChargeUuid);
        currentCarrierChargeUuid = null;
        currentCarrierChargeLocation = null;
    }

    private void tickCurrentHuntObjective(long now) {
        if (waveTwoMarkedPlayerUuid != null && now >= waveTwoMarkDeadlineMillis) {
            currentHuntCycles = Math.min(EndRiftObjective.REQUIRED_HUNT_CYCLES,
                    currentHuntCycles + 1);
            waveTwoMarkedPlayerUuid = null;
            waveTwoMarkRevealDeadlineMillis = 0L;
            waveTwoMarkDeadlineMillis = 0L;
            waveTwoNextMarkMillis = now + 1_000L;
            getLogger().info("BOSS_HUNT_CYCLE event=" + eventId
                    + " cycle=" + currentHuntCycles + "/3");
        }
        if (currentHuntCycles < EndRiftObjective.REQUIRED_HUNT_CYCLES) {
            updateMarkedTargetObjective(now);
        }
    }

    private void tickBlackFogObjective(long now) {
        Location core = coreCombatAnchorLocation();
        if (core == null) {
            return;
        }
        if (blackFogPhaseDeadlineMillis <= 0L) {
            blackFogPhaseDeadlineMillis = now
                    + BlackFogTimingPolicy.combatSeconds(currentFogCycle) * 1_000L;
        }
        if (now >= blackFogPhaseDeadlineMillis) {
            if (blackFogPhase == BlackFogPhase.COMBAT) {
                blackFogPhase = BlackFogPhase.SAFE;
                currentFogZoneCount = EndRiftObjective.fogZoneCount(eventScalePlayers(), currentFogCycle);
                currentFogZoneSide = EndRiftObjective.fogZoneSide(currentFogCycle);
                spawnCurrentSafeZoneVisuals(core.getWorld(), core);
                blackFogPhaseDeadlineMillis = now + BlackFogTimingPolicy.safeZoneSeconds() * 1_000L;
                announceEventTitle("§aЗОНЫ УКРЫТИЯ", "§fЗелёный свет удержит туман", false);
                getLogger().info("END_RIFT_FOG_SAFE_START event=" + eventId + " cycle="
                        + (currentFogCycle + 1) + "/3" + " zones=" + currentFogZoneCount
                        + " side=" + currentFogZoneSide);
            } else if (blackFogPhase == BlackFogPhase.SAFE) {
                blackFogPhase = BlackFogPhase.FOG;
                blackFogPhaseDeadlineMillis = now + BlackFogTimingPolicy.fogSeconds() * 1_000L;
                freezeWaveMobs(true);
                announceEventTitle("§5ЧЁРНЫЙ ТУМАН", "§fНе выходите из зелёного света", false);
                getLogger().info("END_RIFT_FOG_START event=" + eventId + " cycle="
                        + (currentFogCycle + 1) + "/3" + " height=3");
            } else {
                freezeWaveMobs(false);
                clearCurrentSafeZoneVisuals();
                currentFogCycle++;
                if (currentFogCycle >= EndRiftObjective.REQUIRED_FOG_CYCLES) {
                    blackFogPhaseDeadlineMillis = 0L;
                    getLogger().info("END_RIFT_FOG_COMPLETE event=" + eventId + " cycles=3");
                } else {
                    blackFogPhase = BlackFogPhase.COMBAT;
                    blackFogPhaseDeadlineMillis = now
                            + BlackFogTimingPolicy.combatSeconds(currentFogCycle) * 1_000L;
                }
            }
        }
        if (blackFogPhase == BlackFogPhase.FOG) {
            applyBlackFogEffects(now, core);
        } else if (blackFogPhase == BlackFogPhase.SAFE) {
            for (Player player : activeLivingPlayers()) {
                if (isCurrentSafeZonePlayer(player)) {
                    player.addPotionEffect(new PotionEffect(PotionEffectType.REGENERATION,
                            80, 0, false, true, true));
                }
            }
        }
    }

    /**
     * Current Wave 6 controller.  Each ring owns one pair of guards.  The
     * first death starts the exact 200-tick coordination window; a timeout
     * rebuilds the pair at the policy's bounded health fraction.  The old
     * multi-stage prisoner/tower encounter is intentionally not part of the
     * current objective graph.
     */
    private void tickCurrentCollapseRingObjective(long now) {
        if (activeWave != 6 || !isOfficialCurrentAttempt()) {
            return;
        }
        if (currentCollapsedRings >= EndRiftObjective.REQUIRED_COLLAPSE_RINGS) {
            return;
        }
        CollapseRingEncounterPolicy.State state = collapseRingEncounterState;
        if (state != null && state.generation() == generation
                && CollapseRingEncounterPolicy.pairDefeated(state, generation)) {
            currentCollapsedRings++;
            clearCurrentCollapseRingPair();
            removeCurrentRingVisual(currentCollapsedRings - 1);
            Location core = coreCombatAnchorLocation();
            if (core != null) {
                spawnEventParticle(core.clone().add(0.0D, 0.35D, 0.0D),
                        Particle.REVERSE_PORTAL, 48, 2.5D, 0.25D, 2.5D, 0.04D);
                core.getWorld().playSound(core, Sound.BLOCK_RESPAWN_ANCHOR_DEPLETE,
                        0.8F, 1.25F);
            }
            getLogger().info("WAVE_6_PAIR_DEFEATED event=" + eventId
                    + " completed=" + currentCollapsedRings + "/"
                    + EndRiftObjective.REQUIRED_COLLAPSE_RINGS);
            if (currentCollapsedRings >= EndRiftObjective.REQUIRED_COLLAPSE_RINGS) {
                collapseRingEncounterState = state;
                return;
            }
            collapseRingEncounterState = null;
        }
        state = collapseRingEncounterState;
        if (state != null && state.generation() == generation) {
            CollapseRingEncounterPolicy.State advanced = CollapseRingEncounterPolicy.tick(
                    state, generation, eventTickCounter);
            if (advanced != state && advanced.phase() == CollapseRingEncounterPolicy.Phase.BOTH_ALIVE) {
                getLogger().info("WAVE_6_PAIR_REBUILT event=" + eventId
                        + " fraction=" + advanced.reviveHealthFraction());
                clearCurrentCollapseRingPair();
                collapseRingEncounterState = null;
                state = null;
            } else {
                collapseRingEncounterState = advanced;
                state = advanced;
            }
        }
        if (state == null) {
            Location core = coreCombatAnchorLocation();
            World world = core == null ? null : core.getWorld();
            if (world != null && spawnCurrentCollapseRingPair(world, core,
                    currentCollapsedRings)) {
                renderCurrentCollapseRingPair(collapseRingEncounterState);
            }
        } else {
            tickCurrentCollapseRingTargets(state);
            renderCurrentCollapseRingPair(state);
        }
    }

    private boolean spawnCurrentCollapseRingPair(World world, Location core, int ring) {
        if (world == null || core == null || collapseRingEncounterState != null
                || !collapseRingGuardUuids.isEmpty()) {
            return false;
        }
        List<UUID> spawned = new ArrayList<>();
        double baseAngle = eventTickCounter * 0.01D + ring * Math.PI * 0.7D;
        for (int slot = 0; slot < 2; slot++) {
            double angle = baseAngle + (slot == 0 ? 0.0D : Math.PI);
            Location spawn = core.clone().add(Math.cos(angle) * (6.0D + ring * 2.0D),
                    0.0D, Math.sin(angle) * (6.0D + ring * 2.0D));
            Location safe = findSafeCombatLocation(core, spawn,
                    boundedCombatRadius(config.arenaRadius()) - 1.0D,
                    MIN_WAVE_CORE_DISTANCE_BLOCKS, -1);
            Skeleton guard = safe == null ? null : spawnSkeletonAt(world, safe, 6, true,
                    600 + ring * 2 + slot);
            if (guard == null) {
                clearCurrentCollapseRingPair();
                return false;
            }
            guard.setCustomName(ChatColor.DARK_PURPLE + "Страж Кольца " + (slot + 1));
            guard.setCustomNameVisible(true);
            spawned.add(guard.getUniqueId());
            collapseRingGuardUuids.add(guard.getUniqueId());
            collapseRingGuardSlots.put(guard.getUniqueId(), slot);
        }
        if (spawned.size() != 2) {
            clearCurrentCollapseRingPair();
            return false;
        }
        collapseRingEncounterState = CollapseRingEncounterPolicy.initial(generation, ring,
                spawned.get(0), spawned.get(1), eventTickCounter);
        getLogger().info("WAVE_6_PAIR_SPAWNED event=" + eventId
                + " ring=" + (ring + 1) + " guards=2 timer_ticks="
                + CollapseRingEncounterPolicy.PAIR_TIMER_TICKS);
        return true;
    }

    private Skeleton spawnSkeletonAt(World world, Location location, int wave, boolean miniBoss,
                                     int index) {
        if (world == null || location == null) {
            return null;
        }
        Entity entity = world.spawnEntity(location, EntityType.SKELETON);
        if (!(entity instanceof Skeleton skeleton)) {
            entity.remove();
            return null;
        }
        tag(entity, EVENT_KIND_ELITE, wave, true);
        setLootProfile(entity, "skeleton");
        skeleton.setPersistent(true);
        skeleton.setRemoveWhenFarAway(false);
        skeleton.setCanPickupItems(false);
        skeleton.setAI(true);
        skeleton.setAware(true);
        if (skeleton.getEquipment() != null) {
            skeleton.getEquipment().setItemInMainHand(new ItemStack(Material.BOW));
            skeleton.getEquipment().setItemInMainHandDropChance(0.0F);
        }
        configureEventMobStats(skeleton, EntityType.SKELETON);
        if (miniBoss) {
            AttributeInstance max = skeleton.getAttribute(Attribute.GENERIC_MAX_HEALTH);
            if (max != null) {
                double health = Math.max(max.getBaseValue(), config.skeletonEliteHealth());
                max.setBaseValue(health);
                skeleton.setHealth(health);
            }
        }
        ownedEntities.put(entity.getUniqueId(), entity);
        assignCombatTactic(entity, index);
        bindEventEntityClientForOnlinePlayers(entity);
        return skeleton;
    }

    private void tickCurrentCollapseRingTargets(CollapseRingEncounterPolicy.State state) {
        List<Player> players = activeLivingPlayers();
        if (players.isEmpty()) {
            return;
        }
        for (UUID guardId : new LinkedHashSet<>(collapseRingGuardUuids)) {
            Entity entity = ownedEntities.get(guardId);
            if (!(entity instanceof Mob mob) || !isLiveOwnedEntity(guardId)) {
                continue;
            }
            mob.setTarget(null);
            if (!CollapseRingEncounterPolicy.guardMayAttack(state, players.size(), guardId,
                    eventTickCounter)) {
                continue;
            }
            Player target = players.get(Math.floorMod(
                    collapseRingGuardSlots.getOrDefault(guardId, 0)
                            + (int) (eventTickCounter / CollapseRingEncounterPolicy.PAIR_TIMER_TICKS),
                    players.size()));
            if (isCombatTarget(target)) {
                mob.setTarget(target);
            }
        }
    }

    private void renderCurrentCollapseRingPair(CollapseRingEncounterPolicy.State state) {
        if (state == null || state.generation() != generation) {
            clearWorldVfxBeamsByPrefix("wave6-pair-");
            return;
        }
        Location core = coreCombatAnchorLocation();
        if (core == null) {
            clearWorldVfxBeamsByPrefix("wave6-pair-");
            return;
        }
        Set<String> active = new LinkedHashSet<>();
        for (UUID guardId : List.of(state.guardA(), state.guardB())) {
            Entity guard = ownedEntities.get(guardId);
            if (!(guard instanceof LivingEntity living) || !isLiveOwnedEntity(guardId)) {
                continue;
            }
            String key = "wave6-pair-" + guardId;
            active.add(key);
            for (Player viewer : eventAudience()) {
                if (isEventParticleViewer(viewer, core)) {
                    sendWorldBeamPacket(viewer, key, core.clone().add(0.0D, 0.9D, 0.0D),
                            living.getLocation().add(0.0D, 1.0D, 0.0D),
                            state.phase() == CollapseRingEncounterPolicy.Phase.FIRST_DOWN
                                    ? 0xFF6B6B : 0xB84DFF, 0.07F);
                }
            }
        }
        clearWorldVfxBeamsOutside("wave6-pair-", active);
    }

    private void removeCurrentRingVisual(int ring) {
        Set<UUID> ids = currentRingVisualGroups.remove(ring);
        if (ids == null) {
            return;
        }
        for (UUID id : ids) {
            Entity display = ownedEntities.remove(id);
            if (display != null && display.isValid()) {
                display.remove();
            }
            currentRingVisuals.remove(id);
            waveObjectiveVisuals.remove(id);
        }
    }

    private void clearCurrentCollapseRingPair() {
        for (UUID guardId : new LinkedHashSet<>(collapseRingGuardUuids)) {
            Entity entity = ownedEntities.remove(guardId);
            if (entity == null) {
                entity = Bukkit.getEntity(guardId);
            }
            if (entity != null && entity.isValid()) {
                entity.remove();
            }
            unbindEventEntityClient(guardId);
            waveMobTactics.remove(guardId);
            miniBossSpells.remove(guardId);
            nextMiniBossSpellMillis.remove(guardId);
            nextSkeletonArrowMillis.remove(guardId);
        }
        collapseRingGuardUuids.clear();
        collapseRingGuardSlots.clear();
        clearWorldVfxBeamsByPrefix("wave6-pair-");
    }

    private boolean isCurrentCollapseGuard(Entity entity) {
        return entity != null && activeWave == 6 && isOfficialCurrentAttempt()
                && collapseRingGuardUuids.contains(entity.getUniqueId())
                && ownedEntities.containsKey(entity.getUniqueId());
    }

    private boolean currentCollapseTargetAllowed(Entity source, Player player) {
        if (!isCurrentCollapseGuard(source) || !isCombatTarget(player)) {
            return false;
        }
        CollapseRingEncounterPolicy.State state = collapseRingEncounterState;
        return state != null && state.generation() == generation
                && CollapseRingEncounterPolicy.guardMayAttack(state,
                activeLivingPlayers().size(), source.getUniqueId(), eventTickCounter);
    }

    private void tickCurrentChamberObjective(long now) {
        if (!realitySplitChamberController.owns(generation)) {
            return;
        }
        boolean allGroupsSpawned = waveSpawnGroupIndex >= waveSpawnSchedule.size();
        int chamberCount = realitySplitChamberController.assignment().chamberCount();
        if (!allGroupsSpawned || chamberCount <= 0) {
            return;
        }
        for (int chamber = 0; chamber < chamberCount; chamber++) {
            if (realitySplitChamberController.chamberComplete(generation, chamber)) {
                continue;
            }
            if (countLiveWaveEntitiesForChamber(chamber) == 0) {
                boolean marked = realitySplitChamberController.markChamberComplete(
                        generation, chamber);
                if (marked) {
                    for (int other = 0; other < chamberCount; other++) {
                        realitySplitChamberController.openCompletedPassage(
                                generation, chamber, other);
                    }
                    getLogger().info("END_RIFT_REALITY_SPLIT_CHAMBER_COMPLETE event=" + eventId
                            + " chamber=" + chamber + " completed="
                            + countCompletedRealitySplitChambers() + "/" + chamberCount);
                }
            }
        }
        if (realitySplitChamberController.allChambersComplete(generation)
                && !waveObjectiveComplete) {
            waveObjectiveComplete = true;
            wave6Complete = true;
            // Only the explicit all-room completion step merges the graph.
            realitySplitChamberController.openAllBoundariesAfterObjective(generation);
            Location core = coreCombatAnchorLocation();
            if (core != null) {
                spawnEventParticle(core, Particle.END_ROD, 36, 2.0D, 1.0D, 2.0D, 0.03D);
            }
            getLogger().info("END_RIFT_CHAMBERS_COMPLETE event=" + eventId
                    + " chambers=" + realitySplitChamberController.assignment().chamberCount());
        }
    }

    private int countLiveWaveEntitiesForChamber(int chamber) {
        int count = 0;
        for (Entity entity : ownedEntities.values()) {
            String kind = readString(entity, keyKind);
            if (isWaveCombatKind(kind)
                    && readInt(entity, keyWave, 0) == 7
                    && isLiveOwnedEntity(entity.getUniqueId())
                    && realitySplitChamberId(entity) == chamber) {
                count++;
            }
        }
        return count;
    }

    private int countCompletedRealitySplitChambers() {
        int count = 0;
        int chamberCount = realitySplitChamberController.assignment().chamberCount();
        for (int chamber = 0; chamber < chamberCount; chamber++) {
            if (realitySplitChamberController.chamberComplete(generation, chamber)) {
                count++;
            }
        }
        return count;
    }

    private void renderWaveObjective(long now) {
        Location core = coreCombatAnchorLocation();
        if (core == null) {
            return;
        }
        renderCurrentSafeZoneBeams(core);
        int objectiveWave = activeWave;
        if (objectiveWave == 5 && blackFogPhase == BlackFogPhase.FOG) {
            for (Player viewer : eventAudience()) {
                if (!isEventParticleViewer(viewer, core)) {
                    continue;
                }
                for (int level = 0; level < 3; level++) {
                    spawnPatternRing(viewer, core.clone().add(0.0D, level + 0.5D, 0.0D),
                            new Vector(1.0D, 0.0D, 0.0D), new Vector(0.0D, 0.0D, 1.0D),
                            18.0D - level * 1.3D, 18, now * 0.001D + level,
                            Particle.DRAGON_BREATH);
                }
            }
        } else if (objectiveWave == 6) {
            for (Player viewer : eventAudience()) {
                if (isEventParticleViewer(viewer, core)) {
                    spawnPatternRing(viewer, core.clone().add(0.0D, 0.12D, 0.0D),
                            new Vector(1.0D, 0.0D, 0.0D), new Vector(0.0D, 0.0D, 1.0D),
                            3.0D, 16, now * 0.001D, Particle.REVERSE_PORTAL);
                }
            }
        }
    }

    /**
     * Keep the actual Wave 5 safe-zone columns legible at the arena scale.
     * The emerald floor is the gameplay marker; this short-lived client beam
     * is only the vertical beacon and is removed as soon as the safe window
     * ends.  No world block is changed by this method.
     */
    private void renderCurrentSafeZoneBeams(Location core) {
        if (core == null || core.getWorld() == null
                || activeWave != 5 || blackFogPhase != BlackFogPhase.SAFE
                || currentSafeZoneCenters.isEmpty()) {
            clearWorldVfxBeamsByPrefix("wave4-safe-zone-");
            return;
        }
        Location floor = core.clone();
        floor.setY(combatFloorY() + 1.02D);
        Set<String> desired = new LinkedHashSet<>();
        for (Map.Entry<Integer, HazardPlanner.Point> entry : currentSafeZoneCenters.entrySet()) {
            HazardPlanner.Point point = entry.getValue();
            if (point == null || point.x() < arenaMinX || point.x() > arenaMaxX
                    || point.z() < arenaMinZ || point.z() > arenaMaxZ) {
                continue;
            }
            Location base = new Location(core.getWorld(), point.x() + 0.5D,
                    floor.getY(), point.z() + 0.5D);
            Location top = base.clone().add(0.0D, 3.0D, 0.0D);
            String key = "wave4-safe-zone-" + entry.getKey();
            desired.add(key);
            for (Player viewer : eventAudience()) {
                sendWorldBeamPacket(viewer, key, base, top, 0x54FF6A, 0.10F);
            }
        }
        clearWorldVfxBeamsOutside("wave4-safe-zone-", desired);
    }

    private void spawnCurrentSafeZoneVisuals(World world, Location core) {
        clearCurrentSafeZoneVisuals();
        if (world == null || core == null || currentFogZoneCount <= 0 || currentFogZoneSide <= 0) {
            return;
        }
        currentSafeZoneCenters.clear();
        Map<HazardPlanner.Point, String> barrierOriginals = new LinkedHashMap<>();
        double radius = Math.min(12.0D, Math.max(7.0D, config.arenaRadius() * 0.55D));
        for (int zone = 0; zone < currentFogZoneCount; zone++) {
            double angle = -Math.PI / 2.0D + zone * Math.PI * 2.0D
                    / Math.max(1, currentFogZoneCount) + currentFogCycle * 0.37D;
            int centerX = (int) Math.floor(core.getX() + Math.cos(angle) * radius);
            int centerZ = (int) Math.floor(core.getZ() + Math.sin(angle) * radius);
            int half = currentFogZoneSide / 2;
            int cellsBeforeZone = currentSafeZoneCells.size();
            for (int dx = -half; dx <= half; dx++) {
                for (int dz = -half; dz <= half; dz++) {
                    HazardPlanner.Point point = new HazardPlanner.Point(centerX + dx, centerZ + dz);
                    if (point.x() < arenaMinX || point.x() > arenaMaxX
                            || point.z() < arenaMinZ || point.z() > arenaMaxZ) {
                        continue;
                    }
                    Block floor = world.getBlockAt(point.x(), combatFloorY(), point.z());
                    if (!floor.getType().isSolid() || floor.isLiquid()
                            || isCoreBlockPosition(floor.getLocation())) {
                        continue;
                    }
                    currentSafeZoneCells.add(point);
                    currentTemporaryBlockOriginals.putIfAbsent(point,
                            floor.getBlockData().getAsString());
                }
            }
            // The perimeter is one block outside the safe floor.  A 1x1
            // zone therefore remains usable instead of being sealed inside
            // its own invisible wall.
            for (int dx = -half - 1; dx <= half + 1; dx++) {
                for (int dz = -half - 1; dz <= half + 1; dz++) {
                    if (Math.abs(dx) <= half && Math.abs(dz) <= half) {
                        continue;
                    }
                    HazardPlanner.Point point = new HazardPlanner.Point(centerX + dx, centerZ + dz);
                    if (currentSafeZoneCells.contains(point)
                            || point.x() < arenaMinX || point.x() > arenaMaxX
                            || point.z() < arenaMinZ || point.z() > arenaMaxZ
                            || point.x() == coreX && point.z() == coreZ) {
                        continue;
                    }
                    Block above = world.getBlockAt(point.x(), combatFloorY() + 1, point.z());
                    if (!above.isPassable() || above.isLiquid()) {
                        continue;
                    }
                    currentBarrierCells.add(point);
                    barrierOriginals.putIfAbsent(point, above.getBlockData().getAsString());
                }
            }
            if (currentSafeZoneCells.size() > cellsBeforeZone) {
                currentSafeZoneCenters.put(zone, new HazardPlanner.Point(centerX, centerZ));
            }
        }
        if (currentSafeZoneCells.isEmpty()) {
            return;
        }
        List<HazardMutationJournal.Entry> journalEntries = new ArrayList<>();
        for (HazardPlanner.Point point : currentSafeZoneCells) {
            String original = currentTemporaryBlockOriginals.get(point);
            if (original != null) {
                journalEntries.add(new HazardMutationJournal.Entry(
                        point.x(), combatFloorY(), point.z(), original, "", "EMERALD_BARRIER"));
            }
        }
        for (HazardPlanner.Point point : currentBarrierCells) {
            Block floor = world.getBlockAt(point.x(), combatFloorY(), point.z());
            String original = barrierOriginals.get(point);
            if (original != null) {
                journalEntries.add(new HazardMutationJournal.Entry(
                        point.x(), combatFloorY(), point.z(),
                        floor.getBlockData().getAsString(), original, "BARRIER"));
            }
        }
        HazardMutationJournal.Snapshot existingJournal = hazardJournal == null
                ? HazardMutationJournal.Snapshot.empty() : hazardJournal.load();
        boolean journalBusy = existingJournal.status() != HazardMutationJournal.Status.EMPTY
                && existingJournal.status() != HazardMutationJournal.Status.RESTORED
                && (!existingJournal.eventId().equals(eventId)
                || existingJournal.generation() != generation);
        if (journalBusy || hazardJournal == null
                || !hazardJournal.prepare(eventId, generation, world.getName(), journalEntries)) {
            getLogger().severe("END_RIFT_FOG_SAFE_BLOCKS_REFUSED event=" + eventId
                    + " reason=journal-prepare-failed-or-busy");
            currentSafeZoneCells.clear();
            currentBarrierCells.clear();
            currentTemporaryBlockOriginals.clear();
            return;
        }
        try {
            for (HazardMutationJournal.Entry entry : journalEntries) {
                if (entry.isEmeraldBarrierMutation()) {
                    world.getBlockAt(entry.x(), entry.floorY(), entry.z())
                            .setType(Material.EMERALD_BLOCK, false);
                } else if (entry.isBarrierMutation()) {
                    world.getBlockAt(entry.x(), entry.floorY() + 1, entry.z())
                            .setType(Material.BARRIER, false);
                }
            }
            if (!hazardJournal.markApplied()) {
                throw new IllegalStateException("safe-zone journal could not be marked APPLIED");
            }
        } catch (RuntimeException error) {
            getLogger().log(Level.SEVERE, "END_RIFT_FOG_SAFE_BLOCKS_APPLY_FAILED event=" + eventId, error);
            restoreCurrentSafeZoneBlocks();
            return;
        }
        for (HazardPlanner.Point point : currentSafeZoneCells) {
            Location origin = new Location(world, point.x() + 0.5D,
                    combatFloorY() + 1.0D, point.z() + 0.5D);
            BlockDisplay display = world.spawn(origin, BlockDisplay.class, value -> {
                value.setBlock(Material.EMERALD_BLOCK.createBlockData());
                value.setBrightness(new Display.Brightness(15, 15));
                value.setGravity(false);
                value.setInvulnerable(true);
                value.setPersistent(false);
                value.setTransformation(new Transformation(
                        new Vector3f(-0.48F, -0.96F, -0.48F), new AxisAngle4f(),
                        new Vector3f(0.96F, 0.16F, 0.96F), new AxisAngle4f()));
            });
            tag(display, EVENT_KIND_DISPLAY, 4, true);
            ownedEntities.put(display.getUniqueId(), display);
            waveObjectiveVisuals.add(display.getUniqueId());
            currentSafeZoneVisuals.add(display.getUniqueId());
        }
        getLogger().info("END_RIFT_FOG_SAFE_VISUALS event=" + eventId
                + " emerald_cells=" + currentSafeZoneCells.size()
                + " barrier_cells=" + currentBarrierCells.size() + " journaled=true");
    }

    private void clearCurrentSafeZoneVisuals() {
        restoreCurrentSafeZoneBlocks();
        for (UUID id : new HashSet<>(currentSafeZoneVisuals)) {
            Entity entity = ownedEntities.remove(id);
            if (entity == null) {
                entity = Bukkit.getEntity(id);
            }
            if (entity != null && entity.isValid()) {
                entity.remove();
            }
            waveObjectiveVisuals.remove(id);
        }
        currentSafeZoneVisuals.clear();
        currentSafeZoneCells.clear();
        currentSafeZoneCenters.clear();
        currentBarrierCells.clear();
    }

    /** Restore Current Wave 4 cells only through the durable generation journal. */
    private void restoreCurrentSafeZoneBlocks() {
        if (currentTemporaryBlockOriginals.isEmpty() || hazardJournal == null) {
            currentTemporaryBlockOriginals.clear();
            return;
        }
        HazardMutationJournal.Snapshot journal = hazardJournal.load();
        if (!journal.valid() || !journal.eventId().equals(eventId)
                || journal.generation() != generation
                || (journal.status() != HazardMutationJournal.Status.PREPARED
                && journal.status() != HazardMutationJournal.Status.APPLIED)) {
            currentTemporaryBlockOriginals.clear();
            return;
        }
        World world = Bukkit.getWorld(journal.world());
        if (world == null) {
            getLogger().severe("END_RIFT_FOG_SAFE_BLOCKS_RESTORE_BLOCKED event=" + eventId
                    + " reason=world-not-loaded journal=" + hazardJournal.path());
            return;
        }
        int restored = 0;
        int skipped = 0;
        for (HazardMutationJournal.Entry entry : journal.entries()) {
            if (entry.isEmeraldBarrierMutation()) {
                Block floor = world.getBlockAt(entry.x(), entry.floorY(), entry.z());
                if (floor.getType() == Material.EMERALD_BLOCK) {
                    restoreBlock(floor, entry.floorOriginal());
                    restored++;
                } else {
                    skipped++;
                }
            } else if (entry.isBarrierMutation()) {
                Block barrier = world.getBlockAt(entry.x(), entry.floorY() + 1, entry.z());
                if (barrier.getType() == Material.BARRIER) {
                    restoreBlock(barrier, entry.webOriginal());
                    restored++;
                } else {
                    skipped++;
                }
            }
        }
        if (!hazardJournal.markRestored()) {
            getLogger().severe("END_RIFT_FOG_SAFE_BLOCKS_RESTORE_JOURNAL_FAILED event=" + eventId
                    + " journal=" + hazardJournal.path());
        }
        getLogger().info("END_RIFT_FOG_SAFE_BLOCKS_RESTORED event=" + eventId
                + " restored=" + restored + " skipped=" + skipped);
        currentTemporaryBlockOriginals.clear();
    }

    private boolean isCurrentSafeZonePlayer(Player player) {
        if (player == null || player.getWorld() == null
                || !player.getWorld().getName().equals(worldName)) {
            return false;
        }
        HazardPlanner.Point point = new HazardPlanner.Point(player.getLocation().getBlockX(),
                player.getLocation().getBlockZ());
        return currentSafeZoneCells.contains(point)
                && Math.abs(player.getLocation().getY() - combatFloorY()) <= 2.0D;
    }

    private void applyBlackFogEffects(long now, Location core) {
        for (Player player : activeLivingPlayers()) {
            if (isCurrentSafeZonePlayer(player)) {
                continue;
            }
            long last = currentFogLastImpactAt.getOrDefault(player.getUniqueId(), 0L);
            if (now - last < 1_000L) {
                continue;
            }
            currentFogLastImpactAt.put(player.getUniqueId(), now);
            if (player.getHealth() > 4.0D) {
                player.setHealth(4.0D);
            }
            player.addPotionEffect(new PotionEffect(PotionEffectType.BLINDNESS,
                    15 * 20, 0, false, true, true));
            player.addPotionEffect(new PotionEffect(PotionEffectType.SLOWNESS,
                    4 * 20, 2, false, true, true));
            player.addPotionEffect(new PotionEffect(PotionEffectType.WITHER,
                    4 * 20, 0, false, true, true));
            player.spawnParticle(Particle.SQUID_INK,
                    player.getLocation().add(0.0D, 1.0D, 0.0D), 12,
                    0.5D, 0.8D, 0.5D, 0.01D);
        }
        for (Player viewer : eventAudience()) {
            if (!isEventParticleViewer(viewer, core)) {
                continue;
            }
            spawnPatternRing(viewer, core.clone().add(0.0D, 0.4D, 0.0D),
                    new Vector(1.0D, 0.0D, 0.0D), new Vector(0.0D, 0.0D, 1.0D),
                    18.0D, 24, now * 0.0012D, Particle.SQUID_INK);
        }
    }

    private void freezeWaveMobs(boolean frozen) {
        for (Entity entity : ownedEntities.values()) {
            if (!isWaveCombatKind(readString(entity, keyKind))
                    || readInt(entity, keyWave, 0) != 5
                    || !isLiveOwnedEntity(entity.getUniqueId())) {
                continue;
            }
            if (entity instanceof Mob mob) {
                mob.setAI(!frozen);
                if (frozen) {
                    mob.setVelocity(new Vector());
                }
            }
        }
    }

    private void spawnCurrentRingVisuals(World world, Location core) {
        if (world == null || core == null) {
            return;
        }
        for (int ring = 0; ring < EndRiftObjective.RING_COUNT; ring++) {
            final int ringIndex = ring;
            Set<UUID> group = new LinkedHashSet<>();
            double radius = 5.0D + ring * 4.0D;
            for (int index = 0; index < 20; index++) {
                double angle = index * Math.PI * 2.0D / 20.0D;
                Location origin = core.clone().add(Math.cos(angle) * radius,
                        0.45D + ringIndex * 0.12D, Math.sin(angle) * radius);
                BlockDisplay display = world.spawn(origin, BlockDisplay.class, value -> {
                    value.setBlock((ringIndex == 1 ? Material.PURPUR_BLOCK
                            : Material.CRYING_OBSIDIAN).createBlockData());
                    value.setBrightness(new Display.Brightness(15, 15));
                    value.setGravity(false);
                    value.setInvulnerable(true);
                    value.setPersistent(false);
                    value.setInterpolationDuration(5);
                    value.setTransformation(new Transformation(
                            new Vector3f(-0.28F, -0.12F, -0.08F), new AxisAngle4f(),
                            new Vector3f(0.56F, 0.24F, 0.16F), new AxisAngle4f()));
                });
                tag(display, EVENT_KIND_DISPLAY, 5, true);
                ownedEntities.put(display.getUniqueId(), display);
                waveObjectiveVisuals.add(display.getUniqueId());
                currentRingVisuals.add(display.getUniqueId());
                group.add(display.getUniqueId());
            }
            currentRingVisualGroups.put(ring, group);
        }
        getLogger().info("END_RIFT_RINGS_READY event=" + eventId + " rings=3 pieces=60");
    }

    private void teleportCurrentParticipantsToChambers(World world, Location core) {
        if (world == null || core == null || !realitySplitChamberController.owns(generation)) {
            return;
        }
        int count = realitySplitChamberController.assignment().chamberCount();
        for (Player player : activeLivingPlayers()) {
            int chamber = realitySplitChamberController.assignment().chamberByPlayer()
                    .getOrDefault(player.getUniqueId(), -1);
            if (chamber < 0 || chamber >= count) {
                continue;
            }
            double angle = ChamberIsolationPolicy.chamberCenterAngle(chamber, count);
            Location preferred = core.clone().add(Math.cos(angle) * 8.0D, 0.0D,
                    Math.sin(angle) * 8.0D);
            Location destination = findSafeCombatLocation(core, preferred,
                    boundedCombatRadius(config.arenaRadius()) - 1.0D,
                    MIN_WAVE_CORE_DISTANCE_BLOCKS, chamber);
            if (destination != null && player.getWorld().equals(world)) {
                player.teleport(destination);
                player.spawnParticle(Particle.REVERSE_PORTAL,
                        destination.clone().add(0.0D, 1.0D, 0.0D), 24,
                        0.5D, 0.8D, 0.5D, 0.02D);
            }
        }
        getLogger().info("END_RIFT_CHAMBERS_ASSIGNED event=" + eventId
                + " players=" + realitySplitChamberController.assignment().chamberByPlayer().size()
                + " chambers=" + count);
    }

    private void spawnPortalObjectiveVisuals(World world, List<Location> portals) {
        if (world == null || portals == null) {
            return;
        }
        List<UUID> portalModelIds = new ArrayList<>();
        for (int index = 0; index < portals.size(); index++) {
            Location location = portals.get(index);
            // Current communicates progress through the floor model, ring color,
            // sound and particles.  The old floating percentage display is
            // retained only for disposable local probes.
            if (!isOfficialAttempt()) {
                TextDisplay display = world.spawn(location.clone().add(0.0D, 0.15D, 0.0D), TextDisplay.class);
                display.setText("§5✦ ВРАТА РАЗЛОМА " + (index + 1) + "\n§7Захват: 0%\n§8Встаньте внутрь кольца");
                display.setBillboard(Display.Billboard.CENTER);
                display.setBrightness(new Display.Brightness(15, 15));
                display.setViewRange(48.0F);
                display.setSeeThrough(true);
                display.setShadowed(false);
                display.setDefaultBackground(false);
                display.setLineWidth(180);
                display.setPersistent(true);
                display.setInvulnerable(true);
                tag(display, EVENT_KIND_DISPLAY, 3, false);
                waveObjectiveVisuals.add(display.getUniqueId());
                waveObjectiveVisualTexts.put(display.getUniqueId(), display.getText());
            }
            for (Player viewer : eventAudience()) {
                renderPortalObjective(viewer, location, null, index, portals.size(), System.currentTimeMillis());
            }
        }
        for (Location location : portals) {
            portalModelIds.addAll(spawnPortalModelVisual(world, location));
        }
        wavePortalModelVisuals.put(3, portalModelIds);
        startPortalVisualAnimation(world);
    }

    /** Spawn the frame, recessed core and four shard accents as one tracked set. */
    private List<UUID> spawnPortalModelVisual(World world, Location portal) {
        if (world == null || portal == null) {
            return List.of();
        }
        List<UUID> ids = new ArrayList<>(3);
        ItemDisplay frame = spawnPortalModelLayer(world, portal, MODEL_PORTAL_OVERLAY,
                "end_event_portal", PortalVisualLayer.FRAME, 2.15F);
        ItemDisplay inner = spawnPortalModelLayer(world, portal, MODEL_PORTAL_INNER_OVERLAY,
                "end_event_portal_inner", PortalVisualLayer.INNER, 2.08F);
        ItemDisplay shards = spawnPortalModelLayer(world, portal, MODEL_PORTAL_SHARD_OVERLAY,
                "end_event_portal_shard", PortalVisualLayer.SHARD, 2.12F);
        for (ItemDisplay display : new ItemDisplay[] {frame, inner, shards}) {
            if (display != null) {
                ids.add(display.getUniqueId());
            }
        }
        return ids;
    }

    private ItemDisplay spawnPortalModelLayer(World world, Location portal, int modelData,
                                              String modelId, PortalVisualLayer layer,
                                              float scale) {
        if (world == null || portal == null || layer == null
                || portal.getWorld() == null || !world.equals(portal.getWorld())) {
            return null;
        }
        Location origin = portalDisplayOrigin(portal);
        if (origin == null) {
            return null;
        }
        ItemDisplay display = world.spawn(origin, ItemDisplay.class, entity -> {
            entity.setItemStack(overlayItem(modelData, modelId));
            entity.setBrightness(new Display.Brightness(15, 15));
            entity.setItemDisplayTransform(ItemDisplay.ItemDisplayTransform.NONE);
            entity.setBillboard(Display.Billboard.FIXED);
            entity.setViewRange(64.0F);
            entity.setDisplayWidth(3.0F);
            entity.setDisplayHeight(3.0F);
            entity.setPersistent(true);
            entity.setGravity(false);
            entity.setInvulnerable(true);
            entity.setShadowRadius(0.0F);
            entity.setTransformation(new Transformation(
                    new Vector3f(), new AxisAngle4f(),
                    new Vector3f(scale, scale, scale), new AxisAngle4f()));
        });
        tag(display, EVENT_KIND_DISPLAY, 3, false);
        wavePortalVisualLayers.put(display.getUniqueId(), layer);
        waveObjectiveVisuals.add(display.getUniqueId());
        return display;
    }

    private Location portalDisplayOrigin(Location portal) {
        World world = portal == null ? null : portal.getWorld();
        if (world == null) {
            return null;
        }
        // Each display is centered on the portal's block.  The Y coordinate
        // is the playable floor anchor, not the block above it.
        return new Location(world, Math.floor(portal.getX()) + 0.5D, portal.getY(),
                Math.floor(portal.getZ()) + 0.5D, portal.getYaw(), portal.getPitch());
    }

    private void startPortalVisualAnimation(World world) {
        cancelPortalVisualAnimation();
        if (world == null || taskRegistry == null || wavePortalModelVisuals
                .getOrDefault(3, List.of()).isEmpty()) {
            return;
        }
        long callbackGeneration = generation;
        portalVisualTask = Bukkit.getScheduler().runTaskTimer(this, () -> {
            if (taskRegistry == null || !taskRegistry.owns(callbackGeneration)
                    || (!testPortalVisualMode
                    && (phase != EventPhase.WAVE_3 || activeWave != 3))
                    || wavePortalModelVisuals.getOrDefault(3, List.of()).isEmpty()) {
                cancelPortalVisualAnimation();
                return;
            }
            animatePortalModelVisuals(System.currentTimeMillis());
        }, 0L, 5L);
        registerEncounterTask(portalVisualTask);
    }

    private void cancelPortalVisualAnimation() {
        if (portalVisualTask != null) {
            portalVisualTask.cancel();
            portalVisualTask = null;
        }
    }

    /** Gives the layered 3D portal a restrained pulse; the floor ring supplies the faster motion. */
    private void animatePortalModelVisuals(long now) {
        List<UUID> modelIds = wavePortalModelVisuals.getOrDefault(3, List.of());
        if (modelIds.isEmpty()) {
            return;
        }
        for (UUID modelId : modelIds) {
            Entity entity = ownedEntities.get(modelId);
            if (!(entity instanceof ItemDisplay display) || !display.isValid()) {
                continue;
            }
            PortalVisualLayer layer = wavePortalVisualLayers.getOrDefault(modelId,
                    PortalVisualLayer.FRAME);
            float baseScale = switch (layer) {
                case FRAME -> 2.15F;
                case INNER -> 2.08F;
                case SHARD -> 2.12F;
            };
            float pulse = 1.0F + (float) Math.sin(now * 0.004D + layer.ordinal() * 0.85D) * 0.03F;
            float rotation = layer == PortalVisualLayer.FRAME
                    ? 0.0F : (float) Math.sin(now * 0.0014D + layer.ordinal()) * 0.035F;
            display.setTransformation(new Transformation(
                    new Vector3f(), new AxisAngle4f(),
                    new Vector3f(baseScale * pulse, baseScale * pulse, baseScale * pulse),
                    layer == PortalVisualLayer.FRAME
                            ? new AxisAngle4f()
                            : new AxisAngle4f(rotation, 0.0F, 1.0F, 0.0F)));
        }
    }

    private void refreshPortalObjectiveVisuals(List<PortalCapturePolicy.PortalState> states) {
        if (states == null || states.isEmpty()) {
            return;
        }
        for (int index = 0; index < states.size(); index++) {
            PortalCapturePolicy.PortalState state = states.get(index);
            if (index >= wavePortals.getOrDefault(3, List.of()).size()) {
                break;
            }
            UUID visualId = waveObjectiveVisuals.stream()
                    .map(ownedEntities::get)
                    .filter(Objects::nonNull)
                    .filter(entity -> entity instanceof TextDisplay)
                    .map(Entity::getUniqueId)
                    .skip(index)
                    .findFirst()
                    .orElse(null);
            if (visualId == null) {
                continue;
            }
            Entity entity = ownedEntities.get(visualId);
            if (!(entity instanceof TextDisplay display) || !entity.isValid()) {
                continue;
            }
            int percent = (int) Math.min(100L,
                    state.progressMillis() * 100L / Math.max(1L, PortalCapturePolicy.CAPTURE_MILLIS));
            String text = state.completed()
                    ? "§a✦ ВРАТА РАЗЛОМА " + (index + 1) + "\n§aЗАПЕЧАТАНО"
                    : "§5✦ ВРАТА РАЗЛОМА " + (index + 1) + "\n§dЗахват: " + percent + "%\n§8Встаньте внутрь кольца";
            if (!text.equals(waveObjectiveVisualTexts.get(visualId))) {
                display.setText(text);
                waveObjectiveVisualTexts.put(visualId, text);
            }
            Location portal = wavePortals.getOrDefault(3, List.of()).get(index);
            for (Player viewer : eventAudience()) {
                renderPortalObjective(viewer, portal, state, index, states.size(), System.currentTimeMillis());
            }
        }
    }

    private Particle zoneParticle(String policyParticle) {
        String token = policyParticle == null ? "" : policyParticle.trim().toUpperCase(Locale.ROOT);
        int namespaceSeparator = token.lastIndexOf(':');
        if (namespaceSeparator >= 0 && namespaceSeparator + 1 < token.length()) {
            token = token.substring(namespaceSeparator + 1);
        }
        // Bukkit requires a DustOptions payload for both dust particle
        // variants. The shared renderer supplies that payload below, so the
        // transition palette safely uses the plain dust carrier here.
        if ("DUST_COLOR_TRANSITION".equals(token)) {
            return Particle.DUST;
        }
        try {
            return Particle.valueOf(token);
        } catch (IllegalArgumentException invalidParticle) {
            getLogger().warning("Unknown zone particle policy=" + policyParticle
                    + "; using END_ROD fallback");
            return Particle.END_ROD;
        }
    }

    private void spawnZoneRing(Player viewer, Location center, double radius, int points,
                               double phase, Particle particle, Particle.DustOptions dust) {
        if (viewer == null || center == null || center.getWorld() == null || particle == null
                || !viewer.isOnline() || !viewer.getWorld().equals(center.getWorld())
                || viewer.getLocation().distanceSquared(center) > 64.0D * 64.0D) {
            return;
        }
        int safePoints = Math.max(4, Math.min(48, points));
        recordParticleEmission(safePoints);
        for (int index = 0; index < safePoints; index++) {
            double angle = phase + Math.PI * 2.0D * index / safePoints;
            Location point = center.clone().add(Math.cos(angle) * radius,
                    0.0D, Math.sin(angle) * radius);
            if (particle == Particle.DUST) {
                viewer.spawnParticle(Particle.DUST, point, 1,
                        0.0D, 0.0D, 0.0D, 0.0D,
                        dust == null ? new Particle.DustOptions(Color.WHITE, 1.0F) : dust);
            } else {
                viewer.spawnParticle(particle, point, 1,
                        0.0D, 0.0D, 0.0D, 0.0D);
            }
        }
    }

    private void spawnZonePoint(Player viewer, Particle particle, Location point, int count,
                                Particle.DustOptions dust) {
        if (viewer == null || point == null || point.getWorld() == null || particle == null
                || !viewer.isOnline() || !viewer.getWorld().equals(point.getWorld())
                || viewer.getLocation().distanceSquared(point) > 64.0D * 64.0D) {
            return;
        }
        int safeCount = Math.max(1, Math.min(12, count));
        recordParticleEmission(safeCount);
        if (particle == Particle.DUST) {
            viewer.spawnParticle(Particle.DUST, point, safeCount,
                    0.08D, 0.02D, 0.08D, 0.0D,
                    dust == null ? new Particle.DustOptions(Color.WHITE, 1.0F) : dust);
        } else {
            viewer.spawnParticle(particle, point, safeCount,
                    0.08D, 0.02D, 0.08D, 0.0D);
        }
    }

    /**
     * Draw every transient zone from the same floor-anchored policy. The
     * renderer intentionally emits only viewer-scoped particles: it cannot
     * create an entity above the arena, alter a vanilla block, or flood
     * clients that are outside the event view distance.
     */
    private void renderZoneVisual(Player viewer, Location floor, ZoneVisualPolicy.ZoneState state, double radius, long now) {
        if (viewer == null || floor == null || floor.getWorld() == null
                || !isEventParticleViewer(viewer, floor)) {
            return;
        }
        ZoneVisualPolicy.Profile profile = ZoneVisualPolicy.profile(state);
        if (profile == null) {
            return;
        }
        double safeRadius = Math.max(0.45D, Math.min(4.5D, radius));
        Location anchor = floor.clone();
        anchor.setY(Math.floor(floor.getY()) + profile.floorY());
        Particle primary = zoneParticle(profile.primaryParticle());
        Particle accent = zoneParticle(profile.accentParticle());
        Particle.DustOptions dust = new Particle.DustOptions(
                Color.fromRGB(profile.colorRgb()),
                state == ZoneVisualPolicy.ZoneState.DANGER ? 1.20F : 0.95F);
        int outerPoints = Math.min(profile.ringPoints(),
                Math.max(12, Math.min(48, profile.particleBudget())));
        int innerPoints = Math.max(6, Math.min(24, outerPoints / 2));
        double phase = now * 0.002D + state.ordinal() * 0.73D;
        spawnZoneRing(viewer, anchor, safeRadius, outerPoints, phase, primary, dust);
        spawnZoneRing(viewer, anchor.clone().add(0.0D, 0.025D, 0.0D),
                safeRadius * 0.68D, innerPoints, -phase * 1.2D, accent, dust);
        int cornerMarkers = Math.max(2, Math.min(4, profile.particleBudget() / 8));
        for (int marker = 0; marker < cornerMarkers; marker++) {
            double angle = phase + Math.PI * 2.0D * marker / cornerMarkers;
            Location start = anchor.clone().add(Math.cos(angle) * safeRadius * 0.76D,
                    0.02D, Math.sin(angle) * safeRadius * 0.76D);
            Location end = start.clone().add(0.0D, 0.22D, 0.0D);
            spawnPatternSegment(viewer, start, end, accent, dust);
        }
        spawnZonePoint(viewer, primary, anchor.clone().add(0.0D, 0.035D, 0.0D),
                Math.min(8, Math.max(3, profile.particleBudget() / 5)), dust);
        // Keep the vectors explicit: the ring is a horizontal floor marker,
        // never a pillar that could be mistaken for a floating rune.
        if (safeRadius >= 1.0D) {
            spawnZoneRing(viewer, anchor.clone().add(0.0D, 0.045D, 0.0D),
                    safeRadius * 0.36D, Math.min(16, innerPoints), phase * 0.7D,
                    Particle.DUST, dust);
        }
    }

    /** Renders a portal as a floor ring with a moving vertical rift, not a floating icon. */
    private void renderPortalObjective(Player viewer, Location portal,
                                       PortalCapturePolicy.PortalState state,
                                       int index, int total, long now) {
        if (viewer == null || portal == null || portal.getWorld() == null
                || !isEventParticleViewer(viewer, portal)) {
            return;
        }
        boolean complete = state != null && state.completed();
        boolean occupied = state != null && state.lastOccupiedMillis() >= 0L
                && now - state.lastOccupiedMillis() <= PortalCapturePolicy.GRACE_MILLIS;
        ZoneVisualPolicy.ZoneState zoneState = complete
                ? ZoneVisualPolicy.ZoneState.COMPLETED
                : occupied ? ZoneVisualPolicy.ZoneState.OCCUPIED
                : ZoneVisualPolicy.ZoneState.FREE;
        renderZoneVisual(viewer, portal, zoneState, 2.15D, now);
        Color color = complete ? Color.fromRGB(92, 255, 174) : Color.fromRGB(190, 76, 255);
        Particle rift = complete ? Particle.END_ROD : Particle.REVERSE_PORTAL;
        Particle.DustOptions dust = new Particle.DustOptions(color, complete ? 1.2F : 1.05F);
        Location floor = portal.clone().add(0.0D, 0.08D, 0.0D);
        Vector x = new Vector(1.0D, 0.0D, 0.0D);
        Vector z = new Vector(0.0D, 0.0D, 1.0D);
        double spin = now * 0.002D + index * 0.9D;
        spawnPatternRing(viewer, floor, x, z, 2.15D, PORTAL_VISUAL_POINTS, spin, rift);
        spawnPatternRing(viewer, floor.clone().add(0.0D, 0.48D, 0.0D), x, z,
                1.25D, 12, -spin * 1.25D, complete ? Particle.END_ROD : Particle.FLAME);
        for (int arc = 0; arc < 5; arc++) {
            double angle = spin + arc * Math.PI * 0.4D;
            Location base = floor.clone().add(Math.cos(angle) * 1.45D, 0.0D,
                    Math.sin(angle) * 1.45D);
            Location top = base.clone().add(0.0D, complete ? 1.9D : 1.45D, 0.0D);
            spawnPatternSegment(viewer, base, top, rift, dust);
        }
        viewer.spawnParticle(Particle.DUST, floor.clone().add(0.0D, 0.1D, 0.0D),
                complete ? 8 : 5, 0.18D, 0.06D, 0.18D, 0.0D, dust);
    }

    private int countLiveWaveEntitiesForWave(int wave) {
        int count = 0;
        for (Entity entity : ownedEntities.values()) {
            String kind = readString(entity, keyKind);
            if (isWaveCombatKind(kind)
                    && readInt(entity, keyWave, 0) == wave
                    && isLiveOwnedEntity(entity.getUniqueId())) {
                count++;
            }
        }
        return count;
    }

    private void updateCorePulseObjective(long now) {
        Location core = coreCombatAnchorLocation();
        if (core == null) {
            return;
        }
        if (now >= nextWaveOneZoneVisualMillis) {
            renderWaveOneArenaZones(core, now);
            nextWaveOneZoneVisualMillis = now + WAVE_ONE_ZONE_RENDER_INTERVAL_TICKS * 50L;
        }
        if (waveOnePulseDeadlineMillis <= 0L && now >= waveOneNextPulseMillis) {
            waveOnePulseDeadlineMillis = now + WAVE_ONE_PULSE_TELEGRAPH_TICKS * 50L;
            announceEventTitle("§4ПУЛЬС ЯДРА", "§fЗаймите безопасный сектор — удар через 2,5 сек.", true);
            getLogger().info("WAVE_OBJECTIVE_TELEGRAPH event=" + eventId
                    + " wave=1 type=CORE_PULSE pulse=" + waveOnePulseIndex);
        }
        if (waveOnePulseDeadlineMillis > 0L) {
            boolean impact = now >= waveOnePulseDeadlineMillis;
            for (Player player : eventAudience()) {
                if (!player.getWorld().equals(core.getWorld())
                        || horizontalDistanceSquared(player.getLocation(), core)
                        > config.arenaRadius() * config.arenaRadius()) {
                    continue;
                }
                boolean safe = isWaveOneSafeSector(player.getLocation(), core, waveOnePulseIndex);
                player.spawnParticle(safe ? Particle.END_ROD : Particle.DRAGON_BREATH,
                        player.getLocation().add(0.0D, 0.15D, 0.0D), impact ? 16 : 6,
                        0.45D, 0.1D, 0.45D, 0.02D);
                if (impact && !safe) {
                    player.damage(WAVE_ONE_PULSE_DAMAGE);
                    player.addPotionEffect(new PotionEffect(PotionEffectType.SLOWNESS,
                            WaveScalingPolicy.effectDurationTicks(SLOWNESS_DEBUFF_TICKS,
                                    eventScalePlayers()), 1, false, true, true));
                }
            }
            if (impact) {
                core.getWorld().playSound(core, Sound.BLOCK_RESPAWN_ANCHOR_DEPLETE, 0.9F, 0.65F);
                waveOnePulseDeadlineMillis = 0L;
                waveOnePulseIndex++;
                waveOneNextPulseMillis = now + randomSeconds(18, 22) * 1000L;
                getLogger().info("WAVE_OBJECTIVE_IMPACT event=" + eventId
                        + " wave=1 type=CORE_PULSE damage=" + WAVE_ONE_PULSE_DAMAGE
                        + " next_ms=" + waveOneNextPulseMillis);
            }
        }
    }

    private boolean isWaveOneSafeSector(Location player, Location core, int pulse) {
        double angle = Math.atan2(player.getZ() - core.getZ(), player.getX() - core.getX());
        int sector = Math.floorMod((int) Math.floor((angle + Math.PI) / (Math.PI / 2.0D)), 4);
        return sector == Math.floorMod(pulse, 4);
    }

    private void updateMarkedTargetObjective(long now) {
        if (waveTwoMarkedPlayerUuid == null || now >= waveTwoMarkDeadlineMillis) {
            if (now >= waveTwoNextMarkMillis) {
                List<Player> candidates = activeLivingPlayers();
                if (!candidates.isEmpty()) {
                    Player marked = candidates.get(Math.floorMod(waveTargetCursor++, candidates.size()));
                    waveTwoMarkedPlayerUuid = marked.getUniqueId();
                    int markRevealTicks = WaveScalingPolicy.effectDurationTicks(
                            WAVE_TWO_MARK_REVEAL_TICKS, eventScalePlayers());
                    int markDurationTicks = WaveScalingPolicy.effectDurationTicks(
                            WAVE_TWO_MARK_DURATION_TICKS, eventScalePlayers());
                    waveTwoMarkRevealDeadlineMillis = now + markRevealTicks * 50L;
                    waveTwoMarkDeadlineMillis = now + markDurationTicks * 50L;
                    marked.addPotionEffect(new PotionEffect(PotionEffectType.GLOWING,
                            markRevealTicks, 0, false, true, true));
                    marked.addPotionEffect(new PotionEffect(PotionEffectType.SPEED,
                            markRevealTicks, 0, false, true, true));
                    marked.addPotionEffect(new PotionEffect(PotionEffectType.RESISTANCE,
                            markRevealTicks, 0, false, true, true));
                    marked.playSound(marked.getLocation(), Sound.ENTITY_ENDERMAN_STARE, 0.8F, 1.35F);
                    getLogger().info("WAVE_OBJECTIVE_MARK event=" + eventId + " wave=2 player="
                            + marked.getUniqueId() + " deadline=" + waveTwoMarkDeadlineMillis);
                }
                waveTwoNextMarkMillis = now + randomSeconds(12, 16) * 1000L;
            }
            return;
        }
        Player marked = Bukkit.getPlayer(waveTwoMarkedPlayerUuid);
        if (marked == null || !isCombatTarget(marked)) {
            waveTwoMarkedPlayerUuid = null;
            return;
        }
        if (now < waveTwoMarkRevealDeadlineMillis) {
            marked.spawnParticle(Particle.END_ROD, marked.getLocation().add(0.0D, 1.0D, 0.0D),
                    8, 0.35D, 0.6D, 0.35D, 0.02D);
        }
    }

    /** Keep wave one readable from the first tick: four safe-sector beacons. */
    private void renderWaveOneArenaZones(Location core, long now) {
        if (core == null || core.getWorld() == null) {
            return;
        }
        Location floor = core.clone();
        floor.setY(combatFloorY() + 1.05D);
        double spin = now * 0.0012D;
        Particle.DustOptions cyan = new Particle.DustOptions(Color.fromRGB(69, 218, 255), 1.15F);
        Particle.DustOptions violet = new Particle.DustOptions(Color.fromRGB(190, 76, 255), 1.05F);
        for (Player viewer : eventAudience()) {
            if (!isEventParticleViewer(viewer, floor)) {
                continue;
            }
            spawnPatternRing(viewer, floor, new Vector(1.0D, 0.0D, 0.0D),
                    new Vector(0.0D, 0.0D, 1.0D), 2.25D, 24, -spin, Particle.END_ROD);
            for (int sector = 0; sector < 4; sector++) {
                double start = -Math.PI + sector * Math.PI / 2.0D + spin;
                double end = start + Math.PI / 2.0D;
                spawnPatternArc(viewer, floor, WAVE_ONE_ZONE_RADIUS_BLOCKS,
                        start, end, WAVE_ONE_ZONE_POINTS_PER_SECTOR, Particle.DUST, cyan);
                Location inner = floor.clone().add(0.0D, 0.04D, 0.0D);
                spawnPatternArc(viewer, inner, 4.5D, start, end, 6, Particle.DUST, violet);
                Location boundaryStart = floor.clone().add(
                        Math.cos(start) * 2.2D, 0.03D, Math.sin(start) * 2.2D);
                Location boundaryEnd = floor.clone().add(
                        Math.cos(start) * WAVE_ONE_ZONE_RADIUS_BLOCKS, 0.03D,
                        Math.sin(start) * WAVE_ONE_ZONE_RADIUS_BLOCKS);
                spawnPatternSegment(viewer, boundaryStart, boundaryEnd,
                        Particle.END_ROD, cyan);
            }
        }
    }

    private void spawnPatternArc(Player player, Location center, double radius,
                                 double startAngle, double endAngle, int points,
                                 Particle particle, Particle.DustOptions dust) {
        if (player == null || center == null || center.getWorld() == null || !player.isOnline()
                || !player.getWorld().equals(center.getWorld())
                || player.getLocation().distanceSquared(center) > 64.0D * 64.0D) {
            return;
        }
        int safePoints = Math.max(2, points);
        recordParticleEmission(safePoints * (particle == Particle.DUST && dust != null ? 1 : 1));
        for (int index = 0; index < safePoints; index++) {
            double progress = index / (double) (safePoints - 1);
            double angle = startAngle + (endAngle - startAngle) * progress;
            Location point = center.clone().add(Math.cos(angle) * radius,
                    0.0D, Math.sin(angle) * radius);
            if (particle == Particle.DUST) {
                player.spawnParticle(Particle.DUST, point, 1,
                        0.0D, 0.0D, 0.0D, 0.0D,
                        dust == null ? new Particle.DustOptions(Color.WHITE, 1.0F) : dust);
            } else {
                player.spawnParticle(particle, point, 1,
                        0.0D, 0.0D, 0.0D, 0.0D);
            }
        }
    }

    private void updatePortalObjective(long now) {
        boolean wasComplete = waveObjectiveComplete;
        boolean traceProgress = now >= portalCaptureTraceAtMillis;
        List<Location> portals = wavePortals.getOrDefault(3, List.of());
        List<PortalCapturePolicy.PortalState> states = portalCaptureStates.getOrDefault(3, List.of());
        if (portals.size() != states.size() || portals.isEmpty()) {
            waveObjectiveComplete = false;
            return;
        }
        boolean sequential = isOfficialAttempt() && activeWave == 3;
        int currentPortal = -1;
        if (sequential) {
            for (int index = 0; index < states.size(); index++) {
                if (!states.get(index).completed()) {
                    currentPortal = index;
                    break;
                }
            }
        }
        List<PortalCapturePolicy.PortalState> updated = new ArrayList<>();
        int completed = 0;
        for (int index = 0; index < portals.size(); index++) {
            Location portal = portals.get(index);
            boolean active = !sequential || index == currentPortal;
            boolean occupied = active && activeLivingPlayers().stream().anyMatch(player ->
                    horizontalDistanceSquared(player.getLocation(), portal) <= 2.5D * 2.5D
                            && Math.abs(player.getLocation().getY() - portal.getY()) <= 1.5D);
            PortalCapturePolicy.PortalState state = active
                    ? PortalCapturePolicy.tick(states.get(index), occupied, now,
                    config.portalCaptureDecayRate())
                    : states.get(index);
            updated.add(state);
            if (traceProgress) {
                int percent = (int) Math.min(100L,
                        state.progressMillis() * 100L / Math.max(1L, PortalCapturePolicy.CAPTURE_MILLIS));
                getLogger().info("PORTAL_CAPTURE_PROGRESS event=" + eventId
                        + " wave=3 index=" + index
                        + " occupied=" + occupied
                        + " progress_ms=" + state.progressMillis()
                        + " percent=" + percent
                        + " completed=" + state.completed()
                        + " decay_rate=" + config.portalCaptureDecayRate());
            }
            if (state.completed()) {
                completed++;
            }
            for (Player player : eventAudience()) {
                if (player.getWorld().equals(portal.getWorld())) {
                    renderPortalObjective(player, portal, state, index, portals.size(), now);
                    player.spawnParticle(state.completed() ? Particle.END_ROD : Particle.REVERSE_PORTAL,
                            portal.clone().add(0.0D, 0.2D, 0.0D), occupied ? 8 : 3,
                            0.45D, 0.15D, 0.45D, 0.02D);
                }
            }
        }
        portalCaptureStates.put(3, updated);
        if (traceProgress) {
            portalCaptureTraceAtMillis = now + 1_000L;
        }
        refreshPortalObjectiveVisuals(updated);
        waveObjectiveComplete = completed == portals.size();
        if (waveObjectiveComplete && !wasComplete) {
            announceEventTitle("§aПОРТАЛЫ ЗАПЕЧАТАНЫ", "§fПобедите оставшихся слуг Разлома", true);
            getLogger().info("WAVE_OBJECTIVE_COMPLETE event=" + eventId
                    + " wave=3 type=PORTALS completed=" + completed
                    + " portals=" + portals.size()
                    + " capture_ms=" + PortalCapturePolicy.CAPTURE_MILLIS);
        }
    }

